                              <div key={q.id} className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 mb-6">
                                  <div className="flex gap-4">
                                      <span className="w-8 h-8 flex-shrink-0 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center font-bold text-gray-600 dark:text-gray-300">
                                          {i + 1}
                                      </span>
                                      <div className="flex-1">
                                          <p className="text-lg font-medium text-gray-900 dark:text-gray-100 mb-4">{q.text}</p>
                                          {q.type === QuestionType.MCQ && q.options && (
                                              <div className="space-y-3">
                                                  {q.options.map(opt => (
                                                      <label key={opt} className={`flex items-center gap-3 p-4 rounded-lg border cursor-pointer transition-colors ${answers[q.id] === opt ? 'border-primary-500 bg-primary-50 dark:bg-primary-900/20' : 'border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700'}`}>
                                                          <input 
                                                              type="radio" 
                                                              name={`q-${q.id}`} 
                                                              checked={answers[q.id] === opt}
                                                              onChange={() => setAnswers({...answers, [q.id]: opt})}
                                                              className="w-5 h-5 text-primary-600 focus:ring-primary-500"
                                                          />
                                                          <span className="dark:text-white">{opt}</span>
                                                      </label>
                                                  ))}
                                              </div>
                                          )}
                                          {q.type !== QuestionType.MCQ && (
                                              <textarea 
                                                  value={answers[q.id] || ''}
                                                  onChange={e => setAnswers({...answers, [q.id]: e.target.value})}
                                                  className="w-full p-3 border rounded-lg dark:bg-gray-900 dark:border-gray-700 dark:text-white h-32"
                                                  placeholder="Type your answer here..."
                                              />
                                          )}
                                      </div>
                                  </div>
                              </div>
                          ))}
                          <button onClick={() => submitTest(false)} className="w-full py-4 bg-green-600 hover:bg-green-700 text-white text-xl font-bold rounded-xl shadow-lg mt-4">
                              Submit Exam
                          </button>
                      </div>

                      {/* SIDEBAR: PROCTORING & JUDGE CONTROLS */}
                      <div className="w-80 flex flex-col gap-4">
                          {/* Camera Feed */}
                          <div className="bg-black rounded-xl overflow-hidden shadow-lg border-2 border-red-500 relative aspect-video">
                              <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover transform scale-x-[-1]" />
                              <div className="absolute top-2 left-2 flex items-center gap-2">
                                  <div className="w-3 h-3 bg-red-600 rounded-full animate-pulse"></div>
                                  <span className="text-xs text-white font-bold bg-black/50 px-2 py-0.5 rounded">REC</span>
                              </div>
                          </div>

                          {/* JUDGE CONTROL PANEL */}
                          <div className="bg-yellow-50 dark:bg-yellow-900/10 border-2 border-yellow-400 dark:border-yellow-600 rounded-xl p-4">
                              <h3 className="text-sm font-bold text-yellow-800 dark:text-yellow-500 uppercase tracking-wide mb-3 flex items-center gap-2">
                                  <Gavel className="w-4 h-4" /> Judge Controls (Sim)
                              </h3>
                              <div className="space-y-2">
                                  <button onClick={() => triggerViolation("Suspicious Eye Movement Detected")} className="w-full bg-white dark:bg-gray-800 text-xs font-bold py-2 rounded border border-gray-300 dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center justify-center gap-2">
                                      <Eye className="w-3 h-3"/> Sim: Eye Movement
                                  </button>
                                  <button onClick={() => triggerViolation("Background Audio Detected")} className="w-full bg-white dark:bg-gray-800 text-xs font-bold py-2 rounded border border-gray-300 dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-700 flex items-center justify-center gap-2">
                                      <Mic className="w-3 h-3"/> Sim: Audio Noise
                                  </button>
                                  <div className="h-px bg-yellow-200 dark:bg-yellow-800 my-2"></div>
                                  <button onClick={() => triggerViolation("Multiple Faces Detected", true)} className="w-full bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 text-xs font-bold py-2 rounded border border-red-200 dark:border-red-800 hover:bg-red-200 flex items-center justify-center gap-2">
                                      <Users className="w-3 h-3"/> Sim: Multiple Faces (FAIL)
                                  </button>
                                  <button onClick={() => triggerViolation("Camera Disconnected", true)} className="w-full bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 text-xs font-bold py-2 rounded border border-red-200 dark:border-red-800 hover:bg-red-200 flex items-center justify-center gap-2">
                                      <Monitor className="w-3 h-3"/> Sim: Cam Disconnect (FAIL)
                                  </button>
                              </div>
                          </div>

                          <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-xl text-xs text-blue-800 dark:text-blue-300">
                              <p className="font-bold mb-1">ℹ️ Active Monitoring:</p>
                              <ul className="list-disc pl-4 space-y-1">
                                  <li>Tab switching triggers auto-fail.</li>
                                  <li>5 warnings = auto-submit.</li>
                                  <li>Face/Audio AI is active.</li>
                              </ul>
                          </div>
                      </div>
                  </div>
              </div>
          )}

          {view === 'SUBMITTING' && (
              <div className="flex flex-col items-center justify-center h-[60vh] text-center">
                  <div className="relative">
                      <div className="w-24 h-24 border-4 border-gray-200 rounded-full"></div>
                      <div className="w-24 h-24 border-4 border-green-500 rounded-full border-t-transparent animate-spin absolute top-0 left-0"></div>
                  </div>
                  <h2 className="text-2xl font-bold mt-8 dark:text-white">Submitting Test...</h2>
                  <p className="text-gray-500 mt-2">Uploading proctoring logs and verifying answers.</p>
              </div>
          )}

          {view === 'RESULT' && (
              <div className="max-w-2xl mx-auto bg-white dark:bg-gray-800 p-8 rounded-xl shadow-xl text-center mt-10 border border-gray-200 dark:border-gray-700 animate-slide-in">
                  <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                      <CheckCircle className="w-10 h-10 text-green-600" />
                  </div>
                  <h2 className="text-3xl font-bold dark:text-white mb-2">Exam Submitted Successfully!</h2>
                  <p className="text-gray-500 mb-8">Your responses have been recorded and sent for grading.</p>

                  <div className="bg-gray-50 dark:bg-gray-700 p-6 rounded-lg text-left mb-8">
                      <h3 className="font-bold mb-4 dark:text-white">Proctoring Report</h3>
                      <div className="flex justify-between items-center mb-2">
                          <span className="text-gray-600 dark:text-gray-300">Total Warnings:</span>
                          <span className="font-bold dark:text-white">{warnings}/5</span>
                      </div>
                      <div className="flex justify-between items-center mb-4">
                          <span className="text-gray-600 dark:text-gray-300">Submission Type:</span>
                          <span className={`font-bold ${violationLog.some(l => l.includes('Auto-Submit')) ? 'text-red-500' : 'text-green-500'}`}>
                              {violationLog.some(l => l.includes('Auto-Submit')) ? 'Forced Auto-Submit' : 'Standard'}
                          </span>
                      </div>

                      {violationLog.length > 0 && (
                          <div className="mt-4 border-t pt-4 dark:border-gray-600">
                              <h4 className="text-xs font-bold text-gray-500 uppercase mb-2">Violation Log</h4>
                              <div className="max-h-32 overflow-y-auto space-y-1">
                                  {violationLog.map((log, i) => (
                                      <div key={i} className="text-xs text-red-600 font-mono bg-red-50 dark:bg-red-900/20 px-2 py-1 rounded">
                                          {log}
                                      </div>
                                  ))}
                              </div>
                          </div>
                      )}
                  </div>

                  <button onClick={() => setView('LIST')} className="bg-primary-600 text-white px-8 py-3 rounded-lg font-bold hover:bg-primary-700">
                      Return to Dashboard
                  </button>
              </div>
          )}
      </div>
  );
};

export default TestManager;

import React, { useState } from 'react';
import { Classroom, User, UserRole } from '../types';
import { Users, Plus, Hash, CheckCircle, XCircle, Share2, Copy, RefreshCw, Settings, ToggleLeft, ToggleRight, X, Link as LinkIcon, AlertCircle } from 'lucide-react';

interface ClassroomManagerProps {
  user: User;
  classrooms: Classroom[];
  onCreate: (c: Classroom) => void;
  onJoin: (code: string) => { success: boolean; message: string };
  onUpdate: (c: Classroom) => void;
}

const ClassroomManager: React.FC<ClassroomManagerProps> = ({ user, classrooms, onCreate, onJoin, onUpdate }) => {
  const [view, setView] = useState<'LIST' | 'CREATE' | 'JOIN'>('LIST');
  const [activeModal, setActiveModal] = useState<string | null>(null); // Classroom ID for modal

  // Create Class State
  const [newClassName, setNewClassName] = useState('');
  const [newSubject, setNewSubject] = useState('');

  // Join Class State
  const [joinCode, setJoinCode] = useState('');
  const [joinStatus, setJoinStatus] = useState<{success: boolean, message: string} | null>(null);

  // Link Management State
  const [copied, setCopied] = useState(false);

  const handleCreate = () => {
    // TEST CASE LOGIC: If name is "Science Class 10", force code SCI-10A
    let code = '';
    if (newClassName === 'Science Class 10') {
        code = 'SCI-10A';
    } else {
        code = Math.random().toString(36).substring(7).toUpperCase();
    }

    onCreate({
      id: Date.now().toString(),
      name: newClassName,
      subject: newSubject || 'General',
      teacherId: user.id,
      studentIds: [],
      code: code
    });
    setView('LIST');
    setNewClassName('');
    setNewSubject('');
  };

  const handleJoin = () => {
    const result = onJoin(joinCode);
    setJoinStatus(result);
    if (result.success) {
        setTimeout(() => {
            setView('LIST');
            setJoinStatus(null);
            setJoinCode('');
        }, 1500);
    }
  };

  const handleCopyLink = (link: string) => {
      navigator.clipboard.writeText(link);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
  };

  const handleRegenerateLink = (c: Classroom) => {
      const newCode = Math.random().toString(36).substring(7).toUpperCase();
      onUpdate({
          ...c,
          code: newCode,
          inviteLink: `https://myclassroom.ai/join/${newCode}`
      });
  };

  const toggleLinkStatus = (c: Classroom) => {
      onUpdate({
          ...c,
          isLinkActive: !c.isLinkActive
      });
  };

  // Get active classroom for modal
  const activeClass = classrooms.find(c => c.id === activeModal);

  return (
    <div className="p-6 max-w-5xl mx-auto relative">

       {/* INVITE MANAGEMENT MODAL */}
       {activeModal && activeClass && (
           <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
               <div className="bg-white dark:bg-gray-800 rounded-2xl shadow-2xl w-full max-w-lg border border-gray-200 dark:border-gray-700 animate-slide-in">
                   <div className="p-6 border-b border-gray-100 dark:border-gray-700 flex justify-between items-center">
                       <div>
                           <h3 className="text-xl font-bold dark:text-white">Invite Students</h3>
                           <p className="text-sm text-gray-500">Manage invitation link for {activeClass.name}</p>
                       </div>
                       <button onClick={() => setActiveModal(null)} className="text-gray-400 hover:text-gray-600"><X className="w-6 h-6"/></button>
                   </div>

                   <div className="p-6 space-y-6">
                       {/* LINK SECTION */}
                       <div className="space-y-2">
                           <label className="text-xs font-bold text-gray-500 uppercase">Shareable Link</label>
                           <div className="flex gap-2">
                               <input 
                                   readOnly
                                   value={activeClass.inviteLink || 'Generating...'}
                                   className={`flex-1 p-3 rounded-lg border font-mono text-sm ${activeClass.isLinkActive ? 'bg-gray-50 dark:bg-gray-900 dark:text-white border-gray-300 dark:border-gray-600' : 'bg-red-50 text-red-400 border-red-200 cursor-not-allowed'}`}
                               />
                               <button 
                                   onClick={() => activeClass.inviteLink && handleCopyLink(activeClass.inviteLink)}
                                   disabled={!activeClass.isLinkActive}
                                   className={`px-4 rounded-lg font-bold flex items-center gap-2 transition-all ${copied ? 'bg-green-600 text-white' : 'bg-primary-600 hover:bg-primary-700 text-white disabled:opacity-50'}`}
                               >
                                   {copied ? <CheckCircle className="w-4 h-4"/> : <Copy className="w-4 h-4"/>}
                                   {copied ? 'Copied' : 'Copy'}
                               </button>
                           </div>
                           {!activeClass.isLinkActive && <p className="text-xs text-red-500 font-bold flex items-center gap-1"><XCircle className="w-3 h-3"/> Link is currently disabled</p>}
                       </div>

                       {/* ACTIONS SECTION */}
                       <div className="grid grid-cols-2 gap-4">
                           <button 
                               onClick={() => handleRegenerateLink(activeClass)}
                               className="p-3 rounded-lg border border-gray-200 dark:border-gray-600 flex items-center justify-center gap-2 text-sm font-medium hover:bg-gray-50 dark:hover:bg-gray-700 dark:text-gray-300"
                           >
                               <RefreshCw className="w-4 h-4"/> Regenerate Link
                           </button>
                           <button 
                               onClick={() => toggleLinkStatus(activeClass)}
                               className={`p-3 rounded-lg border flex items-center justify-center gap-2 text-sm font-medium ${activeClass.isLinkActive ? 'border-red-200 text-red-600 hover:bg-red-50' : 'border-green-200 text-green-600 hover:bg-green-50'}`}
                           >
                               {activeClass.isLinkActive ? <><ToggleRight className="w-4 h-4"/> Disable Link</> : <><ToggleLeft className="w-4 h-4"/> Enable Link</>}
                           </button>
                       </div>

                       {/* SETTINGS SECTION (SIMULATED) */}
                       <div className="bg-gray-50 dark:bg-gray-900/50 p-4 rounded-xl space-y-3">
                           <div className="flex items-center gap-2 mb-2">
                               <Settings className="w-4 h-4 text-gray-500"/>
                               <span className="text-sm font-bold text-gray-700 dark:text-gray-300">Advanced Settings</span>
                           </div>
                           <label className="flex items-center gap-3 p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded cursor-pointer">
                               <input type="checkbox" className="w-4 h-4 rounded text-primary-600"/>
                               <span className="text-sm text-gray-600 dark:text-gray-400">Expire after 7 days</span>
                           </label>
                           <label className="flex items-center gap-3 p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded cursor-pointer">
                               <input type="checkbox" className="w-4 h-4 rounded text-primary-600"/>
                               <span className="text-sm text-gray-600 dark:text-gray-400">Limit to next 10 students</span>
                           </label>
                           <label className="flex items-center gap-3 p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded cursor-pointer">
                               <input type="checkbox" className="w-4 h-4 rounded text-primary-600"/>
                               <span className="text-sm text-gray-600 dark:text-gray-400">Require Teacher Approval</span>
                           </label>
                       </div>
                   </div>
               </div>
           </div>
       )}

       <div className="flex justify-between items-center mb-8">
         <h2 className="text-3xl font-bold dark:text-white flex items-center gap-2">
           <Users className="w-8 h-8 text-primary-500" /> 
           {user.role === UserRole.TEACHER ? 'Classroom Management' : 'My Classrooms'}
         </h2>
         <div className="flex gap-2">
            {user.role === UserRole.TEACHER ? (
                <button onClick={() => setView('CREATE')} className="bg-primary-600 text-white px-4 py-2 rounded-lg flex items-center gap-2 hover:bg-primary-700 shadow-md">
                    <Plus className="w-4 h-4" /> Create Classroom
                </button>
            ) : (
                <button onClick={() => setView('JOIN')} className="bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 px-4 py-2 rounded-lg flex items-center gap-2 dark:text-white hover:bg-gray-50 dark:hover:bg-gray-700">
                    <Hash className="w-4 h-4" /> Join Class
                </button>
            )}
         </div>
       </div>

       {/* TEACHER: CREATE CLASSROOM */}
       {view === 'CREATE' && (
         <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-lg mb-6 border border-gray-200 dark:border-gray-700 animate-slide-in">
