            title: 'Photosynthesis Practice Test',
            subject: 'Biology',
            creatorId: 'SYSTEM',
            status: 'LIVE',
            accessCode: '123456',
            settings: { timeLimitMinutes: 10, proctoring: true, adaptive: false, shuffleQuestions: false },
            questions: [
                { id: 1, text: 'Which pigment absorbs sunlight?', type: QuestionType.MCQ, options: ['Chlorophyll', 'Xanthophyll'], correctAnswer: 'Chlorophyll', explanation: '', difficulty: 'Easy' },
                { id: 2, text: 'Product of photosynthesis?', type: QuestionType.MCQ, options: ['O2', 'CO2'], correctAnswer: 'O2', explanation: '', difficulty: 'Easy' }
            ]
        }
    ]);
    const [testResults, setTestResults] = useState<TestResult[]>([]);

    useEffect(() => {
        document.documentElement.classList.toggle('dark', isDarkMode);
    }, [isDarkMode]);

    const addNotification = (title: string, message: string, type: 'INFO'|'SUCCESS'|'ERROR'|'EMAIL' = 'INFO') => {
        const id = Date.now().toString();
        setNotifications(prev => [...prev, { id, title, message, type, timestamp: new Date().toISOString() }]);
        setTimeout(() => setNotifications(prev => prev.filter(n => n.id !== id)), 8000); // Auto dismiss
    };

    const handleLogin = (role: UserRole, email: string) => {
        // Generate Mock ID
        const id = `MC-${Math.floor(1000 + Math.random() * 9000)}-${Math.floor(1000 + Math.random() * 9000)}-${Math.floor(1000 + Math.random() * 9000)}`;
        setUser({
            id,
            email,
            name: email.split('@')[0],
            role,
            preferences: { language: 'English', gradeLevel: '10', style: 'Visual' },
            friends: [],
            profile: { dob: '', gender: '', school: '', phone: '', bio: '', isPublic: false }
        });
        setCurrentView(AppView.DASHBOARD);
        // Show onboarding on first login
        setShowOnboarding(true);
    };

    const handleReset = () => {
        setLibrary([]);
        setTests([]);
        setTestResults([]);
        setClassrooms([]);
        addNotification("System Reset", "All local data has been cleared.", "INFO");
    };

    const handleLoadScenario = (scenario: 'TEACHER_DEMO' | 'STUDENT_DEMO') => {
        handleReset();

        const demoClass: Classroom = {
            id: 'demo-class-1',
            name: 'Advanced Physics',
            subject: 'Physics',
            teacherId: 'TEACHER',
            studentIds: ['s1', 's2', 's3'],
            code: 'PHY-101',
            inviteLink: 'https://myclassroom.ai/join/PHY-101',
            isLinkActive: true
        };
        setClassrooms([demoClass]);

        if (scenario === 'TEACHER_DEMO') {
             // Teacher Logic: Already handled by reset & class creation mostly
             addNotification("Scenario Loaded", "Teacher Demo: Class created, ready to deploy tests.", "SUCCESS");
        } else {
             // Student Logic: Setup a test ready to take
             const demoTest: TestData = {
                 id: 'demo-test-1',
                 title: 'Mid-Term Physics Exam',
                 subject: 'Physics',
                 creatorId: 'TEACHER',
                 status: 'LIVE',
                 accessCode: 'PHY-TEST',
                 settings: { timeLimitMinutes: 45, proctoring: true, adaptive: false, shuffleQuestions: true },
                 questions: [
                     { id: 1, text: 'What is the speed of light?', type: QuestionType.MCQ, options: ['3x10^8 m/s', '3x10^6 m/s'], correctAnswer: '3x10^8 m/s', explanation: 'Constant c', difficulty: 'Easy' }
                 ]
             };
             setTests([demoTest]);
             addNotification("Scenario Loaded", "Student Demo: Live test available (Code: PHY-TEST).", "SUCCESS");
        }
    }

    const addToLibrary = (type: ContentType, title: string, data: any) => {
        const newItem: LibraryItem = {
            id: Date.now().toString(),
            type,
            title,
            dateCreated: new Date().toISOString(),
            data,
            userId: user?.id || ''
        };
        setLibrary(prev => [newItem, ...prev]);
        addNotification('Content Saved', `"${title}" added to My Library`, 'SUCCESS');
    };

    // SOCIAL LOGIC
    const handleSendRequest = (toUid: string) => {
        if (!user) return { success: false, message: 'Not logged in' };
        if (toUid === user.id) return { success: false, message: 'Cannot invite yourself' };

        // Demo Validation
        if (toUid.startsWith('MC-')) {
            setTimeout(() => {
                addNotification('New Notification', `${user.role === UserRole.TEACHER ? 'Student' : 'Friend'} accepted your request!`, 'SUCCESS');
                setUser(prev => prev ? ({ ...prev, friends: [...prev.friends, toUid] }) : null);
            }, 2000);
            return { success: true, message: 'Request sent successfully!' };
        } else {
            return { success: false, message: 'Invalid UID Format' };
        }
    };

    // CLASSROOM LOGIC
    const handleJoinClass = (input: string) => {
        // Parse Code from URL or Raw Code
        let code = input.trim();
        if (input.includes('/join/')) {
            code = input.split('/join/')[1];
        }

        const targetClass = classrooms.find(c => c.code === code);
        const alreadyJoined = targetClass?.studentIds.includes(user?.id || '');

        if (!targetClass) {
            return { success: false, message: 'Invalid Class Code or Link' };
        }

        if (alreadyJoined) {
            return { success: false, message: `You are already in ${targetClass.name}` };
        }

        if (targetClass.isLinkActive === false) {
             return { success: false, message: 'This invite link has expired or is disabled.' };
        }

        // Add student
        const updatedClass = {
            ...targetClass,
            studentIds: [...targetClass.studentIds, user?.id || '']
        };

        setClassrooms(prev => prev.map(c => c.id === targetClass.id ? updatedClass : c));

        // Notify Teacher (Simulated)
        if (user?.role === UserRole.STUDENT) {
            setTimeout(() => {
                // In a real app, we'd find the teacher user and push notif
                // Here we just show a local success toast for the student
            }, 500);
        }

        addNotification('Classroom Joined', `Successfully joined ${updatedClass.name}!`, 'SUCCESS');
        return { success: true, message: `Joined ${updatedClass.name}!` };
    };

    const handleCreateClass = (c: Classroom) => {
        // Initialize Link Props
        const newClass: Classroom = {
            ...c,
            inviteLink: `https://myclassroom.ai/join/${c.code}`,
            isLinkActive: true,
            settings: { requiresApproval: false }
        };
        setClassrooms(prev => [...prev, newClass]);
        addNotification('Classroom Created', `Code: ${c.code}`, 'SUCCESS');
    };

    const handleUpdateClass = (updatedClass: Classroom) => {
        setClassrooms(prev => prev.map(c => c.id === updatedClass.id ? updatedClass : c));
        addNotification('Classroom Updated', 'Settings have been saved.', 'SUCCESS');
    }

    const handleCreateTest = (t: TestData) => {
        setTests(prev => [...prev, t]);
        addNotification('Test Created', `Test "${t.title}" is now ${t.status}`, 'SUCCESS');
    };

    const handleDeployTest = (testId: string, classId: string) => {
        setTests(prev => prev.map(t => {
            if (t.id === testId) {
                const cls = classrooms.find(c => c.id === classId);
                return { ...t, status: 'LIVE', assignedClassId: classId, assignedClassName: cls?.name };
            }
            return t;
        }));

        // Notify Students (Simulated)
        addNotification('Test Deployed', `Students in ${classrooms.find(c => c.id === classId)?.name} notified via Email`, 'EMAIL');
    };

    const renderContent = () => {
        if (!user) return null;
        switch (currentView) {
            case AppView.DASHBOARD: return <Dashboard user={user} changeView={setCurrentView} />;
            case AppView.VIDEO_GEN: return <VideoGenerator />;
            case AppView.EBOOK_GEN: return <EbookGenerator />;
            case AppView.PPT_GEN: return <PPTGenerator onSave={(ppt) => addToLibrary(ContentType.PPT, ppt.topic, ppt)} />;
            case AppView.TEST_MANAGER: return <TestManager 
                user={user} 
                globalTests={tests} 
                testHistory={testResults.filter(r => r.studentId === user.id)} 
                classrooms={classrooms}
                onAddTest={handleCreateTest} 
                onSaveResult={(r) => { setTestResults([...testResults, r]); addNotification('Test Submitted', 'Results & Violation Report Saved', 'SUCCESS'); }} 
                onDeployTest={handleDeployTest}
            />;
            case AppView.CLASSROOMS: return <ClassroomManager 
                user={user} 
                classrooms={classrooms} 
                onCreate={handleCreateClass} 
                onJoin={handleJoinClass} 
                onUpdate={handleUpdateClass}
            />;
            case AppView.LIBRARY: return <Library items={library.filter(i => i.userId === user.id)} />;
            case AppView.DOUBT_TUTOR: return <DoubtTutor />;
            case AppView.VIRTUAL_LAB: return <VirtualLab />;
            case AppView.CAREER_PATH: return <CareerPath />;
            case AppView.SOCIAL: return <SocialManager user={user} sendRequest={handleSendRequest} friends={user.friends} />;
            case AppView.LEARNING_PATH: return <LearningPathBuilder />;
            case AppView.NOTES_GEN: return <NotesGenerator onSave={(item) => addToLibrary(item.type!, item.title!, item.data)} />;
            case AppView.PROFILE: return <ProfileManager user={user} onUpdate={(u) => setUser(u)} />;
            case AppView.ASSIGNMENTS: return <AssignmentManager user={user} />;
            case AppView.ANALYTICS: return <AnalyticsDashboard />;
            default: return <div className="p-10">Feature coming soon</div>;
        }
    };

    if (!user) return <LoginScreen onLogin={handleLogin} notify={addNotification} />;

    return (
        <div className="flex min-h-screen bg-gray-50 dark:bg-gray-900 transition-colors duration-200 font-sans relative">
            {showOnboarding && <OnboardingTour onComplete={() => setShowOnboarding(false)} />}

            <Sidebar currentView={currentView} onChangeView={setCurrentView} onLogout={() => setUser(null)} user={user} />
            <main className="flex-1 ml-64 relative">
                <div className="absolute top-4 right-4 z-20">
                    <button 
                        onClick={() => setIsDarkMode(!isDarkMode)}
                        className="p-2 rounded-full bg-white dark:bg-gray-800 shadow-md text-gray-600 dark:text-yellow-400 hover:bg-gray-50 dark:hover:bg-gray-700"
                    >
                        {isDarkMode ? <Sun className="w-5 h-5" /> : <Moon className="w-5 h-5" />}
                    </button>
                </div>
                {renderContent()}
                <NotificationSystem notifications={notifications} remove={(id) => setNotifications(prev => prev.filter(n => n.id !== id))} />
            </main>

            {/* Judge Controls Floating Button */}
            <JudgeControls 
                userRole={user.role}
                onLogout={() => setUser(null)}
                onReset={handleReset}
                onLoadScenario={handleLoadScenario}
            />
        </div>
    );
};

export default App;

