const VideoGenerator: React.FC = () => {
  const [topic, setTopic] = useState('');
  const [duration, setDuration] = useState(10);
  const [loading, setLoading] = useState(false);
  const [script, setScript] = useState<VideoScript | null>(null);
  const [currentChapter, setCurrentChapter] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);

  // Thinking State for visual effect
  const [thinkingStep, setThinkingStep] = useState('');

  // Veo State
  const [generatingVeo, setGeneratingVeo] = useState(false);
  const [veoUrl, setVeoUrl] = useState<string | null>(null);

  const handleGenerate = async () => {
    setLoading(true);
    setThinkingStep('Analyzing Topic & Curriculum...');

    // Simulate thinking steps
    setTimeout(() => setThinkingStep('Structuring Key Concepts...'), 1500);
    setTimeout(() => setThinkingStep('Drafting Voiceover Script...'), 3000);
    setTimeout(() => setThinkingStep('Generating Visual Cues...'), 4500);

    try {
      const result = await generateVideoScript(topic, duration, 'English', 'Animated');
      setScript(result);
    } catch (error) {
      console.error("Failed to generate script", error);
    } finally {
      setLoading(false);
      setThinkingStep('');
    }
  };

  const handleGenerateVeo = async () => {
    if (!script) return;
    setGeneratingVeo(true);
    try {
        const previewPrompt = script.chapters[0].visualCue;
        const url = await generateVeoPreview(previewPrompt);
        setVeoUrl(url);
    } catch(e) {
        console.error(e);
    } finally {
        setGeneratingVeo(false);
    }
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <h2 className="text-3xl font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
        <VideoIcon className="w-8 h-8 text-primary-500" />
        AI Video Studio
      </h2>

      {!script ? (
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-8 max-w-3xl mx-auto">
          <div className="space-y-6">
            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Topic to Teach</label>
