import React, { useState } from 'react';
import { generateVideoScript, generateVeoPreview } from '../services/gemini';
import { VideoScript } from '../types';
import { Play, Pause, Loader2, Video as VideoIcon, BrainCircuit, Lightbulb, Sparkles } from 'lucide-react';

const VideoGenerator: React.FC = () => {
  const [prompt, setPrompt] = useState('');
  const [duration, setDuration] = useState(5);
  const [loading, setLoading] = useState(false);
  const [script, setScript] = useState<VideoScript | null>(null);
  const [currentChapter, setCurrentChapter] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);

  // Thinking State for visual effect
  const [thinkingStep, setThinkingStep] = useState('');

  // Veo State
  const [generatingVeo, setGeneratingVeo] = useState(false);
  const [veoUrl, setVeoUrl] = useState<string | null>(null);

  const handleGenerate = async () => {
    setLoading(true);
    setThinkingStep('Analyzing Prompt & Curriculum...');

    // Simulate thinking steps for the script part
    setTimeout(() => setThinkingStep('Structuring Key Concepts...'), 1500);
    setTimeout(() => setThinkingStep('Drafting Voiceover Script...'), 3000);

    try {
      // 1. Generate Script first for structure and insights
      const result = await generateVideoScript(prompt, duration, 'English', 'Animated');
      setScript(result);

      // 2. Automatically start generating the actual video
      setThinkingStep('Generating Video Frames (Veo)...');
      setGeneratingVeo(true);

      // Use the prompt + first chapter visual cue for the video generation
      const videoPrompt = `${prompt}. ${result.chapters[0].visualCue}`;
      const url = await generateVeoPreview(videoPrompt);
      setVeoUrl(url);

    } catch (error) {
      console.error("Failed to generate content", error);
    } finally {
      setLoading(false);
      setGeneratingVeo(false);
      setThinkingStep('');
    }
  };

  const handleRegenerateScene = async () => {
    if (!script) return;
    setGeneratingVeo(true);
    setVeoUrl(null);
    try {
        const previewPrompt = script.chapters[currentChapter].visualCue;
        const url = await generateVeoPreview(previewPrompt);
        setVeoUrl(url);
    } catch(e) {
        console.error(e);
    } finally {
        setGeneratingVeo(false);
    }
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <h2 className="text-3xl font-bold text-gray-800 dark:text-white mb-6 flex items-center gap-2">
        <VideoIcon className="w-8 h-8 text-primary-500" />
        AI Video Studio
      </h2>

      {!script && !loading ? (
        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-8 max-w-3xl mx-auto animate-fade-in">
          <div className="space-y-6">
            <div className="text-center mb-8">
                <div className="bg-primary-100 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-4">
                    <Sparkles className="w-10 h-10 text-primary-600" />
                </div>
                <h3 className="text-2xl font-bold dark:text-white">Create Educational Videos</h3>
                <p className="text-gray-500">Describe the topic, and AI will generate a script, insights, and a real video.</p>
            </div>

            <div>
              <label className="block text-sm font-bold text-gray-700 dark:text-gray-300 mb-2">Video Prompt</label>
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Describe the video you want (e.g., 'Explain the water cycle to a 5th grader with animated clouds and rain')..."
                className="w-full p-4 rounded-xl border border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900 dark:text-white focus:ring-2 focus:ring-primary-500 min-h-[120px]"
              />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                Target Duration: {duration} minutes
              </label>
              <input
                type="range"
                min="3"
                max="30"
                value={duration}
                onChange={(e) => setDuration(Number(e.target.value))}
                className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer dark:bg-gray-700"
              />
            </div>

            <button
              onClick={handleGenerate}
              disabled={loading || !prompt}
              className="w-full py-4 bg-gradient-to-r from-primary-600 to-indigo-600 hover:from-primary-700 hover:to-indigo-700 text-white rounded-xl font-bold shadow-lg transition-all flex justify-center items-center gap-2 disabled:opacity-50 text-lg"
            >
              Generate Video
            </button>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
          {/* Main Player Area */}
          <div className="lg:col-span-3 space-y-6">

            {loading ? (
                 <div className="bg-black rounded-xl overflow-hidden aspect-video flex flex-col items-center justify-center text-white shadow-2xl">
                     <Loader2 className="w-16 h-16 animate-spin mb-4 text-primary-500" />
                     <h3 className="text-xl font-bold animate-pulse">{thinkingStep}</h3>
                     <p className="text-gray-400 text-sm mt-2">This may take a minute...</p>
                 </div>
            ) : (
                <div className="bg-black rounded-xl overflow-hidden aspect-video relative shadow-2xl flex items-center justify-center group border border-gray-800">
                {veoUrl ? (
                    <video src={veoUrl} controls autoPlay loop className="w-full h-full object-cover" />
                ) : generatingVeo ? (
                    <div className="text-center">
                        <Loader2 className="w-12 h-12 animate-spin text-white mx-auto mb-4" />
                        <p className="text-white font-medium">Rendering Scene with Veo...</p>
                    </div>
                ) : (
                    <div className="text-center p-12">
                        <div className="text-6xl mb-4">🎬</div>
