    ]);
    const [classrooms, setClassrooms] = useState<Classroom[]>([
        // Initial Demo Classroom
        {
            id: '1',
            name: 'Science Class 10',
            subject: 'Science',
            teacherId: 'TEACHER',
            studentIds: [],
            code: 'SCI-10A',
            inviteLink: 'https://myclassroom.ai/join/SCI-10A',
            isLinkActive: true,
