// --- ASSIGNMENT (NEW) ---
export const generateAssignmentQuestions = async (topic: string, count: number, difficulty: string, questionType: string): Promise<Question[]> => {
  const client = await getClient();
  const prompt = `
    Generate ${count} ${difficulty} level questions on "${topic}". 
    Question Type: ${questionType} (MCQ, Short, Long, etc).
    If MCQ, provide 4 options.
    Provide correct answer, explanation, and suggest marks (e.g. 2 for MCQ, 5 for Long).
    Return JSON array.
  `;

  const schema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.INTEGER },
        text: { type: Type.STRING },
        type: { type: Type.STRING, enum: ["MCQ", "SHORT", "LONG", "ONE_WORD", "FILL_BLANKS", "TRUE_FALSE"] },
        options: { type: Type.ARRAY, items: { type: Type.STRING } },
        correctAnswer: { type: Type.STRING },
        explanation: { type: Type.STRING },
        difficulty: { type: Type.STRING, enum: ["Easy", "Medium", "Hard"] },
        marks: { type: Type.INTEGER }
      },
      required: ["text", "type", "difficulty", "marks"]
    }
  };

  const response = await client.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
    config: { responseMimeType: "application/json", responseSchema: schema }
  });

  const raw = JSON.parse(response.text || "[]");
  return raw.map((q: any, i: number) => ({ ...q, id: Date.now() + i }));
};

