                          disabled={isGenerating || !aiSettings.topic}
                          className="w-full bg-purple-600 hover:bg-purple-700 text-white font-bold py-3 rounded-lg flex items-center justify-center gap-2 shadow-md"
                      >
                          {isGenerating ? <Loader2 className="animate-spin" /> : <><RefreshCw className="w-4 h-4"/> Generate Questions</>}
                      </button>
                  </div>
              )}

              {/* QUESTIONS LIST */}
              <div className="flex-1 overflow-y-auto space-y-6 pr-2">
                  {questions.length === 0 && (
                      <div className="text-center py-20 text-gray-400">
                          <FileText className="w-16 h-16 mx-auto mb-4 opacity-20" />
                          <p>No questions yet. Use AI Assistant or add manually.</p>
                      </div>
                  )}

                  {questions.map((q, idx) => (
                      <div key={q.id} className="bg-gray-50 dark:bg-gray-900 p-6 rounded-xl border border-gray-200 dark:border-gray-700 relative group transition-all hover:shadow-md hover:border-blue-300 dark:hover:border-blue-700">
                          <div className="flex justify-between items-start mb-4">
                              <div className="flex items-center gap-3">
                                  <span className="text-lg font-bold text-blue-600">Q{idx + 1}</span>
                                  <span className="bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 text-xs px-2 py-1 rounded-full font-bold uppercase">{q.type}</span>
                              </div>
                              <button 
                                  onClick={() => deleteQuestion(q.id)}
                                  className="text-gray-400 hover:text-red-500 transition-colors"
                              >
                                  <Trash2 className="w-5 h-5" />
                              </button>
                          </div>

                          <textarea 
                              value={q.text}
                              onChange={e => updateQuestion(q.id, 'text', e.target.value)}
                              placeholder="Enter question text..."
                              className="w-full p-3 rounded-lg border border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white mb-4 focus:ring-2 focus:ring-blue-500 min-h-[80px]"
                          />

                          {/* MCQ Options */}
                          {q.type === QuestionType.MCQ && q.options && (
                              <div className="grid grid-cols-2 gap-3 mb-4">
                                  {q.options.map((opt, i) => (
                                      <div key={i} className="flex items-center gap-2">
                                          <div className="w-8 h-8 flex-shrink-0 bg-white dark:bg-gray-800 border rounded flex items-center justify-center font-bold text-gray-500">
                                              {String.fromCharCode(65 + i)}
                                          </div>
                                          <input 
                                              value={opt}
                                              onChange={e => updateOption(q.id, i, e.target.value)}
                                              placeholder={`Option ${String.fromCharCode(65 + i)}`}
                                              className="flex-1 p-2 rounded border border-gray-300 dark:border-gray-600 dark:bg-gray-800 dark:text-white text-sm"
                                          />
                                          <input 
                                              type="radio"
                                              name={`correct-${q.id}`}
                                              checked={q.correctAnswer === opt} // Simple string match for now
                                              onChange={() => updateQuestion(q.id, 'correctAnswer', opt)}
                                              className="w-5 h-5 text-green-600"
                                          />
                                      </div>
                                  ))}
                              </div>
                          )}

                          <div className="flex gap-4">
                              <div className="flex-1">
                                  <label className="text-xs font-bold text-gray-500 uppercase">Correct Answer</label>
                                  <input 
                                      value={q.correctAnswer || ''}
                                      onChange={e => updateQuestion(q.id, 'correctAnswer', e.target.value)}
                                      className="w-full p-2 border rounded mt-1 dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                                  />
                              </div>
                              <div className="w-24">
                                  <label className="text-xs font-bold text-gray-500 uppercase">Marks</label>
