                                      type="number"
                                      value={q.marks}
                                      onChange={e => updateQuestion(q.id, 'marks', Number(e.target.value))}
                                      className="w-full p-2 border rounded mt-1 dark:bg-gray-800 dark:border-gray-600 dark:text-white"
                                  />
                              </div>
                          </div>
                      </div>
                  ))}
              </div>

              {/* FOOTER ACTIONS */}
              <div className="mt-8 pt-6 border-t border-gray-100 dark:border-gray-700 flex justify-end gap-4">
                  <button onClick={() => setView('LIST')} className="px-6 py-3 text-gray-500 font-bold hover:bg-gray-100 dark:hover:bg-gray-700 rounded-lg">
