                  </button>
                  <button onClick={handleSaveAssignment} className="bg-green-600 hover:bg-green-700 text-white px-8 py-3 rounded-lg font-bold flex items-center gap-2 shadow-lg">
                      <Save className="w-5 h-5" /> Save & Publish
                  </button>
              </div>
          </div>
      </div>
  );

  // --- MAIN RENDER ---

  if (user.role === UserRole.STUDENT) {
      return (
          <div className="p-6 max-w-5xl mx-auto">
              <h2 className="text-3xl font-bold dark:text-white mb-6 flex items-center gap-2">
                  <FileText className="w-8 h-8 text-orange-600" />
