import React, { useState, useEffect, useRef } from 'react';
import { User, UserRole, Assignment, Question, QuestionType, AssignmentSubmission } from '../types';
import { 
    FileText, Plus, Bot, Loader2, CheckCircle, Clock, 
    Settings, List, AlignLeft, AlignJustify, Mic, CheckSquare, 
    Trash2, Save, Play, Pause, ChevronRight, User as UserIcon,
    Download, RefreshCw, Sparkles, Send, MicOff, BarChart
} from 'lucide-react';
import { generateAssignmentFromPrompt, evaluateSubmission, generateClassReport } from '../services/gemini';
import confetti from 'canvas-confetti';
import ReactMarkdown from 'react-markdown';

interface AssignmentManagerProps {
  user: User;
}

const AssignmentManager: React.FC<AssignmentManagerProps> = ({ user }) => {
  // VIEW STATES: TEACHER_LIST, TEACHER_CREATE, TEACHER_REVIEW, STUDENT_LIST, STUDENT_TAKE
  const [view, setView] = useState<string>(user.role === UserRole.TEACHER ? 'TEACHER_LIST' : 'STUDENT_LIST');

  // --- STATE: ASSIGNMENT CREATION (TEACHER) ---
  const [meta, setMeta] = useState({
      title: "New Assignment",
      subject: "Physics",
      topicPrompt: "",
      grades: [10],
      type: QuestionType.MCQ,
      totalMarks: 20,
      dueDate: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString().slice(0, 16)
  });
  const [questions, setQuestions] = useState<Question[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeAgent, setActiveAgent] = useState<'GENERATOR' | 'CHECKER' | 'REPORTER'>('GENERATOR');

  // --- STATE: ASSIGNMENT TAKING (STUDENT) ---
  const [activeAssignment, setActiveAssignment] = useState<Assignment | null>(null);
  const [answers, setAnswers] = useState<Record<number, string>>({}); // Text answers or Audio URLs
  const [audioBlobs, setAudioBlobs] = useState<Record<number, string>>({}); // Base64 for submission
  const [isRecording, setIsRecording] = useState<number | null>(null); // Question ID being recorded
  const mediaRecorder = useRef<MediaRecorder | null>(null);
  const [saveStatus, setSaveStatus] = useState('Saved');

  // --- STATE: GLOBAL DATA ---
  const [assignments, setAssignments] = useState<Assignment[]>([
      { 
          id: '101', 
          title: 'Newton\'s Laws Oral Test', 
          description: 'Explain the concepts verbally.', 
          classroomId: 'SCI-10A', 
          dueDate: '2023-12-01', 
          status: 'PUBLISHED', 
          type: 'AI', 
          questions: [
              { id: 1, text: "Explain Newton's First Law in your own words.", type: QuestionType.ORAL, marks: 5, difficulty: 'Medium', explanation: '' },
              { id: 2, text: "What is Inertia?", type: QuestionType.SHORT, marks: 2, difficulty: 'Easy', explanation: '' }
          ], 
          submissions: [],
          totalMarks: 7, 
          subject: 'Physics' 
      }
  ]);

  // --- TEACHER: AGENT 1 - GENERATOR ---
  const handleAIGenerate = async () => {
      if (!meta.topicPrompt) return;
      setIsGenerating(true);
      try {
          const newQs = await generateAssignmentFromPrompt(
              meta.topicPrompt, 
              meta.subject, 
              meta.grades.join(','), 
              meta.type, 
              meta.totalMarks
          );
          setQuestions(newQs);
      } catch (e) {
          console.error(e);
          alert("Agent failed to generate. Try a clearer prompt.");
      } finally {
          setIsGenerating(false);
      }
  };

  const publishAssignment = () => {
      const newAssign: Assignment = {
          id: Date.now().toString(),
          title: meta.title,
          description: meta.topicPrompt || 'Generated Assignment',
          classroomId: 'SCI-10A',
          dueDate: meta.dueDate,
          status: 'PUBLISHED',
          type: 'AI',
          questions: questions,
          subject: meta.subject,
          totalMarks: meta.totalMarks,
          grades: meta.grades,
          submissions: []
      };
      setAssignments([newAssign, ...assignments]);
      setView('TEACHER_LIST');
      confetti({ particleCount: 100, spread: 70, origin: { y: 0.6 } });
  };

  // --- STUDENT: TAKING LOGIC ---

  // Auto-Save Effect
  useEffect(() => {
      if (view === 'STUDENT_TAKE') {
          const interval = setInterval(() => {
              setSaveStatus('Saving...');
              setTimeout(() => setSaveStatus('Saved'), 800);
          }, 30000);
          return () => clearInterval(interval);
      }
  }, [view, answers]);

  const handleAudioRecord = async (qId: number) => {
      if (isRecording === qId) {
          // STOP RECORDING
          mediaRecorder.current?.stop();
          setIsRecording(null);
      } else {
          // START RECORDING
          try {
              const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
              const recorder = new MediaRecorder(stream);
              const chunks: Blob[] = [];

              recorder.ondataavailable = e => chunks.push(e.data);
              recorder.onstop = () => {
                  const blob = new Blob(chunks, { type: 'audio/webm' });
                  const url = URL.createObjectURL(blob);

                  // Convert to base64 for "storage"
                  const reader = new FileReader();
                  reader.readAsDataURL(blob);
                  reader.onloadend = () => {
                      const base64 = reader.result as string;
                      setAudioBlobs(prev => ({ ...prev, [qId]: base64 }));
                  };

                  setAnswers(prev => ({ ...prev, [qId]: url }));
              };

              recorder.start();
              mediaRecorder.current = recorder;
              setIsRecording(qId);
          } catch (e) {
              alert("Microphone access denied.");
          }
      }
  };

  const submitAssignment = () => {
      if (!activeAssignment) return;

      const newSubmission: AssignmentSubmission = {
          studentId: user.id,
          studentName: user.name,
          submittedAt: new Date().toISOString(),
          answers: answers,
          audioBlobs: audioBlobs,
          status: 'PENDING'
      };

      // Update local state
      const updatedAssignments = assignments.map(a => {
          if (a.id === activeAssignment.id) {
              return { ...a, submissions: [...a.submissions, newSubmission] };
          }
          return a;
      });

      setAssignments(updatedAssignments);
      setView('STUDENT_LIST');
      confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 } });
  };

  // --- TEACHER: REVIEW & AGENTS ---
  const [selectedSubmission, setSelectedSubmission] = useState<AssignmentSubmission | null>(null);
  const [report, setReport] = useState('');

  const handleAICheck = async () => {
      if (!selectedSubmission || !activeAssignment) return;
      setIsGenerating(true);
      try {
          const result = await evaluateSubmission(activeAssignment.questions, selectedSubmission.answers);

          // Update submission with grade
          const updatedSub = { ...selectedSubmission, score: result.score, feedback: result.feedback, status: 'GRADED' as const };

          // Save back to state
          const updatedAssignments = assignments.map(a => {
              if (a.id === activeAssignment.id) {
                  const newSubs = a.submissions.map(s => s.studentId === selectedSubmission.studentId ? updatedSub : s);
                  return { ...a, submissions: newSubs };
              }
              return a;
          });
          setAssignments(updatedAssignments);
          setSelectedSubmission(updatedSub);
      } catch (e) {
          console.error(e);
      } finally {
          setIsGenerating(false);
      }
  };

  const handleGenerateReport = async () => {
      if (!activeAssignment) return;
      setIsGenerating(true);
      try {
          const rep = await generateClassReport(activeAssignment.submissions);
          setReport(rep);
      } catch (e) {
          console.error(e);
      } finally {
          setIsGenerating(false);
      }
  }

  const handlePrint = () => {
      window.print();
  };

  // --- RENDERERS ---

  const renderTeacherCreator = () => (
      <div className="flex flex-col lg:flex-row gap-6 animate-fade-in print:hidden">
          {/* SETTINGS SIDEBAR */}
          <div className="w-full lg:w-80 space-y-6">
              <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow border border-gray-200 dark:border-gray-700">
                  <h3 className="font-bold text-gray-700 dark:text-gray-200 mb-4 flex items-center gap-2">
                      <Settings className="w-5 h-5"/> Settings
                  </h3>
                  <div className="space-y-4">
                      <input 
                          value={meta.title} onChange={e => setMeta({...meta, title: e.target.value})}
                          className="w-full p-2 border rounded dark:bg-gray-700 dark:text-white" placeholder="Title"
                      />
                      <select 
                          value={meta.subject} onChange={e => setMeta({...meta, subject: e.target.value})}
                          className="w-full p-2 border rounded dark:bg-gray-700 dark:text-white"
                      >
                          {['Physics','Chemistry','Math','Biology','English','History','Computer Science'].map(s => <option key={s}>{s}</option>)}
                      </select>
                      <select 
                          value={meta.type} onChange={e => setMeta({...meta, type: e.target.value as QuestionType})}
                          className="w-full p-2 border rounded dark:bg-gray-700 dark:text-white"
                      >
                          <option value={QuestionType.MCQ}>MCQ</option>
                          <option value={QuestionType.SHORT}>Short Answer</option>
                          <option value={QuestionType.LONG}>Long Answer</option>
                          <option value={QuestionType.ORAL}>Oral Test (Audio)</option>
                          <option value={QuestionType.TRUE_FALSE}>True/False</option>
                      </select>
                      <input 
                          type="number" value={meta.totalMarks} onChange={e => setMeta({...meta, totalMarks: Number(e.target.value)})}
                          className="w-full p-2 border rounded dark:bg-gray-700 dark:text-white" placeholder="Total Marks"
                      />
                      <input 
                          type="datetime-local" value={meta.dueDate} onChange={e => setMeta({...meta, dueDate: e.target.value})}
                          className="w-full p-2 border rounded dark:bg-gray-700 dark:text-white"
                      />
                  </div>
              </div>
          </div>

          {/* MAIN AI WORKSPACE */}
          <div className="flex-1 bg-white dark:bg-gray-800 p-8 rounded-xl shadow border border-gray-200 dark:border-gray-700">
              <div className="mb-6">
                  <h2 className="text-2xl font-bold dark:text-white flex items-center gap-2">
                      <Bot className="w-8 h-8 text-blue-600" /> Assignment Generator Agent
                  </h2>
                  <p className="text-gray-500 text-sm">Describe what you want, and I'll create the questions.</p>
              </div>

              <div className="bg-blue-50 dark:bg-blue-900/20 p-4 rounded-xl border border-blue-100 dark:border-blue-800 mb-6">
                  <textarea 
                      value={meta.topicPrompt}
                      onChange={e => setMeta({...meta, topicPrompt: e.target.value})}
                      placeholder="e.g. Create 5 MCQ questions on Newton's Laws for grade 10 with medium difficulty. Focus on practical examples."
                      className="w-full bg-transparent border-none focus:ring-0 text-gray-800 dark:text-white h-24 resize-none"
                  />
                  <div className="flex justify-end mt-2">
                      <button 
                          onClick={handleAIGenerate}
                          disabled={isGenerating || !meta.topicPrompt}
                          className="bg-blue-600 text-white px-6 py-2 rounded-lg font-bold flex items-center gap-2 hover:bg-blue-700 disabled:opacity-50"
                      >
                          {isGenerating ? <Loader2 className="animate-spin w-4 h-4"/> : <Sparkles className="w-4 h-4"/>}
                          Generate Assignment
                      </button>
                  </div>
              </div>

              {/* QUESTIONS PREVIEW */}
              <div className="space-y-4 max-h-[500px] overflow-y-auto pr-2">
                  {questions.map((q, i) => (
                      <div key={q.id} className="p-4 border rounded-lg dark:border-gray-700">
                          <div className="flex justify-between">
                              <span className="font-bold text-blue-600">Q{i+1} ({q.type})</span>
                              <span className="text-xs bg-gray-100 dark:bg-gray-700 px-2 py-1 rounded dark:text-white">{q.marks} Marks</span>
                          </div>
                          <p className="mt-2 dark:text-white">{q.text}</p>
                          {q.type === QuestionType.MCQ && (
                              <div className="mt-2 grid grid-cols-2 gap-2">
                                  {q.options?.map((opt, idx) => (
                                      <div key={idx} className={`text-sm p-2 rounded ${opt === q.correctAnswer ? 'bg-green-100 text-green-800' : 'bg-gray-50 text-gray-600'}`}>
                                          {opt}
                                      </div>
                                  ))}
                              </div>
                          )}
                          <p className="text-xs text-gray-400 mt-2">Correct: {q.correctAnswer}</p>
                      </div>
                  ))}
              </div>

              {questions.length > 0 && (
                  <div className="mt-6 flex justify-end gap-3 border-t pt-4 dark:border-gray-700">
                      <button onClick={handlePrint} className="px-4 py-2 border rounded text-gray-600 hover:bg-gray-50 flex items-center gap-2">
                          <Download className="w-4 h-4"/> PDF Preview
                      </button>
                      <button onClick={publishAssignment} className="bg-green-600 text-white px-6 py-2 rounded font-bold hover:bg-green-700 flex items-center gap-2 shadow-lg">
                          <Send className="w-4 h-4"/> Publish
                      </button>
                  </div>
              )}
          </div>
      </div>
  );

  const renderStudentTaker = () => {
      if (!activeAssignment) return null;
      return (
          <div className="max-w-4xl mx-auto pb-20">
              <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border-b-4 border-blue-600 mb-6 sticky top-4 z-10">
                  <div className="flex justify-between items-center">
                      <div>
                          <h1 className="text-2xl font-bold dark:text-white">{activeAssignment.title}</h1>
                          <p className="text-gray-500 text-sm">Due: {new Date(activeAssignment.dueDate).toLocaleDateString()}</p>
                      </div>
                      <div className="flex items-center gap-4">
                          <span className="text-xs font-mono text-gray-400 flex items-center gap-1">
                              <RefreshCw className="w-3 h-3 animate-spin-slow"/> {saveStatus}
                          </span>
                          <div className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-sm font-bold">
                              {activeAssignment.totalMarks} Marks
                          </div>
                      </div>
                  </div>
              </div>

              <div className="space-y-6">
                  {activeAssignment.questions.map((q, i) => (
                      <div key={q.id} className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow border border-gray-200 dark:border-gray-700">
                          <div className="flex gap-3 mb-4">
                              <span className="w-8 h-8 flex items-center justify-center bg-gray-100 dark:bg-gray-700 rounded-full font-bold text-gray-600 dark:text-gray-300 flex-shrink-0">
                                  {i+1}
                              </span>
                              <div className="flex-1">
                                  <p className="text-lg font-medium dark:text-white mb-2">{q.text}</p>
                                  <span className="text-xs text-gray-400 uppercase tracking-wider">{q.type} • {q.marks} Marks</span>
                              </div>
                          </div>

                          <div className="pl-11">
                              {q.type === QuestionType.MCQ && (
                                  <div className="space-y-2">
                                      {q.options?.map(opt => (
                                          <label key={opt} className={`flex items-center gap-3 p-3 rounded border cursor-pointer hover:bg-gray-50 dark:hover:bg-gray-700 ${answers[q.id] === opt ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20' : 'border-gray-200 dark:border-gray-700'}`}>
                                              <input 
                                                  type="radio" name={`q-${q.id}`} 
                                                  checked={answers[q.id] === opt}
                                                  onChange={() => setAnswers({...answers, [q.id]: opt})}
                                                  className="w-4 h-4 text-blue-600"
                                              />
                                              <span className="dark:text-white">{opt}</span>
                                          </label>
                                      ))}
                                  </div>
                              )}

                              {(q.type === QuestionType.SHORT || q.type === QuestionType.LONG) && (
                                  <textarea 
                                      value={answers[q.id] || ''}
                                      onChange={e => setAnswers({...answers, [q.id]: e.target.value})}
                                      rows={q.type === QuestionType.SHORT ? 4 : 12}
                                      className="w-full p-3 border rounded-lg dark:bg-gray-900 dark:border-gray-600 dark:text-white focus:ring-2 focus:ring-blue-500"
                                      placeholder="Type your answer here..."
                                  />
                              )}

                              {q.type === QuestionType.ORAL && (
                                  <div className="bg-gray-50 dark:bg-gray-900 p-4 rounded-lg border border-gray-200 dark:border-gray-700">
                                      <div className="flex items-center gap-4 mb-4">
                                          <button 
                                              onClick={() => handleAudioRecord(q.id)}
                                              className={`p-4 rounded-full transition-all ${isRecording === q.id ? 'bg-red-500 animate-pulse' : 'bg-blue-600 hover:bg-blue-700'} text-white shadow-lg`}
                                          >
                                              {isRecording === q.id ? <div className="w-6 h-6 bg-white rounded-sm" /> : <Mic className="w-6 h-6" />}
                                          </button>
                                          <div className="flex-1">
                                              {isRecording === q.id ? (
                                                  <div className="h-8 flex items-center gap-1">
                                                      {[...Array(10)].map((_, k) => (
                                                          <div key={k} className="w-1 bg-red-400 rounded-full animate-waveform" style={{height: `${Math.random() * 100}%`}}></div>
                                                      ))}
                                                      <span className="text-red-500 text-sm font-bold ml-2">Recording...</span>
                                                  </div>
                                              ) : answers[q.id] ? (
                                                  <audio src={answers[q.id]} controls className="w-full h-8" />
