                  >
                      <CheckCircle className="w-6 h-6"/> Submit Assignment
                  </button>
              </div>
          </div>
      );
  };

  const renderTeacherReview = () => {
      if (!activeAssignment) return null;
      return (
          <div className="flex flex-col h-[800px]">
              <div className="flex justify-between items-center mb-6">
                  <div>
                      <h2 className="text-2xl font-bold dark:text-white flex items-center gap-2">
                          <CheckSquare className="w-6 h-6 text-purple-600"/> Review: {activeAssignment.title}
                      </h2>
                      <p className="text-gray-500">{activeAssignment.submissions.length} Submissions</p>
                  </div>
                  <div className="flex gap-2">
                      <button 
                          onClick={() => setActiveAgent(activeAgent === 'REPORTER' ? 'GENERATOR' : 'REPORTER')}
                          className={`px-4 py-2 rounded-lg font-bold flex items-center gap-2 ${activeAgent === 'REPORTER' ? 'bg-purple-600 text-white' : 'bg-gray-100 text-gray-600'}`}
                      >
                          <BarChart className="w-4 h-4"/> AI Result Formulator
                      </button>
                  </div>
              </div>

              <div className="flex flex-1 gap-6 overflow-hidden">
                  {/* SUBMISSION LIST */}
                  <div className="w-64 bg-white dark:bg-gray-800 rounded-xl shadow overflow-y-auto border border-gray-200 dark:border-gray-700">
                      {activeAssignment.submissions.map(sub => (
                          <button
                              key={sub.studentId}
                              onClick={() => { setSelectedSubmission(sub); setActiveAgent('CHECKER'); }}
                              className={`w-full text-left p-4 border-b border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 ${selectedSubmission?.studentId === sub.studentId ? 'bg-blue-50 dark:bg-blue-900/20 border-l-4 border-l-blue-500' : ''}`}
                          >
                              <div className="font-bold dark:text-white">{sub.studentName}</div>
                              <div className="text-xs text-gray-500 flex justify-between mt-1">
                                  <span>{new Date(sub.submittedAt).toLocaleDateString()}</span>
                                  <span className={sub.status === 'GRADED' ? 'text-green-600' : 'text-orange-500'}>{sub.status}</span>
                              </div>
                          </button>
                      ))}
                  </div>

                  {/* DETAIL VIEW */}
                  <div className="flex-1 bg-white dark:bg-gray-800 rounded-xl shadow border border-gray-200 dark:border-gray-700 p-8 overflow-y-auto relative">
                      {activeAgent === 'REPORTER' ? (
                          <div className="space-y-4">
                              <div className="bg-purple-50 dark:bg-purple-900/20 p-6 rounded-xl border border-purple-100 dark:border-purple-800">
                                  <h3 className="text-xl font-bold text-purple-800 dark:text-purple-300 mb-4 flex items-center gap-2">
                                      <Bot className="w-6 h-6"/> AI Class Report
                                  </h3>
                                  {report ? (
                                      <div className="prose dark:prose-invert max-w-none"><ReactMarkdown>{report}</ReactMarkdown></div>
                                  ) : (
                                      <div className="text-center py-10">
                                          <button onClick={handleGenerateReport} disabled={isGenerating} className="bg-purple-600 text-white px-6 py-3 rounded-lg font-bold">
                                              {isGenerating ? 'Analyzing Class Data...' : 'Generate Class Report'}
                                          </button>
                                      </div>
                                  )}
                              </div>
                          </div>
                      ) : selectedSubmission ? (
                          <div className="space-y-6">
                              <div className="flex justify-between items-start border-b pb-4">
                                  <div>
                                      <h3 className="text-xl font-bold dark:text-white">{selectedSubmission.studentName}'s Submission</h3>
                                      <p className="text-gray-500 text-sm">ID: {selectedSubmission.studentId}</p>
                                  </div>
                                  <div className="text-right">
                                      {selectedSubmission.score !== undefined && (
                                          <div className="text-3xl font-bold text-green-600">{selectedSubmission.score} <span className="text-sm text-gray-400">/ {activeAssignment.totalMarks}</span></div>
                                      )}
                                      <button 
                                          onClick={handleAICheck}
                                          disabled={isGenerating}
                                          className="mt-2 bg-gradient-to-r from-blue-600 to-indigo-600 text-white px-4 py-2 rounded shadow flex items-center gap-2 text-sm font-bold disabled:opacity-50"
                                      >
                                          {isGenerating ? <Loader2 className="animate-spin w-4 h-4"/> : <Bot className="w-4 h-4"/>}
                                          AI Paper Checker
                                      </button>
                                  </div>
                              </div>

                              <div className="space-y-6">
                                  {activeAssignment.questions.map((q, i) => (
                                      <div key={q.id} className="p-4 bg-gray-50 dark:bg-gray-900 rounded-lg border border-gray-200 dark:border-gray-700">
                                          <p className="font-bold mb-2 dark:text-white">Q{i+1}: {q.text} <span className="text-gray-400 font-normal">({q.marks} Marks)</span></p>

                                          <div className="bg-white dark:bg-gray-800 p-3 rounded border border-gray-200 dark:border-gray-600 mb-2">
                                              {q.type === QuestionType.ORAL ? (
                                                  selectedSubmission.answers[q.id] ? (
                                                      <audio src={selectedSubmission.answers[q.id]} controls className="w-full h-8" />
                                                  ) : <span className="text-red-400 italic">No Audio Submitted</span>
                                              ) : (
                                                  <p className="dark:text-gray-200">{selectedSubmission.answers[q.id] || <span className="text-red-400 italic">No Answer</span>}</p>
                                              )}
                                          </div>

                                          <p className="text-xs text-green-600"><strong>Correct Answer:</strong> {q.correctAnswer || 'Evaluated by AI'}</p>
                                      </div>
                                  ))}
                              </div>

                              {selectedSubmission.feedback && (
                                  <div className="mt-6 bg-blue-50 dark:bg-blue-900/20 p-4 rounded-lg border border-blue-100 dark:border-blue-800">
                                      <h4 className="font-bold text-blue-800 dark:text-blue-300 mb-2 flex items-center gap-2"><Bot className="w-4 h-4"/> AI Feedback</h4>
                                      <p className="text-blue-900 dark:text-blue-100 text-sm">{selectedSubmission.feedback}</p>
                                  </div>
                              )}

                              <div className="flex justify-end pt-4">
                                  <button onClick={handlePrint} className="flex items-center gap-2 text-gray-500 hover:text-black">
                                      <Download className="w-4 h-4" /> Download PDF Response
                                  </button>
                              </div>
                          </div>
                      ) : (
                          <div className="text-center text-gray-400 py-20">Select a student to review</div>
                      )}
                  </div>
              </div>
          </div>
      );
  };

  // --- MAIN RENDER SWITCH ---
  if (user.role === UserRole.STUDENT) {
      if (view === 'STUDENT_TAKE') return renderStudentTaker();

      return (
          <div className="p-6 max-w-6xl mx-auto">
              <h2 className="text-3xl font-bold dark:text-white mb-6">My Assignments</h2>
              <div className="grid gap-4">
                  {assignments.map(a => {
                      const mySub = a.submissions.find(s => s.studentId === user.id);
                      return (
                          <div key={a.id} className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow flex justify-between items-center">
                              <div>
                                  <h3 className="text-xl font-bold dark:text-white">{a.title}</h3>
                                  <p className="text-gray-500 text-sm">{a.subject} • Due {new Date(a.dueDate).toLocaleDateString()}</p>
                              </div>
                              {mySub ? (
                                  <div className="text-right">
                                      <span className="block text-green-600 font-bold mb-1">Submitted</span>
                                      {mySub.status === 'GRADED' && <span className="text-sm font-bold bg-blue-100 text-blue-700 px-2 py-1 rounded">Score: {mySub.score}/{a.totalMarks}</span>}
                                  </div>
                              ) : (
                                  <button 
                                      onClick={() => { setActiveAssignment(a); setView('STUDENT_TAKE'); }}
                                      className="bg-blue-600 text-white px-6 py-2 rounded-lg font-bold hover:bg-blue-700"
                                  >
                                      Start Assignment
                                  </button>
                              )}
                          </div>
                      );
                  })}
              </div>
          </div>
      );
  }

  // TEACHER VIEWS
  return (
      <div className="p-6 max-w-7xl mx-auto">
          {view === 'TEACHER_LIST' && (
              <>
                  <div className="flex justify-between items-center mb-8">
                      <h2 className="text-3xl font-bold dark:text-white">Assignment Dashboard</h2>
                      <button onClick={() => setView('TEACHER_CREATE')} className="bg-blue-600 text-white px-6 py-3 rounded-lg font-bold flex items-center gap-2 shadow-lg">
                          <Plus className="w-5 h-5"/> Create New
                      </button>
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                      {assignments.map(a => (
                          <div key={a.id} className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow border border-gray-200 dark:border-gray-700 hover:shadow-lg transition-all group">
                              <div className="flex justify-between items-start mb-4">
                                  <span className={`px-2 py-1 rounded text-xs font-bold ${a.type === 'AI' ? 'bg-purple-100 text-purple-700' : 'bg-gray-100 text-gray-700'}`}>{a.type}</span>
                                  <span className="text-xs text-gray-500">{a.submissions.length} Subs</span>
                              </div>
                              <h3 className="font-bold text-lg dark:text-white mb-2">{a.title}</h3>
                              <p className="text-sm text-gray-500 mb-4 line-clamp-2">{a.description}</p>
                              <button 
                                  onClick={() => { setActiveAssignment(a); setView('TEACHER_REVIEW'); }}
                                  className="w-full py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded font-bold hover:bg-gray-200 dark:hover:bg-gray-600 flex items-center justify-center gap-2"
                              >
                                  <CheckSquare className="w-4 h-4"/> Review & Grade
                              </button>
                          </div>
                      ))}
                  </div>
              </>
          )}

          {view === 'TEACHER_CREATE' && (
              <div>
                  <button onClick={() => setView('TEACHER_LIST')} className="mb-4 text-gray-500 hover:text-black dark:text-gray-400">← Back to Dashboard</button>
                  {renderTeacherCreator()}
              </div>
          )}

          {view === 'TEACHER_REVIEW' && (
              <div>
                  <button onClick={() => setView('TEACHER_LIST')} className="mb-4 text-gray-500 hover:text-black dark:text-gray-400">← Back to Dashboard</button>
                  {renderTeacherReview()}
              </div>
          )}
      </div>
  );
};

export default AssignmentManager;

