class PaperCheckerAgent {
    async evaluateSubmission(assignment, studentAnswers) {
        return await this.callAI(`
            Evaluate student answers against assignment.
            Assignment: ${JSON.stringify(assignment)}
            Student Answers: ${JSON.stringify(studentAnswers)}

            Provide unbiased evaluation with:
            1. Marks for each question
            2. Detailed feedback
            3. Common mistakes identified
            4. Percentage score
            5. Grade (A, B, C, etc.)

            Return in structured JSON format.
        `);
    }
}

