// Agent 1: Assignment Generator
export const generateAssignmentFromPrompt = async (
    userPrompt: string, 
    subject: string, 
    grade: string, 
    type: QuestionType, 
    marks: number
): Promise<Question[]> => {
  const client = await getClient();
  const prompt = `
    You are an AI Assignment Generator Agent.
    User Request: "${userPrompt}"
    Subject: ${subject}
    Grade Level: ${grade}
    Question Type: ${type}
    Total Marks: ${marks}

    Generate 5 high-quality questions based on this.
    For 'ORAL' type questions, provide a prompt that requires a spoken answer.
    Allocated marks should sum up to ${marks}.
    Return JSON array.
  `;

  const schema: Schema = {
    type: Type.ARRAY,
    items: {
      type: Type.OBJECT,
      properties: {
        id: { type: Type.INTEGER },
        text: { type: Type.STRING },
        type: { type: Type.STRING, enum: ["MCQ", "SHORT", "LONG", "ONE_WORD", "FILL_BLANKS", "TRUE_FALSE", "ORAL"] },
        options: { type: Type.ARRAY, items: { type: Type.STRING } },
        correctAnswer: { type: Type.STRING },
        explanation: { type: Type.STRING },
        difficulty: { type: Type.STRING, enum: ["Easy", "Medium", "Hard"] },
        marks: { type: Type.INTEGER }
      },
      required: ["text", "type", "difficulty", "marks", "explanation"]
    }
  };

  const response = await client.models.generateContent({
    model: 'gemini-2.5-flash',
    contents: prompt,
    config: { responseMimeType: "application/json", responseSchema: schema }
  });

  const raw = JSON.parse(response.text || "[]");
  return raw.map((q: any, i: number) => ({ ...q, id: Date.now() + i }));
};

// Agent 2: Paper Checker
export const evaluateSubmission = async (
    questions: Question[], 
    answers: Record<number, string>
): Promise<{ score: number, feedback: string }> => {
    const client = await getClient();

    // Prepare context
    const context = questions.map(q => ({
        question: q.text,
        correctAnswer: q.correctAnswer,
        studentAnswer: answers[q.id] || "No Answer",
        maxMarks: q.marks || 1
    }));

    const prompt = `
        You are an AI Paper Checker Agent.
        Evaluate the student's answers against the correct answers.

        Data: ${JSON.stringify(context)}

        Task:
        1. Calculate the total score gained.
        2. Provide a constructive feedback summary (max 100 words).
        3. Be fair and unbiased. For subjective answers (Short/Long/Oral), use best judgment based on relevance to correct answer.

        Return JSON.
    `;

    const schema: Schema = {
        type: Type.OBJECT,
        properties: {
            score: { type: Type.NUMBER },
            feedback: { type: Type.STRING }
        },
        required: ["score", "feedback"]
    };

    const response = await client.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt,
        config: { responseMimeType: "application/json", responseSchema: schema }
    });

    return JSON.parse(response.text || "{\"score\": 0, \"feedback\": \"Error evaluating\"}");
};

// Agent 3: Result Formulator
export const generateClassReport = async (submissions: AssignmentSubmission[]): Promise<string> => {
    const client = await getClient();

    // Anonymize and summarize
    const summaryData = submissions.map(s => ({
        student: s.studentName,
        score: s.score,
        status: s.status
    }));

    const prompt = `
        You are an AI Result Formulator Agent.
        Generate a comprehensive class performance report based on this data:
        ${JSON.stringify(summaryData)}

        Include:
        1. Class Average
        2. Top Performers
        3. Areas of Improvement
        4. Teacher Remarks

        Format as Markdown.
    `;

    const response = await client.models.generateContent({
        model: 'gemini-2.5-flash',
        contents: prompt
    });

    return response.text || "Report generation failed.";
};

