// AI Test Creator Agent
class TestCreatorAgent {
    async createTest(prompt, subject, type) {
        const aiResponse = await this.callAI(`
            Create a ${type} for ${subject} based on: "${prompt}"

            Requirements:
            1. Generate appropriate questions
            2. Include answer key
            3. Set marks distribution
            4. Add instructions
            5. Ensure grade-level appropriateness

            Return in structured JSON format.
        `);
        return this.formatTest(aiResponse);
    }
}

// AI Test Checker Agent
class TestCheckerAgent {
    async evaluateTest(submission, answerKey) {
        return await this.callAI(`
            Evaluate student submission against answer key.

            Submission: ${JSON.stringify(submission.answers)}
            Answer Key: ${JSON.stringify(answerKey)}

            Provide:
            1. Marks for each question
            2. Total score
            3. Feedback per question
            4. Common mistakes
            5. Suggested grade

            Be unbiased and consistent.
        `);
    }
}

// Result Formatter Agent
class ResultFormatterAgent {
    async formatResults(studentMarks, classStats) {
        return await this.callAI(`
            Format test results for student.

            Student Marks: ${JSON.stringify(studentMarks)}
            Class Statistics: ${JSON.stringify(classStats)}

            Create:
            1. Clear marks breakdown
            2. Comparative performance
            3. Strengths identified
            4. Areas for improvement
            5. Encouraging remarks
        `);
    }
}class NotificationSystem {
    // Send to student
    sendResultNotification(studentId, assessmentId, marks) {
        const notification = {
            type: 'result_published',
            message: `Your ${assessment.type} results are out! You scored ${marks}/${assessment.total_marks}`,
            data: { assessmentId, marks }
        };
        this.sendToStudent(studentId, notification);
    }

    // Send to teacher
    sendQueryNotification(teacherId, studentId, assessmentId) {
        const notification = {
            type: 'student_query',
            message: `${student.name} has a query about ${assessment.title}`,
            data: { studentId, assessmentId }
        };
        this.sendToTeacher(teacherId, notification);
    }
}class PDFGenerator {
    async generateAssessmentPDF(assessment, includeAnswers = false) {
        const doc = new jsPDF();

        // Header
        doc.setFontSize(20);
        doc.text(assessment.title, 20, 20);

        // Description section
        doc.setFontSize(12);
        doc.text(`Subject: ${assessment.subject}`, 20, 40);
        doc.text(`Type: ${assessment.type}`, 20, 50);
        doc.text(`Marks: ${assessment.total_marks}`, 20, 60);
        doc.text(`Due: ${assessment.dueDate}`, 20, 70);

        // Questions
        let y = 90;
        assessment.questions.forEach((q, i) => {
            doc.text(`${i+1}. ${q.text} [${q.marks} marks]`, 20, y);
            y += 10;

            if (includeAnswers && q.correctAnswer) {
                doc.text(`Answer: ${q.correctAnswer}`, 25, y);
                y += 10;
            }
            y += 10;
        });

        return doc.output('blob');
    }
}
## **Key Features Summary:**

1. **Assignment Description** instead of Settings
2. **No prompt text shown** to students
3. **Save as Draft & Deploy Later** functionality
4. **Dual system**: Assignments & Tests
5. **AI Agents**: Creator + Checker + Result Formatter
6. **"AI Check" button** on each submission
7. **Manual grading option** alongside AI
8. **Automatic notifications** to students when results published
9. **Student query system** for dissatisfaction
10. **Teacher re-check capability** with result sync
11. **Two-way feedback** with audit trail
12. **Real-time updates** and notifications
13. **PDF generation** for offline use
14. **Professional result display** with question-wise breakdown

This system creates a complete, fair, and transparent assessment ecosystem where AI assists but doesn't replace teacher judgment, and students have proper channels for feedback and clarification.

