                                          <div className="grid grid-cols-2 gap-4 text-xs">
                                              <p className="text-green-600"><strong>Correct:</strong> {q.correctAnswer}</p>
                                              {q.modelAnswer && <p className="text-purple-600"><strong>Model:</strong> {q.modelAnswer}</p>}
                                          </div>
                                      </div>
