        // Verify teacher owns classroom
        const isOwner = await this.verifyOwnership(classroomId, teacherId);
        if (!isOwner) throw new Error('Permission denied');

        // Remove student from classroom members
        await database.removeClassroomMember(classroomId, studentId);

        // Update student count
        await database.updateStudentCount(classroomId, -1);

        // Log the action
        await this.logKickAction(classroomId, studentId, teacherId, reason);

        // Notify student
        await notificationService.send({
            to: studentId,
            type: 'kicked_from_classroom',
            data: { classroomId, reason }
        });

        // Update real-time dashboard
        socketService.broadcastToClassroom(classroomId, 'student_kicked', {
