               {/* LIST VIEW */}
               {classrooms.length === 0 && view === 'LIST' ? (
                   <div className="text-center py-20 bg-gray-50 dark:bg-gray-800/50 rounded-xl border-2 border-dashed border-gray-300 dark:border-gray-700">
