// --- LOGIN SCREEN ---
interface LoginProps {
    onLogin: (role: UserRole, email: string) => void;
    notify: (title: string, msg: string, type: 'INFO'|'SUCCESS'|'ERROR') => void;
}

const LoginScreen: React.FC<LoginProps> = ({ onLogin, notify }) => {
    const [step, setStep] = useState<'EMAIL' | 'OTP'>('EMAIL');
    const [email, setEmail] = useState('');
    const [role, setRole] = useState<UserRole>(UserRole.STUDENT);

    // OTP State
    const [otp, setOtp] = useState(['', '', '', '', '', '']);
    const [serverOtp, setServerOtp] = useState(''); // The 'real' OTP to check against
    const [timer, setTimer] = useState(120); // 2 minutes
    const [attempts, setAttempts] = useState(0);
    const [isLocked, setIsLocked] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState('');

    // Refs for auto-focusing OTP inputs
    const otpRefs = useRef<(HTMLInputElement | null)[]>([]);

    useEffect(() => {
        let interval: any;
        if (step === 'OTP' && timer > 0) {
            interval = setInterval(() => setTimer(prev => prev - 1), 1000);
        }
        return () => clearInterval(interval);
    }, [step, timer]);

    const triggerOtpSend = (targetEmail: string, targetRole?: UserRole) => {
        const emailToSend = targetEmail || email;
        const roleToSet = targetRole || role;

        if (!emailToSend.includes('@') || !emailToSend.endsWith('.com')) {
            setError('Please enter a valid email ending in .com');
            return;
        }

        if (isLocked) {
             setError('Account temporarily locked due to too many failed attempts.');
             return;
        }

        setLoading(true);
        setError('');

        // Judge Mode Logic: Always 123456 for .com
        const code = '123456';

        setTimeout(() => {
            setServerOtp(code);
            setStep('OTP');
            setTimer(120);
            setLoading(false);

            // Auto-fill logic for Judge Mode
            setOtp(['1', '2', '3', '4', '5', '6']);
            // notify('JUDGE MODE ACTIVE', `OTP ${code} has been auto-filled for your convenience.`, 'SUCCESS');
        }, 800);
    };

    const handleEmailSubmit = () => {
        triggerOtpSend(email);
    };

    const handleQuickLogin = (role: UserRole, email: string) => {
        setRole(role);
        setEmail(email);
        triggerOtpSend(email, role);
    };

    const handleOtpChange = (index: number, value: string) => {
        if (isNaN(Number(value))) return;

        const newOtp = [...otp];
        newOtp[index] = value;
        setOtp(newOtp);

        // Auto-focus next input
        if (value && index < 5) {
            otpRefs.current[index + 1]?.focus();
        }
    };

    const handleKeyDown = (index: number, e: React.KeyboardEvent) => {
        if (e.key === 'Backspace' && !otp[index] && index > 0) {
            otpRefs.current[index - 1]?.focus();
        }
    };

    const handleVerify = () => {
        const enteredOtp = otp.join('');

        if (enteredOtp.length !== 6) {
            setError('Please enter the full 6-digit code');
            return;
        }

        setLoading(true);
        setTimeout(() => {
            if (enteredOtp === serverOtp) {
                // SUCCESS
                notify('Login Successful', `Welcome back, ${email.split('@')[0]}!`, 'SUCCESS');

                // Auto-detect role for test accounts if generic login used
                let finalRole = role;
                if(email === 'teacher@myclassroom.com') finalRole = UserRole.TEACHER;
                if(email === 'student@myclassroom.com') finalRole = UserRole.STUDENT;

                onLogin(finalRole, email);
            } else {
                // FAILURE
                setLoading(false);
                setAttempts(prev => prev + 1);
                setOtp(['', '', '', '', '', '']);
                otpRefs.current[0]?.focus();

                if (attempts + 1 >= 5) {
                    setIsLocked(true);
                    setError('Account locked! Too many failed attempts. Try again later.');
                } else {
                    setError(`Incorrect OTP. ${5 - (attempts + 1)} attempts remaining.`);
                }
            }
        }, 800);
    };

    const handleResend = () => {
        if (timer > 0) return;
        handleEmailSubmit();
    };

    const formatTime = (seconds: number) => {
        const m = Math.floor(seconds / 60);
        const s = seconds % 60;
        return `${m}:${s < 10 ? '0' : ''}${s}`;
    };

    return (
        <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 font-sans relative overflow-hidden">
            {/* Ambient Background Elements */}
            <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] rounded-full bg-blue-100 blur-3xl opacity-50"></div>
            <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] rounded-full bg-teal-100 blur-3xl opacity-50"></div>

            <div className="max-w-md w-full bg-white rounded-3xl shadow-2xl relative z-10 p-8 md:p-10 border border-slate-100">

                {/* BRAND HEADER */}
                <div className="text-center mb-10">
                    <div className="inline-flex items-center justify-center p-3 bg-gradient-to-br from-blue-50 to-teal-50 rounded-2xl mb-4 shadow-inner">
                        <Sparkles className="w-8 h-8 text-blue-600" />
                    </div>
                    <h1 className="text-3xl font-bold text-slate-900 tracking-tight">MyClassroom<span className="text-teal-600">.AI</span></h1>
                    <p className="text-slate-500 mt-2 font-medium">Your intelligent learning companion</p>
                </div>

                {step === 'EMAIL' ? (
                    <div className="space-y-8 animate-fade-in">
                        {/* Modern Pill Role Selector */}
                        <div className="bg-slate-100 p-1.5 rounded-xl flex relative">
                            <button
                                onClick={() => setRole(UserRole.STUDENT)}
                                className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-lg text-sm font-bold transition-all duration-300 z-10 ${role === UserRole.STUDENT ? 'bg-white text-blue-700 shadow-md transform scale-[1.02]' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                <GraduationCap className="w-4 h-4" />
                                Student
                            </button>
                            <button
                                onClick={() => setRole(UserRole.TEACHER)}
                                className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-lg text-sm font-bold transition-all duration-300 z-10 ${role === UserRole.TEACHER ? 'bg-white text-blue-700 shadow-md transform scale-[1.02]' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                <School className="w-4 h-4" />
                                Teacher
                            </button>
                        </div>

                        {/* Email Input */}
                        <div className="space-y-2">
                            <label className="block text-xs font-bold text-slate-400 uppercase tracking-wider ml-1">Academic Email</label>
                            <div className="relative group">
                                <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                                    <Mail className="h-5 w-5 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
                                </div>
                                <input 
                                    type="email" 
                                    className={`block w-full pl-11 pr-4 py-4 bg-slate-50 border rounded-xl text-slate-900 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 transition-all font-medium ${error ? 'border-red-300 bg-red-50/50' : 'border-slate-200'}`}
                                    placeholder="name@school.com"
                                    value={email}
                                    onChange={e => { setEmail(e.target.value); setError(''); }}
                                    onKeyDown={e => e.key === 'Enter' && handleEmailSubmit()}
                                />
                            </div>

                            {error ? (
                                <p className="text-xs text-red-500 font-medium flex items-center gap-1.5 ml-1 animate-pulse">
                                    <AlertTriangle className="w-3 h-3"/> {error}
                                </p>
                            ) : (
                                <p className="text-[11px] text-teal-600 font-medium flex items-center gap-1.5 ml-1 bg-teal-50 w-fit px-2 py-1 rounded-md">
                                    <CheckCircle className="w-3 h-3" /> Auto-OTP active for .com domains
                                </p>
                            )}
                        </div>

                        {/* Main CTA */}
                        <button 
                            onClick={handleEmailSubmit}
                            disabled={loading || !email}
                            className="w-full bg-gradient-to-r from-blue-700 to-teal-600 hover:from-blue-800 hover:to-teal-700 text-white font-bold py-4 rounded-xl shadow-lg shadow-blue-500/20 hover:shadow-blue-500/30 transition-all transform active:scale-[0.98] disabled:opacity-70 disabled:cursor-not-allowed flex justify-center items-center gap-2 group"
                        >
                            {loading ? <Loader2 className="animate-spin w-5 h-5" /> : (
                                <>
                                    Get Secure Code
                                    <ArrowRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
                                </>
                            )}
                        </button>

                        {/* Rapid Testing Footer */}
                        <div className="pt-6 mt-2 border-t border-slate-100">
                            <p className="text-[10px] font-bold text-slate-400 uppercase text-center mb-4 tracking-widest">Rapid Developer Access</p>
                            <div className="grid grid-cols-2 gap-3">
                                <button onClick={() => handleQuickLogin(UserRole.TEACHER, 'teacher@myclassroom.com')} className="flex flex-col items-center justify-center p-3 rounded-xl border border-slate-100 hover:border-blue-200 hover:bg-blue-50/50 transition-all group">
                                    <span className="text-xs font-bold text-slate-600 group-hover:text-blue-700">Teacher Demo</span>
                                    <span className="text-[10px] text-slate-400">@myclassroom.com</span>
                                </button>
                                <button onClick={() => handleQuickLogin(UserRole.STUDENT, 'student@myclassroom.com')} className="flex flex-col items-center justify-center p-3 rounded-xl border border-slate-100 hover:border-teal-200 hover:bg-teal-50/50 transition-all group">
                                    <span className="text-xs font-bold text-slate-600 group-hover:text-teal-700">Student Demo</span>
                                    <span className="text-[10px] text-slate-400">@myclassroom.com</span>
                                </button>
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="space-y-8 animate-fade-in text-center">
                        <div className="space-y-2">
                            <h2 className="text-xl font-bold text-slate-800">Verify Identity</h2>
                            <p className="text-slate-500 text-sm">
                                Enter the code sent to <br/>
                                <span className="font-bold text-slate-700">{email}</span>
                            </p>
                        </div>

                        {/* Development Badge */}
                        <div className="inline-flex items-center gap-2 px-4 py-2 bg-green-50 text-green-700 rounded-full border border-green-100 text-xs font-bold animate-pulse">
                            <Key className="w-3 h-3" />
                            Development Mode: 123456 Auto-Filled
                        </div>

                        {/* OTP Inputs */}
                        <div className="flex justify-center gap-2">
                            {otp.map((digit, idx) => (
                                <input
                                    key={idx}
                                    ref={el => otpRefs.current[idx] = el}
                                    type="text"
                                    maxLength={1}
                                    value={digit}
                                    onChange={e => handleOtpChange(idx, e.target.value)}
                                    onKeyDown={e => handleKeyDown(idx, e)}
                                    className={`w-12 h-14 text-center text-2xl font-bold rounded-xl border-2 outline-none transition-all focus:ring-4 focus:ring-blue-100 ${
                                        error ? 'border-red-300 bg-red-50 text-red-600' : 
                                        digit ? 'border-blue-500 bg-white text-slate-800' : 'border-slate-200 bg-slate-50 text-slate-800'
                                    }`}
                                    disabled={isLocked}
                                />
                            ))}
                        </div>

                        {error && (
                            <div className="text-red-500 text-sm font-medium flex items-center justify-center gap-2">
                                <AlertTriangle className="w-4 h-4" />
                                {error}
                            </div>
                        )}

                        <button 
                            onClick={handleVerify}
                            disabled={loading || isLocked}
                            className="w-full bg-gradient-to-r from-blue-700 to-teal-600 hover:from-blue-800 hover:to-teal-700 text-white font-bold py-4 rounded-xl shadow-lg transition-all transform active:scale-[0.98] disabled:opacity-70 flex justify-center items-center gap-2"
                        >
                            {loading ? <Loader2 className="animate-spin w-5 h-5" /> : 'Verify & Enter Class'}
                        </button>

                        <div className="flex justify-between items-center text-sm px-2">
                            <button onClick={() => setStep('EMAIL')} className="text-slate-400 hover:text-slate-600 font-medium">
                                Change Email
                            </button>
                            <button 
                                onClick={handleResend}
                                disabled={timer > 0 || isLocked}
                                className={`flex items-center gap-1.5 font-bold ${timer > 0 ? 'text-slate-300 cursor-not-allowed' : 'text-blue-600 hover:text-blue-700'}`}
                            >
                                {timer > 0 ? (
                                    <span>Resend in {formatTime(timer)}</span>
                                ) : (
                                    <>
                                        <RefreshCw className="w-3.5 h-3.5"/> Resend Code
                                    </>
                                )}
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* Footer Branding */}
            <div className="absolute bottom-6 text-center w-full">
                <p className="text-xs text-slate-400 font-medium">
                    &copy; 2024 MyClassroom.AI • Secure Educational Platform
                </p>
            </div>
        </div>
    );
};

