                              <div className="flex items-center gap-3"><CheckCircle className="w-5 h-5"/> <span>Proctored Exams</span></div>
                              <div className="flex items-center gap-3"><CheckCircle className="w-5 h-5"/> <span>Smart Notes</span></div>
