                     n.type === 'ERROR' ? 'bg-red-600 text-white' : 
                     'bg-blue-600 text-white'
                 }`}>
                     <Bell className="w-5 h-5" />
                     <div>
                         <p className="font-bold text-sm">{n.title}</p>
                         <p className="text-xs opacity-90">{n.message}</p>
                     </div>
                 </div>
             ))}
         </div>

         {!onboardingComplete && <OnboardingTour onComplete={handleCompleteOnboarding} />}

         <JudgeControls 
            onLogout={handleLogout} 
            onReset={resetDemo} 
            userRole={user.role} 
            onLoadScenario={(s) => { 
                if (s === 'TEACHER_DEMO') { handleLogout(); setTimeout(() => handleLogin(UserRole.TEACHER), 100); }
                else { handleLogout(); setTimeout(() => handleLogin(UserRole.STUDENT), 100); setView(AppView.TEST_MANAGER); }
            }}
         />

         {/* VIEW ROUTER */}
         {view === AppView.DASHBOARD && <Dashboard user={user} changeView={setView} />}
         {view === AppView.VIDEO_GEN && <VideoGenerator onSave={(script) => { setLibrary(prev => [...prev, { id: Date.now().toString(), type: ContentType.VIDEO, title: script.topic, data: script, dateCreated: new Date().toISOString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 }]); addNotification('Video Saved', 'Saved to My Library', 'SUCCESS'); }} />}
         {view === AppView.EBOOK_GEN && <EbookGenerator onSave={(title, content) => { setLibrary(prev => [...prev, { id: Date.now().toString(), type: ContentType.EBOOK, title, data: content, dateCreated: new Date().toISOString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 }]); addNotification('Ebook Saved', 'Saved to My Library', 'SUCCESS'); }} />}
         {view === AppView.NOTES_GEN && <NotesGenerator onSave={(item) => { setLibrary(prev => [...prev, { ...item, id: Date.now().toString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 } as LibraryItem]); }} />}
         {view === AppView.PPT_GEN && <PPTGenerator onSave={(ppt) => { setLibrary(prev => [...prev, { id: Date.now().toString(), type: ContentType.PPT, title: ppt.topic, data: ppt, dateCreated: new Date().toISOString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 }]); addNotification('Presentation Saved', 'Saved to My Library', 'SUCCESS'); }} />}

         {view === AppView.TEST_MANAGER && <TestManager 
                user={user} 
                globalTests={tests} 
                testHistory={testResults.filter(r => r.studentId === user.id)} 
                classrooms={classrooms}
                onAddTest={(t) => setTests([...tests, t])} 
                onSaveResult={(r) => { setTestResults([...testResults, r]); addNotification('Test Submitted', 'Results & Violation Report Saved', 'SUCCESS'); }} 
                onDeployTest={(tid, classIds) => {
                    setTests(tests.map(t => t.id === tid ? { ...t, status: 'LIVE', assignedClassIds: classIds } : t));
                    addNotification('Test Deployed', `Students in ${classIds.length} classes notified`, 'EMAIL');
                }}
                onExit={() => setView(AppView.DASHBOARD)}
         />}

         {view === AppView.CLASSROOMS && <ClassroomManager 
                user={user} 
                classrooms={classrooms}
                assignments={assignments}
                tests={tests}
                testResults={testResults}
                onCreate={(c) => setClassrooms([...classrooms, c])} 
                onJoin={() => ({ success: true, message: 'Joined!' })} 
                onUpdate={(c) => setClassrooms(classrooms.map(cl => cl.id === c.id ? c : cl))}
         />}

         {view === AppView.LIBRARY && <Library 
                items={library} 
                user={user} 
                friends={friends}
                onUpdateItem={(id, updates) => setLibrary(library.map(i => i.id === id ? { ...i, ...updates } : i))}
                onDeletePermanent={(id) => setLibrary(library.filter(i => i.id !== id))}
                onImport={(item) => {
                    const newItem = { ...item, id: Date.now().toString(), userId: user.id, imports: 0, originalOwnerId: item.userId, originalOwnerName: `Friend ${item.userId.substring(item.userId.length-4)}` };
                    setLibrary([...library, newItem]);
                    // Update original import count (mock)
                    setLibrary(prev => prev.map(i => i.id === item.id ? { ...i, imports: (i.imports || 0) + 1 } : i));
                    addNotification('Content Imported', `${item.title} added to your library.`, 'SUCCESS');
                }}
         />}

         {view === AppView.ASSIGNMENTS && <AssignmentManager 
            user={user} 
            assignments={assignments} 
            setAssignments={setAssignments} 
            classrooms={classrooms}
         />}

         {view === AppView.SOCIAL && <SocialManager 
            user={user} 
            friends={friends} 
            sendRequest={(uid) => {
                if (uid === user.id) return { success: false, message: "Cannot invite yourself." };
                if (friends.includes(uid)) return { success: false, message: "Already connected." };
                setFriends([...friends, uid]);
                return { success: true, message: "Invitation Sent!" };
            }}
         />}

         {view === AppView.PROFILE && <ProfileManager user={user} onUpdate={setUser} />}
         {view === AppView.DOUBT_TUTOR && <DoubtTutor />}
         {view === AppView.LEARNING_PATH && <LearningPathBuilder />}
         {view === AppView.ANALYTICS && <AnalyticsDashboard />}

         {/* Extra Views */}
         {view === AppView.VIRTUAL_LAB && renderVirtualLab()}
         {view === AppView.CAREER_PATH && renderCareerPath()}

      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { generatePPT } from '../services/gemini';
import { Presentation } from '../types';
import { Presentation as PresentationIcon, Loader2, Download, Share2 } from 'lucide-react';
import { jsPDF } from "jspdf";

interface PPTGeneratorProps {
  onSave: (ppt: Presentation) => void;
}

const PPTGenerator: React.FC<PPTGeneratorProps> = ({ onSave }) => {
  const [topic, setTopic] = useState('');
  const [loading, setLoading] = useState(false);
  const [ppt, setPpt] = useState<Presentation | null>(null);
  const [activeSlide, setActiveSlide] = useState(0);
  const [exporting, setExporting] = useState(false);

  const handleGenerate = async () => {
    setLoading(true);
    try {
      const result = await generatePPT(topic, 5);
      setPpt(result);
      onSave(result); // Auto-save to library
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleExportPDF = () => {
      if (!ppt) return;
      setExporting(true);

      try {
          // Create PDF in landscape mode for PPT feel
          const doc = new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'a4' });
          const width = doc.internal.pageSize.getWidth();
          const height = doc.internal.pageSize.getHeight();
          const margin = 20;

          ppt.slides.forEach((slide, index) => {
              if (index > 0) doc.addPage();

              // Background (Simple styling)
              doc.setFillColor(248, 250, 252); // slate-50
              doc.rect(0, 0, width, height, 'F');

              // Slide Number
              doc.setFontSize(10);
              doc.setTextColor(150, 150, 150);
              doc.text(`Slide ${index + 1}`, width - margin, margin, { align: 'right' });

              // Title
              doc.setFontSize(24);
              doc.setTextColor(30, 41, 59); // slate-800
              doc.setFont("helvetica", "bold");
              const titleLines = doc.splitTextToSize(slide.title, width - (margin * 2));
              doc.text(titleLines, margin, margin + 10);

              let yPos = margin + 10 + (titleLines.length * 10) + 10;

              // Content Area (Bullets)
              doc.setFontSize(16);
              doc.setFont("helvetica", "normal");
              doc.setTextColor(51, 65, 85); // slate-700

              slide.bullets.forEach((bullet) => {
                  const bulletText = `• ${bullet}`;
                  const bulletLines = doc.splitTextToSize(bulletText, width - (margin * 2) - 10);

                  // Check if page overflow
                  if (yPos + (bulletLines.length * 8) > height - 40) {
                      doc.addPage();
                      yPos = margin;
                  }

                  doc.text(bulletLines, margin + 5, yPos);
                  yPos += (bulletLines.length * 8) + 4;
              });

              // Image Description Box (Placeholder)
              yPos += 10;
              // Ensure we don't draw off page
              if (yPos + 40 < height - 30) {
                doc.setDrawColor(203, 213, 225); // slate-300
                doc.setFillColor(255, 255, 255);
                doc.roundedRect(margin, yPos, width - (margin * 2), 40, 3, 3, 'FD');

                doc.setFontSize(10);
                doc.setTextColor(100, 116, 139); // slate-500
                doc.setFont("helvetica", "italic");
                doc.text("Image Suggestion:", margin + 5, yPos + 8);

                doc.setFont("helvetica", "normal");
                doc.setTextColor(71, 85, 105);
                const imgLines = doc.splitTextToSize(slide.imageDescription, width - (margin * 2) - 10);
                doc.text(imgLines, margin + 5, yPos + 15);
              }

              // Speaker Notes
              const notesY = height - 30;
              doc.setDrawColor(226, 232, 240); // slate-200
              doc.line(margin, notesY, width - margin, notesY);

              doc.setFontSize(10);
              doc.setTextColor(148, 163, 184); // slate-400
              doc.setFont("helvetica", "bold");
              doc.text("SPEAKER NOTES", margin, notesY + 5);

              doc.setFont("helvetica", "normal");
              doc.setTextColor(100, 116, 139);
              const notesLines = doc.splitTextToSize(slide.speakerNotes, width - (margin * 2));
              doc.text(notesLines, margin, notesY + 10);
          });

          // Filename cleanup
          const safeTitle = ppt.topic.replace(/[^a-z0-9]/gi, '_').substring(0, 30);
          doc.save(`${safeTitle}_Presentation.pdf`);

      } catch (e) {
          console.error("PDF Export failed", e);
          alert("Failed to export PDF.");
      } finally {
          setExporting(false);
      }
  };

  return (
    <div className="p-6 max-w-6xl mx-auto h-[calc(100vh-2rem)] flex flex-col">
      <div className="flex items-center justify-between mb-6">
        <h2 className="text-3xl font-bold text-gray-800 dark:text-white flex items-center gap-2">
          <PresentationIcon className="w-8 h-8 text-orange-500" />
          AI PPT Creator
        </h2>
        {ppt && (
             <button 
                onClick={handleExportPDF}
                disabled={exporting}
                className="flex items-center gap-2 bg-blue-600 text-white px-4 py-2 rounded-lg hover:bg-blue-700 shadow-md disabled:opacity-50 transition-all"
            >
                 {exporting ? <Loader2 className="w-4 h-4 animate-spin"/> : <Download className="w-4 h-4"/>} 
                 {exporting ? 'Generating PDF...' : 'Export PDF'}
             </button>
        )}
      </div>

      {!ppt ? (
        <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-lg border border-gray-200 dark:border-gray-700">
           <div className="max-w-xl mx-auto space-y-4">
              <label className="block font-medium dark:text-gray-300">Presentation Topic</label>
              <input 
                value={topic}
                onChange={e => setTopic(e.target.value)}
                placeholder="e.g. The Solar System, History of Rome"
                className="w-full p-3 border rounded-lg dark:bg-gray-900 dark:border-gray-700 dark:text-white"
              />
              <button 
                onClick={handleGenerate}
                disabled={loading || !topic}
                className="w-full bg-orange-600 hover:bg-orange-700 text-white py-3 rounded-lg font-bold flex justify-center items-center gap-2"
              >
                {loading ? <Loader2 className="animate-spin" /> : 'Generate Slides'}
              </button>
           </div>
        </div>
      ) : (
        <div className="flex-1 flex gap-6 overflow-hidden">
            {/* Sidebar Slides */}
            <div className="w-64 bg-white dark:bg-gray-800 rounded-xl shadow overflow-y-auto p-4 space-y-4 border border-gray-200 dark:border-gray-700">
                {ppt.slides.map((slide, idx) => (
                    <button 
                        key={idx}
                        onClick={() => setActiveSlide(idx)}
                        className={`w-full text-left p-3 rounded border transition-all ${activeSlide === idx ? 'border-orange-500 ring-1 ring-orange-500 bg-orange-50 dark:bg-orange-900/20' : 'border-gray-200 dark:border-gray-700'}`}
                    >
                        <span className="text-xs font-bold text-gray-400">Slide {idx + 1}</span>
                        <p className="text-sm font-medium truncate dark:text-gray-200">{slide.title}</p>
                    </button>
                ))}
            </div>

            {/* Main Preview */}
            <div className="flex-1 bg-white dark:bg-gray-800 rounded-xl shadow-2xl p-12 border border-gray-200 dark:border-gray-700 flex flex-col">
                <div className="border-b pb-4 mb-8">
                     <h1 className="text-4xl font-bold text-gray-900 dark:text-white">{ppt.slides[activeSlide].title}</h1>
                </div>

                <div className="flex-1 grid grid-cols-2 gap-8">
                    <ul className="space-y-4 list-disc pl-5 text-xl text-gray-700 dark:text-gray-300">
                        {ppt.slides[activeSlide].bullets.map((b, i) => (
                            <li key={i}>{b}</li>
                        ))}
                    </ul>
                    <div className="bg-gray-100 dark:bg-gray-700 rounded-lg flex items-center justify-center text-gray-400 italic p-4 text-center">
                        Image Placeholder: <br/>{ppt.slides[activeSlide].imageDescription}
                    </div>
                </div>

                <div className="mt-8 p-4 bg-yellow-50 dark:bg-yellow-900/20 rounded-lg border border-yellow-100 dark:border-yellow-900/50">
                    <p className="text-sm font-bold text-yellow-800 dark:text-yellow-500 uppercase tracking-wide mb-1">Speaker Notes</p>
                    <p className="text-gray-700 dark:text-gray-300">{ppt.slides[activeSlide].speakerNotes}</p>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default PPTGenerator;

import React, { useState } from 'react';
