      );
  }

  return (
    <div className="flex bg-gray-50 dark:bg-gray-900 min-h-screen text-gray-900 dark:text-gray-100 font-sans transition-colors duration-200">
      <Sidebar 
        currentView={view} 
        onChangeView={setView} 
        onLogout={handleLogout} 
        user={user}
      />

      <main className="flex-1 ml-64 relative">
         <div className="fixed top-4 right-4 z-[60] flex flex-col gap-2">
             {notifications.map(n => (
                 <div key={n.id} className={`p-4 rounded-lg shadow-xl flex items-center gap-3 animate-slide-in min-w-[300px] ${
                     n.type === 'SUCCESS' ? 'bg-green-600 text-white' : 
                     n.type === 'ERROR' ? 'bg-red-600 text-white' : 
                     'bg-blue-600 text-white'
                 }`}>
                     <Bell className="w-5 h-5" />
                     <div>
                         <p className="font-bold text-sm">{n.title}</p>
                         <p className="text-xs opacity-90">{n.message}</p>
                     </div>
                 </div>
             ))}
         </div>

         {!onboardingComplete && <OnboardingTour onComplete={handleCompleteOnboarding} />}

         <JudgeControls 
            onLogout={handleLogout} 
            onReset={resetDemo} 
            userRole={user.role} 
            onLoadScenario={(s) => { 
                if (s === 'TEACHER_DEMO') { handleLogout(); setTimeout(() => handleLogin(UserRole.TEACHER), 100); }
                else { handleLogout(); setTimeout(() => handleLogin(UserRole.STUDENT), 100); setView(AppView.TEST_MANAGER); }
            }}
         />

         {view === AppView.DASHBOARD && <Dashboard user={user} changeView={setView} />}
         {view === AppView.VIDEO_GEN && <VideoGenerator onSave={(script) => { setLibrary(prev => [...prev, { id: Date.now().toString(), type: ContentType.VIDEO, title: script.topic, data: script, dateCreated: new Date().toISOString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 }]); addNotification('Video Saved', 'Saved to My Library', 'SUCCESS'); }} />}
         {view === AppView.EBOOK_GEN && <EbookGenerator onSave={(title, content) => { setLibrary(prev => [...prev, { id: Date.now().toString(), type: ContentType.EBOOK, title, data: content, dateCreated: new Date().toISOString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 }]); addNotification('Ebook Saved', 'Saved to My Library', 'SUCCESS'); }} />}
         {view === AppView.NOTES_GEN && <NotesGenerator onSave={(item) => { setLibrary(prev => [...prev, { ...item, id: Date.now().toString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 } as LibraryItem]); }} />}
         {view === AppView.PPT_GEN && <PPTGenerator onSave={(ppt) => { setLibrary(prev => [...prev, { id: Date.now().toString(), type: ContentType.PPT, title: ppt.topic, data: ppt, dateCreated: new Date().toISOString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 }]); addNotification('Presentation Saved', 'Saved to My Library', 'SUCCESS'); }} />}

         {view === AppView.TEST_MANAGER && <TestManager 
                user={user} 
                globalTests={tests} 
                testHistory={testResults.filter(r => r.studentId === user.id)} 
                classrooms={classrooms}
                onAddTest={(t) => setTests([...tests, t])} 
                onSaveResult={(r) => { setTestResults([...testResults, r]); addNotification('Test Submitted', 'Results & Violation Report Saved', 'SUCCESS'); }} 
                onDeployTest={(tid, classIds) => {
                    setTests(tests.map(t => t.id === tid ? { ...t, status: 'LIVE', assignedClassIds: classIds } : t));
                    addNotification('Test Deployed', `Students in ${classIds.length} classes notified`, 'EMAIL');
                }}
                onPublishResults={(tid) => {
                    setTests(tests.map(t => t.id === tid ? { ...t, resultsPublished: true } : t));
                    addNotification('Results Published', 'Students can now view their scores', 'SUCCESS');
                }}
                onExit={() => setView(AppView.DASHBOARD)}
         />}
         {view === AppView.EXAMINATION && <ExaminationCenter 
            user={user}
            globalTests={tests}
            onAddTest={(t) => setTests([...tests, t])}
            onSaveResult={(r) => { setTestResults([...testResults, r]); addNotification('Public Exam Submitted', 'Result Saved', 'SUCCESS'); }}
         />}
         {view === AppView.DOUBT_TUTOR && <DoubtTutor />}
         {view === AppView.LEARNING_PATH && <LearningPathBuilder />}
         {view === AppView.CLASSROOMS && <ClassroomManager 
            user={user} 
            classrooms={classrooms} 
            assignments={assignments} 
            tests={tests} 
            testResults={testResults} 
            onCreate={(c) => setClassrooms([...classrooms, c])} 
            onJoin={(code) => { 
                const c = classrooms.find(cl => cl.code === code);
                if (!c) return { success: false, message: 'Invalid Class Code' };
                if (c.studentIds.includes(user.id)) return { success: false, message: 'Already Joined' };
                const updated = { ...c, studentIds: [...c.studentIds, user.id] };
                setClassrooms(classrooms.map(cl => cl.id === c.id ? updated : cl));
                return { success: true, message: 'Joined Successfully' };
            }} 
            onUpdate={(updated) => setClassrooms(classrooms.map(c => c.id === updated.id ? updated : c))} 
         />}
         {view === AppView.LIBRARY && <Library 
            items={library} 
            user={user} 
            friends={friends} 
            onUpdateItem={(id, updates) => setLibrary(library.map(i => i.id === id ? { ...i, ...updates } : i))} 
            onDeletePermanent={(id) => setLibrary(library.filter(i => i.id !== id))} 
            onImport={(item) => {
                const newItem = { ...item, id: Date.now().toString(), userId: user.id, isShared: false, imports: 0, originalOwnerId: item.userId, originalOwnerName: 'Friend' };
                setLibrary([...library, newItem]);
                addNotification('Content Imported', 'Saved to your library', 'SUCCESS');
            }} 
         />}
         {view === AppView.ASSIGNMENTS && <AssignmentManager user={user} classrooms={classrooms} assignments={assignments} setAssignments={setAssignments} />}
         {view === AppView.SOCIAL && <SocialManager 
            user={user} 
            friends={friends} 
            sendRequest={(uid) => {
                if (uid === user.id) return { success: false, message: "Cannot invite yourself" };
                if (friends.includes(uid)) return { success: false, message: "Already connected" };
                setFriends([...friends, uid]);
                return { success: true, message: "Friend added to network" };
            }} 
         />}
         {view === AppView.PROFILE && <ProfileManager user={user} onUpdate={(u) => { setUser(u); addNotification('Profile Updated', 'Changes saved', 'SUCCESS'); }} />}
         {view === AppView.ANALYTICS && <AnalyticsDashboard />}
         {view === AppView.VIRTUAL_LAB && renderVirtualLab()}
         {view === AppView.CAREER_PATH && renderCareerPath()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { generateTest, analyzeProctoringFrame } from '../services/gemini';
import { TestData, User, TestResult, QuestionType } from '../types';
import { 
    Play, Plus, Loader2, ShieldCheck, Hash, 
    Copy, CheckCircle, Sparkles, Send, Mic, 
    Camera, Eye, Activity, Clock, ShieldAlert, X
} from 'lucide-react';
import confetti from 'canvas-confetti';

interface ExaminationCenterProps {
    user: User;
    globalTests: TestData[];
    onAddTest: (test: TestData) => void;
    onSaveResult: (result: TestResult) => void;
}

const ExaminationCenter: React.FC<ExaminationCenterProps> = ({ user, globalTests, onAddTest, onSaveResult }) => {
    const [view, setView] = useState<'HUB' | 'GENERATING' | 'CODE_REVEAL' | 'PERMISSIONS' | 'TAKING' | 'SUBMITTING'>('HUB');
    const [joinCode, setJoinCode] = useState('');
    const [prompt, setPrompt] = useState('');
    const [generatedCode, setGeneratedCode] = useState('');
    const [activeTest, setActiveTest] = useState<TestData | null>(null);
    const [copied, setCopied] = useState(false);

    // TAKE EXAM STATE
    const [answers, setAnswers] = useState<Record<number, string>>({});
    const [timeLeft, setTimeLeft] = useState(0);
    const [warnings, setWarnings] = useState(0);
    const [audioLevel, setAudioLevel] = useState(0);
    const [proctorStatus, setProctorStatus] = useState('Monitoring');

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const lastViolationRef = useRef<number>(0);

    const handleGenerate = async () => {
        if (!prompt) return;
        setView('GENERATING');
        try {
            const data = await generateTest(prompt, 'Medium', 5);
            const code = Math.floor(100000 + Math.random() * 899999).toString();
            const newTest: TestData = {
                ...data,
                id: Date.now().toString(),
                creatorId: user.id,
                accessCode: code,
                status: 'LIVE',
                settings: { ...data.settings, proctoring: true }
            };
            onAddTest(newTest);
            setGeneratedCode(code);
            setView('CODE_REVEAL');
        } catch (e) {
            console.error(e);
            alert("Failed to generate test. Try again.");
            setView('HUB');
        }
    };

    const handleJoin = () => {
        const test = globalTests.find(t => t.accessCode === joinCode);
        if (test) {
            setActiveTest(test);
            setView('PERMISSIONS');
        } else {
            alert("Invalid Examination Code.");
        }
    };

    const requestPermissions = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ 
                video: { facingMode: 'user' }, 
                audio: true 
            });
            streamRef.current = stream;
            setView('TAKING');
        } catch (e) {
            alert("Permission Denied: Camera and Microphone are required.");
        }
    };

    // PROCTORING SYSTEM
    useEffect(() => {
        let visionInterval: any;
        let audioInterval: any;

        if (view === 'TAKING' && streamRef.current) {
            if (videoRef.current) videoRef.current.srcObject = streamRef.current;

            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            audioContextRef.current = new AudioContext();
            analyserRef.current = audioContextRef.current.createAnalyser();
            const source = audioContextRef.current.createMediaStreamSource(streamRef.current);
            source.connect(analyserRef.current);
            if (audioContextRef.current.state === 'suspended') audioContextRef.current.resume();

            visionInterval = setInterval(async () => {
                if (!videoRef.current) return;
                const canvas = document.createElement('canvas');
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;
                ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                setProctorStatus('Analyzing...');
                const res = await analyzeProctoringFrame(base64);
                if (res.suspicious) triggerViolation(`AI Alert: ${res.reason}`);
                setProctorStatus('Monitoring');
            }, 5000);

            audioInterval = setInterval(() => {
                if (!analyserRef.current) return;
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteFrequencyData(data);
                const avg = data.reduce((a, b) => a + b) / data.length;
                setAudioLevel(avg);
                if (avg > 15) triggerViolation("Noise Detected");
            }, 200);
        }

        return () => {
            clearInterval(visionInterval);
            clearInterval(audioInterval);
        };
    }, [view]);

    const triggerViolation = (reason: string) => {
        const now = Date.now();
        if (now - lastViolationRef.current < 4000) return;
        lastViolationRef.current = now;
        setWarnings(prev => {
            const next = prev + 1;
            if (next >= 5) submitExam(true);
            return next;
        });
        showViolationToast(reason);
    };

    const showViolationToast = (msg: string) => {
        const toast = document.createElement('div');
        toast.className = "fixed top-8 left-1/2 -translate-x-1/2 bg-red-600 text-white px-6 py-3 rounded-2xl shadow-2xl z-[999] animate-bounce font-bold border-2 border-white";
        toast.innerText = `⚠️ PROCTOR ALERT: ${msg}`;
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 3000);
    };

    const submitExam = (auto = false) => {
        setView('SUBMITTING');
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        setTimeout(() => {
            const result: TestResult = {
                testId: activeTest?.id || 'public',
                studentId: user.id,
                score: Object.keys(answers).length, // Simplified mock score
                maxScore: activeTest?.questions.length || 0,
                answers,
                dateTaken: new Date().toISOString(),
                status: 'COMPLETED',
                autoSubmitted: auto
            };
            onSaveResult(result);
            confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 } });
            setView('HUB');
            setJoinCode('');
        }, 2000);
    };

    useEffect(() => {
        let t: any;
        if (view === 'TAKING' && activeTest) {
            if (timeLeft === 0) setTimeLeft(activeTest.settings.timeLimitMinutes * 60);
            t = setInterval(() => setTimeLeft(prev => prev > 0 ? prev - 1 : (submitExam(true), 0)), 1000);
        }
        return () => clearInterval(t);
    }, [view, timeLeft, activeTest]);

    return (
        <div className="p-6 max-w-6xl mx-auto min-h-[calc(100vh-4rem)] flex flex-col">
            {view === 'HUB' && (
                <div className="flex-1 flex flex-col justify-center animate-fade-in">
                    <div className="text-center mb-12">
                        <h1 className="text-5xl font-black mb-4 bg-gradient-to-r from-red-600 to-indigo-600 bg-clip-text text-transparent">Examination Arena</h1>
                        <p className="text-gray-500 text-xl">The public hub for secure, AI-powered academic testing.</p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-12 max-w-5xl mx-auto w-full">
                        {/* JOIN CARD */}
                        <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] p-10 shadow-2xl border border-gray-100 dark:border-gray-700 hover:scale-[1.02] transition-transform flex flex-col group">
                            <div className="w-16 h-16 bg-red-100 dark:bg-red-900/30 rounded-3xl flex items-center justify-center mb-8 group-hover:rotate-6 transition-transform">
                                <Play className="w-8 h-8 text-red-600" />
                            </div>
                            <h2 className="text-3xl font-bold dark:text-white mb-4">Enter the Arena</h2>
                            <p className="text-gray-500 mb-8 flex-1">Participate in an ongoing examination by entering your unique session code.</p>
                            <div className="space-y-4">
                                <div className="relative">
                                    <Hash className="absolute left-4 top-4 text-gray-400" />
                                    <input 
                                        value={joinCode}
                                        onChange={e => setJoinCode(e.target.value.toUpperCase())}
                                        placeholder="EXAM CODE"
                                        className="w-full pl-12 p-4 bg-gray-50 dark:bg-gray-900 rounded-2xl border-none font-mono text-xl focus:ring-2 focus:ring-red-500 dark:text-white"
                                    />
                                </div>
                                <button 
                                    onClick={handleJoin}
                                    disabled={!joinCode}
                                    className="w-full py-4 bg-red-600 hover:bg-red-700 text-white rounded-2xl font-bold text-lg shadow-xl disabled:opacity-50"
                                >
                                    Begin Proctored Session
                                </button>
                            </div>
                        </div>

                        {/* HOST CARD */}
                        <div className="bg-white dark:bg-gray-800 rounded-[2.5rem] p-10 shadow-2xl border border-gray-100 dark:border-gray-700 hover:scale-[1.02] transition-transform flex flex-col group">
                            <div className="w-16 h-16 bg-indigo-100 dark:bg-indigo-900/30 rounded-3xl flex items-center justify-center mb-8 group-hover:-rotate-6 transition-transform">
                                <Plus className="w-8 h-8 text-indigo-600" />
                            </div>
                            <h2 className="text-3xl font-bold dark:text-white mb-4">The Architect</h2>
                            <p className="text-gray-500 mb-8 flex-1">Use AI to build a custom examination on any topic and generate a joinable code for others.</p>
                            <div className="space-y-4">
                                <div className="relative">
                                    <Sparkles className="absolute left-4 top-4 text-gray-400" />
                                    <input 
                                        value={prompt}
                                        onChange={e => setPrompt(e.target.value)}
                                        placeholder="TOPIC (e.g. Modern History)"
                                        className="w-full pl-12 p-4 bg-gray-50 dark:bg-gray-900 rounded-2xl border-none text-lg focus:ring-2 focus:ring-indigo-500 dark:text-white"
                                    />
                                </div>
                                <button 
                                    onClick={handleGenerate}
                                    disabled={!prompt}
                                    className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold text-lg shadow-xl disabled:opacity-50"
                                >
                                    Generate & Open Hall
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {view === 'GENERATING' && (
                <div className="flex-1 flex flex-col items-center justify-center text-center">
                    <Loader2 className="w-20 h-20 text-indigo-600 animate-spin mb-6" />
                    <h2 className="text-3xl font-black dark:text-white">AI Agent is generating the exam hall...</h2>
                    <p className="text-gray-500 mt-2">Configuring proctoring parameters and question bank.</p>
                </div>
            )}

            {view === 'CODE_REVEAL' && (
                <div className="flex-1 flex flex-col items-center justify-center text-center animate-scale-in">
                    <div className="bg-white dark:bg-gray-800 p-12 rounded-[3rem] shadow-2xl border border-indigo-100 dark:border-gray-700 max-w-xl w-full">
                        <CheckCircle className="w-20 h-20 text-green-500 mx-auto mb-6" />
                        <h2 className="text-4xl font-black mb-2 dark:text-white">Hall is Open!</h2>
                        <p className="text-gray-500 mb-8 text-lg">Share this code with participants. The exam is live.</p>

                        <div className="bg-gray-100 dark:bg-gray-900 p-6 rounded-3xl mb-8 flex items-center justify-between">
                            <span className="text-5xl font-mono font-black tracking-widest text-indigo-600">{generatedCode}</span>
                            <button 
                                onClick={() => { navigator.clipboard.writeText(generatedCode); setCopied(true); setTimeout(() => setCopied(false), 2000); }}
                                className="p-4 bg-white dark:bg-gray-800 rounded-2xl shadow hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                            >
                                {copied ? <CheckCircle className="w-6 h-6 text-green-500" /> : <Copy className="w-6 h-6 text-gray-500" />}
                            </button>
                        </div>

                        <button onClick={() => setView('HUB')} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold text-xl hover:bg-indigo-700 transition-colors">
                            Done
                        </button>
                    </div>
                </div>
            )}

            {view === 'PERMISSIONS' && (
                <div className="flex-1 flex flex-col items-center justify-center text-center max-w-2xl mx-auto">
                    <div className="w-24 h-24 bg-red-100 dark:bg-red-900/30 rounded-full flex items-center justify-center mb-8">
                        <ShieldAlert className="w-12 h-12 text-red-600" />
                    </div>
                    <h2 className="text-4xl font-black mb-4 dark:text-white">Secure Access Required</h2>
                    <p className="text-gray-500 mb-10 text-xl">You are entering a strictly proctored environment. AI will monitor your movement, audio, and browser focus to ensure academic integrity.</p>
                    <div className="flex gap-4">
                        <button onClick={() => setView('HUB')} className="px-8 py-4 font-bold text-gray-500">Cancel</button>
                        <button onClick={requestPermissions} className="px-10 py-4 bg-red-600 text-white rounded-2xl font-bold text-xl shadow-xl hover:bg-red-700">Grant & Start Exam</button>
                    </div>
                </div>
            )}

            {view === 'TAKING' && activeTest && (
                <div className="flex-1 flex flex-col lg:flex-row gap-6 animate-fade-in pb-10">
                    <div className="flex-1 space-y-6 overflow-y-auto pr-4">
                        <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 flex justify-between items-center sticky top-0 z-20">
                            <div>
                                <h1 className="text-2xl font-bold dark:text-white">{activeTest.title}</h1>
                                <p className="text-sm text-gray-400">Public Hall Exam</p>
                            </div>
                            <div className="flex items-center gap-6">
                                <div className="text-center">
                                    <span className="block text-[10px] font-bold text-gray-400 uppercase">Warnings</span>
                                    <div className="flex gap-1 mt-1">
                                        {[1,2,3,4,5].map(i => <div key={i} className={`w-4 h-1.5 rounded-full ${i <= warnings ? 'bg-red-600' : 'bg-gray-200 dark:bg-gray-700'}`}></div>)}
                                    </div>
                                </div>
                                <div className="flex items-center gap-2 bg-gray-100 dark:bg-gray-700 px-4 py-2 rounded-2xl">
                                    <Clock className="w-5 h-5 text-gray-500" />
                                    <span className="text-xl font-mono font-bold dark:text-white">
                                        {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
                                    </span>
                                </div>
                            </div>
                        </div>

                        {activeTest.questions.map((q, i) => (
                            <div key={q.id} className="bg-white dark:bg-gray-800 p-8 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700">
                                <p className="text-xl font-bold mb-6 dark:text-white"><span className="text-red-600 mr-2">{i+1}.</span> {q.text}</p>
                                {q.type === QuestionType.MCQ ? (
                                    <div className="space-y-3">
                                        {q.options?.map(opt => (
                                            <button 
                                                key={opt}
                                                onClick={() => setAnswers({...answers, [q.id]: opt})}
                                                className={`w-full text-left p-4 rounded-2xl border-2 transition-all ${answers[q.id] === opt ? 'border-red-600 bg-red-50 dark:bg-red-900/20 dark:text-white' : 'border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-750 dark:text-gray-300'}`}
                                            >
                                                {opt}
                                            </button>
                                        ))}
                                    </div>
                                ) : (
                                    <textarea 
                                        value={answers[q.id] || ''}
                                        onChange={e => setAnswers({...answers, [q.id]: e.target.value})}
                                        className="w-full p-4 bg-gray-50 dark:bg-gray-900 rounded-2xl border-none h-32 dark:text-white"
                                        placeholder="Type your solution..."
                                    />
                                )}
                            </div>
                        ))}
                        <button onClick={() => submitExam()} className="w-full py-5 bg-green-600 text-white text-2xl font-bold rounded-3xl shadow-2xl hover:bg-green-700">Submit Final Responses</button>
                    </div>

                    <div className="w-full lg:w-80 space-y-6">
                        <div className="bg-black rounded-3xl overflow-hidden aspect-video relative border-2 border-red-600 shadow-xl">
                            <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover scale-x-[-1]" />
                            <div className="absolute top-4 left-4 flex items-center gap-2 bg-black/40 px-3 py-1 rounded-full text-[10px] text-white font-bold">
