                                <div className="flex justify-between items-center text-sm">
                                    <span className="text-gray-500">Audio Sensitive</span>
                                    <span className={`font-bold ${audioLevel > 15 ? 'text-red-600' : 'text-green-600'}`}>{Math.round(audioLevel)}%</span>
                                </div>
                                <div className="h-1.5 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                                    <div className={`h-full transition-all ${audioLevel > 15 ? 'bg-red-600' : 'bg-green-500'}`} style={{width: `${Math.min(audioLevel*4, 100)}%`}}></div>
                                </div>
                                <div className="flex items-center gap-3 p-3 bg-red-50 dark:bg-red-900/20 rounded-2xl border border-red-100 dark:border-red-900/50">
                                    <Eye className="w-5 h-5 text-red-600" />
                                    <div>
                                        <p className="text-xs font-bold text-red-800 dark:text-red-200">{proctorStatus}</p>
                                        <p className="text-[10px] text-red-600 dark:text-red-400">Eye-tracking Active</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {view === 'SUBMITTING' && (
                <div className="flex-1 flex flex-col items-center justify-center">
                    <div className="relative w-24 h-24">
                        <div className="absolute inset-0 border-4 border-gray-100 dark:border-gray-700 rounded-full"></div>
                        <div className="absolute inset-0 border-4 border-green-500 rounded-full border-t-transparent animate-spin"></div>
                    </div>
                    <h2 className="text-3xl font-black mt-8 dark:text-white">Closing Examination Session...</h2>
                    <p className="text-gray-500">Encrypting logs and finalizing scores.</p>
                </div>
            )}
        </div>
    );
};

