                    </div>
                </div>
            )}
        </div>
      );
  }

  return (
    <div className="flex bg-gray-50 dark:bg-gray-900 min-h-screen text-gray-900 dark:text-gray-100 font-sans transition-colors duration-200">
      <Sidebar 
        currentView={view} 
        onChangeView={setView} 
        onLogout={handleLogout} 
        user={user}
      />

      <main className="flex-1 ml-64 relative">
         <div className="fixed top-4 right-4 z-[60] flex flex-col gap-2">
             {notifications.map(n => (
                 <div key={n.id} className={`p-4 rounded-lg shadow-xl flex items-center gap-3 animate-slide-in min-w-[300px] ${
                     n.type === 'SUCCESS' ? 'bg-green-600 text-white' : 
                     n.type === 'ERROR' ? 'bg-red-600 text-white' : 
                     'bg-blue-600 text-white'
                 }`}>
                     <Bell className="w-5 h-5" />
                     <div>
                         <p className="font-bold text-sm">{n.title}</p>
                         <p className="text-xs opacity-90">{n.message}</p>
                     </div>
                 </div>
             ))}
         </div>

         {!onboardingComplete && <OnboardingTour onComplete={handleCompleteOnboarding} />}

         <JudgeControls 
            onLogout={handleLogout} 
            onReset={resetDemo} 
            userRole={user.role} 
            onLoadScenario={(s) => { 
                if (s === 'TEACHER_DEMO') { handleLogout(); setTimeout(() => handleLogin(UserRole.TEACHER), 100); }
                else { handleLogout(); setTimeout(() => handleLogin(UserRole.STUDENT), 100); setView(AppView.TEST_MANAGER); }
            }}
         />

         {view === AppView.DASHBOARD && <Dashboard user={user} changeView={setView} />}
         {view === AppView.VIDEO_GEN && <VideoGenerator onSave={(script) => { setLibrary(prev => [...prev, { id: Date.now().toString(), type: ContentType.VIDEO, title: script.topic, data: script, dateCreated: new Date().toISOString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 }]); addNotification('Video Saved', 'Saved to My Library', 'SUCCESS'); }} />}
         {view === AppView.EBOOK_GEN && <EbookGenerator onSave={(title, content) => { setLibrary(prev => [...prev, { id: Date.now().toString(), type: ContentType.EBOOK, title, data: content, dateCreated: new Date().toISOString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 }]); addNotification('Ebook Saved', 'Saved to My Library', 'SUCCESS'); }} />}
         {view === AppView.NOTES_GEN && <NotesGenerator onSave={(item) => { setLibrary(prev => [...prev, { ...item, id: Date.now().toString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 } as LibraryItem]); }} />}
         {view === AppView.PPT_GEN && <PPTGenerator onSave={(ppt) => { setLibrary(prev => [...prev, { id: Date.now().toString(), type: ContentType.PPT, title: ppt.topic, data: ppt, dateCreated: new Date().toISOString(), userId: user.id, status: 'ACTIVE', isShared: false, views: 0, imports: 0 }]); addNotification('Presentation Saved', 'Saved to My Library', 'SUCCESS'); }} />}

         {view === AppView.TEST_MANAGER && <TestManager 
                user={user} 
                globalTests={tests} 
                testHistory={testResults.filter(r => r.studentId === user.id)} 
                classrooms={classrooms}
                onAddTest={(t) => setTests([...tests, t])} 
                onSaveResult={(r) => { setTestResults([...testResults, r]); addNotification('Test Submitted', 'Results & Violation Report Saved', 'SUCCESS'); }} 
                onDeployTest={(tid, classIds) => {
                    setTests(tests.map(t => t.id === tid ? { ...t, status: 'LIVE', assignedClassIds: classIds } : t));
                    addNotification('Test Deployed', `Students in ${classIds.length} classes notified`, 'EMAIL');
                }}
                onPublishResults={(tid) => {
                    setTests(tests.map(t => t.id === tid ? { ...t, resultsPublished: true } : t));
                    addNotification('Results Published', 'Students can now view their scores', 'SUCCESS');
                }}
                onExit={() => setView(AppView.DASHBOARD)}
         />}
         {view === AppView.EXAMINATION && <ExaminationCenter 
            user={user}
            globalTests={tests}
            onAddTest={(t) => setTests([...tests, t])}
            onSaveResult={(r) => { setTestResults([...testResults, r]); addNotification('Public Exam Submitted', 'Result Saved', 'SUCCESS'); }}
         />}
         {view === AppView.DOUBT_TUTOR && <DoubtTutor />}
         {view === AppView.LEARNING_PATH && <LearningPathBuilder />}
         {view === AppView.CLASSROOMS && <ClassroomManager 
            user={user} 
            classrooms={classrooms} 
            assignments={assignments} 
            tests={tests} 
            testResults={testResults} 
            onCreate={(c) => setClassrooms([...classrooms, c])} 
            onJoin={(code) => { 
                const c = classrooms.find(cl => cl.code === code);
                if (!c) return { success: false, message: 'Invalid Class Code' };
                if (c.studentIds.includes(user.id)) return { success: false, message: 'Already Joined' };
                const updated = { ...c, studentIds: [...c.studentIds, user.id] };
                setClassrooms(classrooms.map(cl => cl.id === c.id ? updated : cl));
                return { success: true, message: 'Joined Successfully' };
            }} 
            onUpdate={(updated) => setClassrooms(classrooms.map(c => c.id === updated.id ? updated : c))} 
         />}
         {view === AppView.LIBRARY && <Library 
            items={library} 
            user={user} 
            friends={friends} 
            onUpdateItem={(id, updates) => setLibrary(library.map(i => i.id === id ? { ...i, ...updates } : i))} 
            onDeletePermanent={(id) => setLibrary(library.filter(i => i.id !== id))} 
            onImport={(item) => {
                const newItem = { ...item, id: Date.now().toString(), userId: user.id, isShared: false, imports: 0, originalOwnerId: item.userId, originalOwnerName: 'Friend' };
                setLibrary([...library, newItem]);
                addNotification('Content Imported', 'Saved to your library', 'SUCCESS');
            }} 
         />}
         {view === AppView.ASSIGNMENTS && <AssignmentManager user={user} classrooms={classrooms} assignments={assignments} setAssignments={setAssignments} />}
         {view === AppView.SOCIAL && <SocialManager 
            user={user} 
            friends={friends} 
            sendRequest={(uid) => {
                if (uid === user.id) return { success: false, message: "Cannot invite yourself" };
                if (friends.includes(uid)) return { success: false, message: "Already connected" };
                setFriends([...friends, uid]);
                return { success: true, message: "Friend added to network" };
            }} 
         />}
         {view === AppView.PROFILE && <ProfileManager user={user} onUpdate={(u) => { setUser(u); addNotification('Profile Updated', 'Changes saved', 'SUCCESS'); }} />}
         {view === AppView.ANALYTICS && <AnalyticsDashboard />}
         {view === AppView.VIRTUAL_LAB && renderVirtualLab()}
         {view === AppView.CAREER_PATH && renderCareerPath()}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { generateTest, analyzeProctoringFrame } from '../services/gemini';
import { TestData, User, TestResult, QuestionType, UserRole } from '../types';
import { 
    Play, Plus, Loader2, ShieldCheck, Hash, 
    Copy, CheckCircle, Sparkles, Send, Mic, 
    Camera, Eye, Activity, Clock, ShieldAlert, X, GraduationCap, Layout
} from 'lucide-react';
import confetti from 'canvas-confetti';

interface ExaminationCenterProps {
    user: User;
    globalTests: TestData[];
    onAddTest: (test: TestData) => void;
    onSaveResult: (result: TestResult) => void;
}

const ExaminationCenter: React.FC<ExaminationCenterProps> = ({ user, globalTests, onAddTest, onSaveResult }) => {
    // Determine initial filtered hub based on user guest role if available
    const [view, setView] = useState<'HUB' | 'GENERATING' | 'CODE_REVEAL' | 'PERMISSIONS' | 'INSTRUCTIONS' | 'TAKING' | 'SUBMITTING' | 'MANAGEMENT'>('HUB');
    const [joinCode, setJoinCode] = useState('');
    const [prompt, setPrompt] = useState('');
    const [generatedCode, setGeneratedCode] = useState('');
    const [activeTest, setActiveTest] = useState<TestData | null>(null);
    const [copied, setCopied] = useState(false);

    // TAKE EXAM STATE
    const [answers, setAnswers] = useState<Record<number, string>>({});
    const [timeLeft, setTimeLeft] = useState(0);
    const [warnings, setWarnings] = useState(0);
    const [audioLevel, setAudioLevel] = useState(0);
    const [proctorStatus, setProctorStatus] = useState('Monitoring');

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const lastViolationRef = useRef<number>(0);

    const handleGenerate = async () => {
        if (!prompt) return;
        setView('GENERATING');
        try {
            const data = await generateTest(prompt, 'Medium', 5);
            const code = Math.floor(100000 + Math.random() * 899999).toString();
            const newTest: TestData = {
                ...data,
                id: Date.now().toString(),
                creatorId: user.id,
                accessCode: code,
                status: 'LIVE',
                settings: { ...data.settings, proctoring: true }
            };
            onAddTest(newTest);
            setGeneratedCode(code);
            setView('CODE_REVEAL');
        } catch (e) {
            console.error(e);
            alert("Failed to generate test. Try again.");
            setView('HUB');
        }
    };

    const handleJoin = () => {
        const test = globalTests.find(t => t.accessCode === joinCode);
        if (test) {
            setActiveTest(test);
            setView('INSTRUCTIONS');
        } else {
            alert("Invalid Examination Code.");
        }
    };

    const requestPermissions = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ 
                video: { facingMode: 'user' }, 
                audio: true 
            });
            streamRef.current = stream;
            setView('TAKING');
        } catch (e) {
            alert("Permission Denied: Camera and Microphone are required.");
        }
    };

    // PROCTORING SYSTEM
    useEffect(() => {
        let visionInterval: any;
        let audioInterval: any;

        if (view === 'TAKING' && streamRef.current) {
            if (videoRef.current) videoRef.current.srcObject = streamRef.current;

            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            audioContextRef.current = new AudioContext();
            analyserRef.current = audioContextRef.current.createAnalyser();
            const source = audioContextRef.current.createMediaStreamSource(streamRef.current);
            source.connect(analyserRef.current);
            if (audioContextRef.current.state === 'suspended') audioContextRef.current.resume();

            visionInterval = setInterval(async () => {
                if (!videoRef.current) return;
                const canvas = document.createElement('canvas');
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;
                ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                setProctorStatus('Analyzing...');
                const res = await analyzeProctoringFrame(base64);
                if (res.suspicious) triggerViolation(`AI Alert: ${res.reason}`);
                setProctorStatus('Monitoring');
            }, 5000);

            audioInterval = setInterval(() => {
                if (!analyserRef.current) return;
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteFrequencyData(data);
                const avg = data.reduce((a, b) => a + b) / data.length;
                setAudioLevel(avg);
                if (avg > 15) triggerViolation("Noise Detected");
            }, 200);
        }

        return () => {
            clearInterval(visionInterval);
            clearInterval(audioInterval);
        };
    }, [view]);

    const triggerViolation = (reason: string) => {
        const now = Date.now();
        if (now - lastViolationRef.current < 4000) return;
        lastViolationRef.current = now;
        setWarnings(prev => {
            const next = prev + 1;
            if (next >= 5) submitExam(true);
            return next;
        });
        showViolationToast(reason);
    };

    const showViolationToast = (msg: string) => {
        const toast = document.createElement('div');
        toast.className = "fixed top-8 left-1/2 -translate-x-1/2 bg-red-600 text-white px-6 py-3 rounded-2xl shadow-2xl z-[999] animate-bounce font-bold border-2 border-white";
        toast.innerText = `⚠️ PROCTOR ALERT: ${msg}`;
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 3000);
    };

    const submitExam = (auto = false) => {
        setView('SUBMITTING');
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        setTimeout(() => {
            const result: TestResult = {
                testId: activeTest?.id || 'public',
                studentId: user.id,
                score: Object.keys(answers).length, // Simplified mock score
                maxScore: activeTest?.questions.length || 0,
                answers,
                dateTaken: new Date().toISOString(),
                status: 'COMPLETED',
                autoSubmitted: auto
            };
            onSaveResult(result);
            confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 } });
            setView('HUB');
            setJoinCode('');
        }, 2000);
    };

    useEffect(() => {
        let t: any;
        if (view === 'TAKING' && activeTest) {
            if (timeLeft === 0) setTimeLeft(activeTest.settings.timeLimitMinutes * 60);
            t = setInterval(() => setTimeLeft(prev => prev > 0 ? prev - 1 : (submitExam(true), 0)), 1000);
        }
        return () => clearInterval(t);
    }, [view, timeLeft, activeTest]);

    // Role-based visibility
    const isInvigilator = user.role === UserRole.TEACHER;

    return (
        <div className="p-6 max-w-6xl mx-auto min-h-[calc(100vh-4rem)] flex flex-col">
            {view === 'HUB' && (
                <div className="flex-1 flex flex-col justify-center animate-fade-in">
                    <div className="text-center mb-12">
                        <h1 className="text-5xl font-black mb-4 bg-gradient-to-r from-red-600 to-indigo-600 bg-clip-text text-transparent">Examination Hall</h1>
                        <p className="text-gray-500 text-xl font-medium">Secure, AI-monitored public testing portal.</p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-12 max-w-5xl mx-auto w-full">
                        {/* STUDENT CARD */}
                        <div className={`bg-white dark:bg-gray-800 rounded-[2.5rem] p-10 shadow-2xl border border-gray-100 dark:border-gray-700 hover:scale-[1.02] transition-transform flex flex-col group ${!isInvigilator ? 'ring-4 ring-red-500/20' : 'opacity-50 grayscale pointer-events-none'}`}>
                            <div className="w-16 h-16 bg-red-100 dark:bg-red-900/30 rounded-3xl flex items-center justify-center mb-8 group-hover:rotate-6 transition-transform">
                                <GraduationCap className="w-8 h-8 text-red-600" />
                            </div>
                            <h2 className="text-3xl font-bold dark:text-white mb-4">Student</h2>
                            <p className="text-gray-500 mb-8 flex-1">Enter a unique test code to join a session. Strict AI proctoring will be active.</p>
                            <div className="space-y-4">
                                <div className="relative">
                                    <Hash className="absolute left-4 top-4 text-gray-400" />
                                    <input 
                                        value={joinCode}
                                        onChange={e => setJoinCode(e.target.value.toUpperCase())}
                                        placeholder="EXAM CODE"
                                        className="w-full pl-12 p-4 bg-gray-50 dark:bg-gray-900 rounded-2xl border-none font-mono text-xl focus:ring-2 focus:ring-red-500 dark:text-white"
                                    />
                                </div>
                                <button 
                                    onClick={handleJoin}
                                    disabled={!joinCode}
                                    className="w-full py-4 bg-red-600 hover:bg-red-700 text-white rounded-2xl font-bold text-lg shadow-xl disabled:opacity-50"
                                >
                                    Access Hall & Take Test
                                </button>
                            </div>
                        </div>

                        {/* INVIGILATOR CARD */}
                        <div className={`bg-white dark:bg-gray-800 rounded-[2.5rem] p-10 shadow-2xl border border-gray-100 dark:border-gray-700 hover:scale-[1.02] transition-transform flex flex-col group ${isInvigilator ? 'ring-4 ring-indigo-500/20' : 'opacity-50 grayscale pointer-events-none'}`}>
                            <div className="w-16 h-16 bg-indigo-100 dark:bg-indigo-900/30 rounded-3xl flex items-center justify-center mb-8 group-hover:-rotate-6 transition-transform">
                                <ShieldCheck className="w-8 h-8 text-indigo-600" />
                            </div>
                            <h2 className="text-3xl font-bold dark:text-white mb-4">Invigilator</h2>
                            <p className="text-gray-500 mb-8 flex-1">Create exams on any topic using AI, generate codes, and access the management dashboard.</p>
                            <div className="space-y-4">
                                <div className="relative">
                                    <Sparkles className="absolute left-4 top-4 text-gray-400" />
                                    <input 
                                        value={prompt}
                                        onChange={e => setPrompt(e.target.value)}
                                        placeholder="TOPIC (e.g. Quantum Physics)"
                                        className="w-full pl-12 p-4 bg-gray-50 dark:bg-gray-900 rounded-2xl border-none text-lg focus:ring-2 focus:ring-indigo-500 dark:text-white"
                                    />
                                </div>
                                <div className="flex gap-2">
                                    <button 
                                        onClick={handleGenerate}
                                        disabled={!prompt}
                                        className="flex-1 py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold text-lg shadow-xl disabled:opacity-50"
                                    >
                                        Generate Hall
                                    </button>
                                    <button onClick={() => setView('MANAGEMENT')} className="p-4 bg-gray-100 dark:bg-gray-700 rounded-2xl hover:bg-gray-200" title="Dashboard">
                                        <Layout className="w-6 h-6 text-indigo-600"/>
                                    </button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {view === 'GENERATING' && (
                <div className="flex-1 flex flex-col items-center justify-center text-center">
                    <Loader2 className="w-20 h-20 text-indigo-600 animate-spin mb-6" />
                    <h2 className="text-3xl font-black dark:text-white">AI Agent is generating the exam hall...</h2>
                    <p className="text-gray-500 mt-2 font-medium">Configuring proctoring parameters and creating unique questions.</p>
                </div>
            )}

            {view === 'CODE_REVEAL' && (
                <div className="flex-1 flex flex-col items-center justify-center text-center animate-scale-in">
                    <div className="bg-white dark:bg-gray-800 p-12 rounded-[3rem] shadow-2xl border border-indigo-100 dark:border-gray-700 max-w-xl w-full">
                        <CheckCircle className="w-20 h-20 text-green-500 mx-auto mb-6" />
                        <h2 className="text-4xl font-black mb-2 dark:text-white">Hall is Open!</h2>
                        <p className="text-gray-500 mb-8 text-lg">Share this unique access code with your students.</p>

                        <div className="bg-gray-100 dark:bg-gray-900 p-6 rounded-3xl mb-8 flex items-center justify-between">
                            <span className="text-5xl font-mono font-black tracking-widest text-indigo-600">{generatedCode}</span>
                            <button 
                                onClick={() => { navigator.clipboard.writeText(generatedCode); setCopied(true); setTimeout(() => setCopied(false), 2000); }}
                                className="p-4 bg-white dark:bg-gray-800 rounded-2xl shadow hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors"
                            >
                                {copied ? <CheckCircle className="w-6 h-6 text-green-500" /> : <Copy className="w-6 h-6 text-gray-500" />}
                            </button>
                        </div>

                        <button onClick={() => setView('HUB')} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-bold text-xl hover:bg-indigo-700 transition-colors">
                            Return to Hub
                        </button>
                    </div>
                </div>
            )}

            {view === 'MANAGEMENT' && (
                <div className="flex-1 animate-fade-in">
                    <div className="flex justify-between items-center mb-8">
                        <button onClick={() => setView('HUB')} className="text-gray-500 font-bold hover:text-black">← Back to Hub</button>
                        <h2 className="text-3xl font-black dark:text-white">Invigilator Dashboard</h2>
                    </div>
                    <div className="bg-white dark:bg-gray-800 rounded-[2rem] shadow-xl overflow-hidden border border-gray-100 dark:border-gray-700">
                        <table className="w-full text-left">
                            <thead className="bg-gray-50 dark:bg-gray-900">
                                <tr>
                                    <th className="p-6 font-bold text-gray-400 uppercase text-xs">Session Code</th>
                                    <th className="p-6 font-bold text-gray-400 uppercase text-xs">Topic</th>
                                    <th className="p-6 font-bold text-gray-400 uppercase text-xs">Status</th>
                                    <th className="p-6 font-bold text-gray-400 uppercase text-xs">Questions</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y dark:divide-gray-700">
                                {globalTests.filter(t => t.creatorId === user.id).map(test => (
                                    <tr key={test.id} className="hover:bg-gray-50 dark:hover:bg-gray-750">
                                        <td className="p-6 font-mono font-bold text-indigo-600">{test.accessCode}</td>
                                        <td className="p-6 font-bold dark:text-white">{test.title}</td>
                                        <td className="p-6"><span className="px-3 py-1 bg-green-100 text-green-700 text-xs font-black rounded-full">ACTIVE</span></td>
                                        <td className="p-6 text-gray-500">{test.questions.length} Qs</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {view === 'INSTRUCTIONS' && activeTest && (
                <div className="flex-1 flex flex-col items-center justify-center max-w-2xl mx-auto animate-fade-in">
                    <div className="bg-white dark:bg-gray-800 p-10 rounded-[3rem] shadow-2xl border border-gray-100 dark:border-gray-700 w-full">
                        <div className="w-16 h-16 bg-red-100 dark:bg-red-900/30 rounded-2xl flex items-center justify-center mb-6">
                            <ShieldAlert className="w-8 h-8 text-red-600" />
                        </div>
                        <h2 className="text-3xl font-black mb-4 dark:text-white">Exam Rules: {activeTest.title}</h2>
                        <div className="space-y-4 mb-10 text-gray-600 dark:text-gray-300">
                            <p className="flex items-center gap-3"><CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0" /> AI Vision is active. Maintain eye contact with the screen.</p>
                            <p className="flex items-center gap-3"><CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0" /> Audio Monitoring is on. Avoid whispering or speaking aloud.</p>
                            <p className="flex items-center gap-3"><CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0" /> Tab Locking: Switching tabs or windows will trigger a severe violation.</p>
                            <p className="flex items-center gap-3"><CheckCircle className="w-5 h-5 text-green-500 flex-shrink-0" /> Time Limit: {activeTest.settings.timeLimitMinutes} minutes to complete.</p>
                        </div>
                        <div className="flex gap-4">
                            <button onClick={() => setView('HUB')} className="px-8 py-4 font-bold text-gray-500 hover:text-gray-700">Cancel</button>
                            <button onClick={() => setView('PERMISSIONS')} className="flex-1 py-4 bg-red-600 text-white rounded-2xl font-bold text-xl shadow-xl hover:bg-red-700 transition-all">Proceed to Secure Lobby</button>
                        </div>
                    </div>
                </div>
            )}

            {view === 'PERMISSIONS' && (
                <div className="flex-1 flex flex-col items-center justify-center text-center max-w-2xl mx-auto">
                    <div className="w-24 h-24 bg-red-100 dark:bg-red-900/30 rounded-full flex items-center justify-center mb-8">
                        <Camera className="w-12 h-12 text-red-600" />
                    </div>
                    <h2 className="text-4xl font-black mb-4 dark:text-white">Grant Secure Access</h2>
                    <p className="text-gray-500 mb-10 text-xl font-medium">To maintain hall integrity, you must grant access to your camera and microphone for real-time proctoring.</p>
                    <div className="flex gap-4">
                        <button onClick={() => setView('HUB')} className="px-8 py-4 font-bold text-gray-500">Cancel</button>
                        <button onClick={requestPermissions} className="px-10 py-4 bg-red-600 text-white rounded-2xl font-bold text-xl shadow-xl hover:bg-red-700">Grant & Start Session</button>
                    </div>
                </div>
            )}

            {view === 'TAKING' && activeTest && (
                <div className="flex-1 flex flex-col lg:flex-row gap-6 animate-fade-in pb-10">
                    <div className="flex-1 space-y-6 overflow-y-auto pr-4">
                        <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 flex justify-between items-center sticky top-0 z-20">
                            <div>
                                <h1 className="text-2xl font-bold dark:text-white">{activeTest.title}</h1>
                                <p className="text-sm text-gray-400 font-bold uppercase tracking-widest">Public Lobby Session</p>
                            </div>
                            <div className="flex items-center gap-6">
                                <div className="text-center">
                                    <span className="block text-[10px] font-black text-gray-400 uppercase">Violations</span>
                                    <div className="flex gap-1 mt-1">
                                        {[1,2,3,4,5].map(i => <div key={i} className={`w-4 h-1.5 rounded-full ${i <= warnings ? 'bg-red-600 animate-pulse' : 'bg-gray-200 dark:bg-gray-700'}`}></div>)}
                                    </div>
                                </div>
                                <div className="flex items-center gap-2 bg-gray-100 dark:bg-gray-700 px-4 py-2 rounded-2xl">
                                    <Clock className="w-5 h-5 text-gray-500" />
                                    <span className="text-xl font-mono font-bold dark:text-white">
                                        {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
                                    </span>
                                </div>
                            </div>
                        </div>

                        {activeTest.questions.map((q, i) => (
                            <div key={q.id} className="bg-white dark:bg-gray-800 p-8 rounded-3xl shadow-sm border border-gray-100 dark:border-gray-700 transition-all hover:shadow-md">
                                <p className="text-xl font-bold mb-6 dark:text-white"><span className="text-red-600 mr-2">{i+1}.</span> {q.text}</p>
                                {q.type === QuestionType.MCQ ? (
                                    <div className="space-y-3">
                                        {q.options?.map(opt => (
                                            <button 
                                                key={opt}
                                                onClick={() => setAnswers({...answers, [q.id]: opt})}
                                                className={`w-full text-left p-4 rounded-2xl border-2 transition-all font-medium ${answers[q.id] === opt ? 'border-red-600 bg-red-50 dark:bg-red-900/20 dark:text-white shadow-inner' : 'border-gray-100 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-750 dark:text-gray-300'}`}
                                            >
                                                {opt}
                                            </button>
                                        ))}
                                    </div>
                                ) : (
                                    <textarea 
                                        value={answers[q.id] || ''}
                                        onChange={e => setAnswers({...answers, [q.id]: e.target.value})}
                                        className="w-full p-4 bg-gray-50 dark:bg-gray-900 rounded-2xl border-none h-32 dark:text-white focus:ring-2 focus:ring-red-500"
                                        placeholder="Provide your solution here..."
                                    />
                                )}
                            </div>
                        ))}
                        <button onClick={() => submitExam()} className="w-full py-5 bg-green-600 text-white text-2xl font-black rounded-3xl shadow-2xl hover:bg-green-700 transform transition active:scale-[0.98]">SUBMIT FINAL RESPONSES</button>
                    </div>

                    <div className="w-full lg:w-80 space-y-6">
                        <div className="bg-black rounded-3xl overflow-hidden aspect-video relative border-2 border-red-600 shadow-xl">
                            <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover scale-x-[-1]" />
                            <div className="absolute top-4 left-4 flex items-center gap-2 bg-black/40 px-3 py-1 rounded-full text-[10px] text-white font-black">
                                <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse"></div> SECURE REC
                            </div>
                            {audioLevel > 15 && (
                                <div className="absolute inset-0 flex items-center justify-center bg-red-600/20 backdrop-blur-[2px]">
                                    <div className="bg-red-600 text-white px-3 py-1 rounded-lg text-xs font-black animate-pulse">VOICE DETECTED</div>
                                </div>
                            )}
                        </div>

                        <div className="bg-white dark:bg-gray-800 p-6 rounded-3xl shadow border border-gray-100 dark:border-gray-700">
                            <h3 className="text-sm font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                                <Activity className="w-4 h-4 text-green-500" /> Secure Sensors
                            </h3>
                            <div className="space-y-4">
                                <div className="flex justify-between items-center text-sm font-bold">
                                    <span className="text-gray-500">Audio Sens.</span>
                                    <span className={`font-black ${audioLevel > 15 ? 'text-red-600' : 'text-green-600'}`}>{Math.round(audioLevel)}%</span>
                                </div>
                                <div className="h-1.5 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                                    <div className={`h-full transition-all duration-150 ${audioLevel > 15 ? 'bg-red-600' : 'bg-green-500'}`} style={{width: `${Math.min(audioLevel*4, 100)}%`}}></div>
                                </div>
                                <div className="flex items-center gap-3 p-3 bg-red-50 dark:bg-red-900/20 rounded-2xl border border-red-100 dark:border-red-900/50">
                                    <Eye className="w-5 h-5 text-red-600" />
                                    <div>
                                        <p className="text-xs font-black text-red-800 dark:text-red-200">{proctorStatus}</p>
                                        <p className="text-[10px] text-red-600 dark:text-red-400 font-bold uppercase">AI Eye-Tracking</p>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {view === 'SUBMITTING' && (
                <div className="flex-1 flex flex-col items-center justify-center">
                    <div className="relative w-24 h-24">
                        <div className="absolute inset-0 border-4 border-gray-100 dark:border-gray-700 rounded-full"></div>
                        <div className="absolute inset-0 border-4 border-green-500 rounded-full border-t-transparent animate-spin"></div>
                    </div>
                    <h2 className="text-3xl font-black mt-8 dark:text-white">Closing Session...</h2>
                    <p className="text-gray-500 font-medium">Encrypting logs and finalizing grading reports.</p>
                </div>
            )}
        </div>
    );
};

export default ExaminationCenter;

import React, { useState, useRef, useEffect } from 'react';
import { generateTest, analyzeProctoringFrame } from '../services/gemini';
import { TestData, User, TestResult, QuestionType, UserRole, Question } from '../types';
import { 
    Play, Plus, Loader2, ShieldCheck, Hash, 
    Copy, CheckCircle, Sparkles, Send, Mic, 
    Camera, Eye, Activity, Clock, ShieldAlert, X, GraduationCap, 
    Layout, Settings, Edit3, Trash2, List, CheckSquare, AlertCircle, 
    ChevronRight, ChevronLeft, Save, Globe, Monitor, BarChart3, Info
} from 'lucide-react';
import confetti from 'canvas-confetti';

interface ExaminationCenterProps {
    user: User;
    globalTests: TestData[];
    onAddTest: (test: TestData) => void;
    onSaveResult: (result: TestResult) => void;
}

const ExaminationCenter: React.FC<ExaminationCenterProps> = ({ user, globalTests, onAddTest, onSaveResult }) => {
    // VIEW MANAGEMENT
    const [view, setView] = useState<'HUB' | 'INV_METHOD' | 'INV_BUILDER' | 'INV_DASHBOARD' | 'INV_MONITOR' | 'STU_ENTRY' | 'STU_INSTRUCTIONS' | 'STU_TAKING' | 'STU_SUBMITTING'>('HUB');

    // INVIGILATOR STATE
    const [creationMode, setCreationMode] = useState<'AI' | 'MANUAL'>('AI');
    const [isGenerating, setIsGenerating] = useState(false);
    const [invSettings, setInvSettings] = useState({
        title: '',
        duration: 30,
        topic: '',
        qCount: 5,
        difficulty: 'Medium' as 'Easy' | 'Medium' | 'Hard',
        proctoring: true,
        tabLock: true
    });
    const [workingQuestions, setWorkingQuestions] = useState<Question[]>([]);
    const [activeEditIdx, setActiveEditIdx] = useState<number | null>(null);
    const [generatedCode, setGeneratedCode] = useState('');

    // STUDENT STATE
    const [joinCode, setJoinCode] = useState('');
    const [activeTest, setActiveTest] = useState<TestData | null>(null);
    const [answers, setAnswers] = useState<Record<number, string>>({});
    const [timeLeft, setTimeLeft] = useState(0);
    const [warnings, setWarnings] = useState(0);
    const [audioLevel, setAudioLevel] = useState(0);
    const [proctorStatus, setProctorStatus] = useState('Monitoring');
    const [currentQIdx, setCurrentQIdx] = useState(0);

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const lastViolationRef = useRef<number>(0);

    // --- INVIGILATOR LOGIC ---

    const handleGenerateAI = async () => {
        if (!invSettings.topic) return;
        setIsGenerating(true);
        try {
            const data = await generateTest(invSettings.topic, invSettings.difficulty, invSettings.qCount);
            setWorkingQuestions(data.questions);
            setInvSettings(prev => ({ ...prev, title: data.title }));
            setView('INV_BUILDER');
        } catch (e) {
            alert("AI generation failed. Please try a different topic.");
        } finally {
            setIsGenerating(false);
        }
    };

    const addManualQuestion = () => {
        const newQ: Question = {
            id: Date.now(),
            text: '',
            type: QuestionType.MCQ,
            options: ['', '', '', ''],
            correctAnswer: '',
            explanation: '',
            difficulty: 'Medium',
            marks: 1
        };
        setWorkingQuestions([...workingQuestions, newQ]);
        setActiveEditIdx(workingQuestions.length);
    };

    const removeQuestion = (idx: number) => {
        setWorkingQuestions(workingQuestions.filter((_, i) => i !== idx));
        if (activeEditIdx === idx) setActiveEditIdx(null);
    };

    const updateQuestion = (idx: number, updates: Partial<Question>) => {
        const updated = [...workingQuestions];
        updated[idx] = { ...updated[idx], ...updates };
        setWorkingQuestions(updated);
    };

    const finalizeTest = () => {
        if (!invSettings.title) { alert("Please provide a test name."); return; }
        if (workingQuestions.length === 0) { alert("Add at least one question."); return; }

        const code = Math.floor(100000 + Math.random() * 899999).toString();
        const newTest: TestData = {
            id: Date.now().toString(),
            title: invSettings.title,
            subject: invSettings.topic || 'General',
            creatorId: user.id,
            questions: workingQuestions,
            settings: {
                timeLimitMinutes: invSettings.duration,
                proctoring: invSettings.proctoring,
                adaptive: false,
                shuffleQuestions: true
            },
            status: 'LIVE',
            accessCode: code
        };
        onAddTest(newTest);
        setGeneratedCode(code);
        setView('INV_DASHBOARD');
    };

    // --- STUDENT LOGIC ---

    const handleJoin = () => {
        const test = globalTests.find(t => t.accessCode === joinCode);
        if (test) {
            setActiveTest(test);
            setView('STU_INSTRUCTIONS');
        } else {
            alert("Invalid Test Code. Check with your Invigilator.");
        }
    };

    const startExam = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
            streamRef.current = stream;
            setView('STU_TAKING');
            setTimeLeft((activeTest?.settings.timeLimitMinutes || 30) * 60);
        } catch (e) {
            alert("Permissions required to start the proctored exam.");
        }
    };

    const submitExam = (auto = false) => {
        setView('STU_SUBMITTING');
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        setTimeout(() => {
            const result: TestResult = {
                testId: activeTest?.id || 'public',
                studentId: user.id,
                score: Object.keys(answers).length, 
                maxScore: activeTest?.questions.length || 0,
                answers,
                dateTaken: new Date().toISOString(),
                status: 'COMPLETED',
                autoSubmitted: auto
            };
            onSaveResult(result);
            confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 } });
            setView('HUB');
            setJoinCode('');
        }, 2000);
    };

    // PROCTORING SYSTEM
    useEffect(() => {
        let visionInterval: any;
        let audioInterval: any;

        if (view === 'STU_TAKING' && streamRef.current) {
            if (videoRef.current) videoRef.current.srcObject = streamRef.current;

            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            audioContextRef.current = new AudioContext();
            analyserRef.current = audioContextRef.current.createAnalyser();
            const source = audioContextRef.current.createMediaStreamSource(streamRef.current);
            source.connect(analyserRef.current);

            visionInterval = setInterval(async () => {
                if (!videoRef.current) return;
                const canvas = document.createElement('canvas');
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;
                ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                setProctorStatus('Scanning...');
                const res = await analyzeProctoringFrame(base64);
                if (res.suspicious) triggerViolation(`AI Warning: ${res.reason}`);
                setProctorStatus('Monitoring');
            }, 7000);

            audioInterval = setInterval(() => {
                if (!analyserRef.current) return;
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteFrequencyData(data);
                const avg = data.reduce((a, b) => a + b) / data.length;
                setAudioLevel(avg);
                if (avg > 18) triggerViolation("Noise Detected");
            }, 250);
        }

        return () => {
            clearInterval(visionInterval);
            clearInterval(audioInterval);
        };
    }, [view]);

    const triggerViolation = (reason: string) => {
        if (Date.now() - lastViolationRef.current < 4000) return;
        lastViolationRef.current = Date.now();
        setWarnings(prev => {
            const next = prev + 1;
            if (next >= 5) submitExam(true);
            return next;
        });
        showViolationToast(reason);
    };

    const showViolationToast = (msg: string) => {
        const toast = document.createElement('div');
        toast.className = "fixed top-12 left-1/2 -translate-x-1/2 bg-red-600 text-white px-8 py-4 rounded-full shadow-2xl z-[999] animate-bounce font-bold border-2 border-white";
        toast.innerText = `PROCTOR ALERT: ${msg}`;
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 3500);
    };

    useEffect(() => {
        let t: any;
        if (view === 'STU_TAKING' && timeLeft > 0) {
            t = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
        } else if (view === 'STU_TAKING' && timeLeft === 0) {
            submitExam(true);
        }
        return () => clearInterval(t);
    }, [view, timeLeft]);

    return (
        <div className="p-6 max-w-7xl mx-auto min-h-[calc(100vh-4rem)] flex flex-col font-sans">

            {/* HUB VIEW */}
            {view === 'HUB' && (
                <div className="flex-1 flex flex-col justify-center animate-fade-in">
                    <div className="text-center mb-16">
                        <h1 className="text-6xl font-black mb-4 bg-gradient-to-r from-indigo-600 via-purple-600 to-red-600 bg-clip-text text-transparent">Examination Center</h1>
                        <p className="text-gray-500 text-xl font-medium">The proctored hub for guest access and public academic integrity.</p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-12 max-w-5xl mx-auto w-full">
                        {/* INVIGILATOR HUB */}
                        <div className="bg-white dark:bg-gray-800 rounded-[3rem] p-12 shadow-2xl border-b-8 border-indigo-600 group transition-all hover:-translate-y-2">
                            <div className="w-20 h-20 bg-indigo-100 dark:bg-indigo-900/40 rounded-[2rem] flex items-center justify-center mb-8 group-hover:rotate-6 transition-transform">
                                <ShieldCheck className="w-10 h-10 text-indigo-600" />
                            </div>
                            <h2 className="text-4xl font-black dark:text-white mb-4">Invigilator</h2>
                            <p className="text-gray-500 mb-10 text-lg">Generate AI tests, build manual banks, and monitor live proctored sessions.</p>
                            <button 
                                onClick={() => setView('INV_METHOD')}
                                className="w-full py-5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold text-xl shadow-xl transition-all active:scale-95"
                            >
                                Enter Command Center
                            </button>
                        </div>

                        {/* STUDENT HUB */}
                        <div className="bg-white dark:bg-gray-800 rounded-[3rem] p-12 shadow-2xl border-b-8 border-red-600 group transition-all hover:-translate-y-2">
                            <div className="w-20 h-20 bg-red-100 dark:bg-red-900/40 rounded-[2rem] flex items-center justify-center mb-8 group-hover:-rotate-6 transition-transform">
                                <GraduationCap className="w-10 h-10 text-red-600" />
                            </div>
                            <h2 className="text-4xl font-black dark:text-white mb-4">Student</h2>
                            <p className="text-gray-500 mb-10 text-lg">Enter a unique hall code to access your exam under strict AI invigilation.</p>
                            <button 
                                onClick={() => setView('STU_ENTRY')}
                                className="w-full py-5 bg-red-600 hover:bg-red-700 text-white rounded-2xl font-bold text-xl shadow-xl transition-all active:scale-95"
                            >
                                Join Examination Hall
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* INVIGILATOR METHOD SELECTION */}
            {view === 'INV_METHOD' && (
                <div className="flex-1 flex flex-col animate-fade-in">
                    <button onClick={() => setView('HUB')} className="text-gray-500 font-bold mb-8 hover:text-black">← Return to Hub</button>
                    <div className="max-w-4xl mx-auto w-full">
                        <h2 className="text-4xl font-black mb-4 dark:text-white">Creation Method</h2>
                        <p className="text-gray-500 mb-10">Choose how you want to architect this examination session.</p>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
                            <button 
                                onClick={() => { setCreationMode('AI'); setWorkingQuestions([]); setView('INV_BUILDER'); }}
                                className="bg-white dark:bg-gray-800 p-10 rounded-[2.5rem] shadow-xl border-2 border-transparent hover:border-indigo-500 text-left transition-all group"
                            >
                                <Sparkles className="w-12 h-12 text-indigo-600 mb-6 group-hover:scale-110 transition-transform" />
                                <h3 className="text-2xl font-bold dark:text-white mb-2">AI-Generated</h3>
                                <p className="text-gray-500">Provide a topic and let AI generate a full question bank with answers and explanations.</p>
                            </button>

                            <button 
                                onClick={() => { setCreationMode('MANUAL'); setWorkingQuestions([]); setView('INV_BUILDER'); }}
                                className="bg-white dark:bg-gray-800 p-10 rounded-[2.5rem] shadow-xl border-2 border-transparent hover:border-purple-500 text-left transition-all group"
                            >
                                <Edit3 className="w-12 h-12 text-purple-600 mb-6 group-hover:scale-110 transition-transform" />
                                <h3 className="text-2xl font-bold dark:text-white mb-2">Manual Build</h3>
                                <p className="text-gray-500">Craft every question from scratch. Full control over types, options, and difficulty.</p>
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* INVIGILATOR BUILDER */}
            {view === 'INV_BUILDER' && (
                <div className="flex-1 flex flex-col lg:flex-row gap-8 animate-fade-in pb-10">
                    {/* SETTINGS PANEL */}
                    <div className="w-full lg:w-96 space-y-6">
                        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2rem] shadow-xl border border-gray-100 dark:border-gray-700">
                            <h3 className="text-xl font-bold mb-6 flex items-center gap-2 dark:text-white">
                                <Settings className="w-5 h-5 text-gray-400" /> Session Architect
                            </h3>
                            <div className="space-y-4">
                                <div>
                                    <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-1">Test Name</label>
                                    <input 
                                        value={invSettings.title}
                                        onChange={e => setInvSettings({...invSettings, title: e.target.value})}
                                        className="w-full p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border-none focus:ring-2 focus:ring-indigo-500 dark:text-white"
                                        placeholder="e.g. Mid-Term Biology"
                                    />
                                </div>
                                {creationMode === 'AI' && (
                                    <div>
                                        <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-1">Topic</label>
                                        <input 
                                            value={invSettings.topic}
                                            onChange={e => setInvSettings({...invSettings, topic: e.target.value})}
                                            className="w-full p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border-none focus:ring-2 focus:ring-indigo-500 dark:text-white"
                                            placeholder="e.g. Newton's 3rd Law"
                                        />
                                    </div>
                                )}
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-1">Duration (Min)</label>
                                        <input 
                                            type="number"
                                            value={invSettings.duration}
                                            onChange={e => setInvSettings({...invSettings, duration: Number(e.target.value)})}
                                            className="w-full p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border-none dark:text-white"
                                        />
                                    </div>
                                    <div>
                                        <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-1">Q Count</label>
                                        <input 
                                            type="number"
                                            value={invSettings.qCount}
                                            onChange={e => setInvSettings({...invSettings, qCount: Number(e.target.value)})}
                                            className="w-full p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border-none dark:text-white"
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="mt-8 pt-8 border-t dark:border-gray-700 space-y-4">
                                <label className="flex items-center gap-3 cursor-pointer group">
                                    <div className={`w-10 h-5 rounded-full relative transition-colors ${invSettings.proctoring ? 'bg-indigo-600' : 'bg-gray-300'}`}>
                                        <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${invSettings.proctoring ? 'translate-x-5' : ''}`} />
                                    </div>
                                    <input type="checkbox" className="hidden" checked={invSettings.proctoring} onChange={() => setInvSettings({...invSettings, proctoring: !invSettings.proctoring})} />
                                    <span className="text-sm font-bold dark:text-gray-300">AI Proctoring</span>
                                </label>
                                <label className="flex items-center gap-3 cursor-pointer group">
                                    <div className={`w-10 h-5 rounded-full relative transition-colors ${invSettings.tabLock ? 'bg-indigo-600' : 'bg-gray-300'}`}>
                                        <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${invSettings.tabLock ? 'translate-x-5' : ''}`} />
                                    </div>
                                    <input type="checkbox" className="hidden" checked={invSettings.tabLock} onChange={() => setInvSettings({...invSettings, tabLock: !invSettings.tabLock})} />
                                    <span className="text-sm font-bold dark:text-gray-300">Tab Focus Lock</span>
                                </label>
                            </div>

                            {creationMode === 'AI' && (
                                <button 
                                    onClick={handleGenerateAI}
                                    disabled={isGenerating || !invSettings.topic}
                                    className="w-full mt-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold flex items-center justify-center gap-2 disabled:opacity-50"
                                >
                                    {isGenerating ? <Loader2 className="animate-spin w-5 h-5" /> : <Sparkles className="w-5 h-5" />}
                                    Generate Draft
                                </button>
                            )}
                        </div>
