                                            <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button onClick={() => setActiveEditIdx(idx)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded"><Edit3 className="w-5 h-5 text-indigo-600"/></button>
                                                <button onClick={() => removeQuestion(idx)} className="p-2 hover:bg-red-100 rounded"><Trash2 className="w-5 h-5 text-red-600"/></button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
