                                        <div className="w-2 h-2 rounded-full bg-green-500"></div>
                                    </div>
                                    <div className="absolute inset-0 bg-red-600/0 group-hover:bg-red-600/10 transition-colors pointer-events-none"></div>
                                </div>
                                <div className="flex justify-between items-center">
                                    <div>
                                        <p className="font-black dark:text-white">Student {i}</p>
                                        <p className="text-[10px] text-gray-400 font-bold uppercase">Progress: 40%</p>
                                    </div>
                                    <span className="text-xs bg-gray-100 dark:bg-gray-700 px-2 py-1 rounded-full dark:text-white">0 Warns</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
