                            </div>
                            <div className="bg-gray-50 dark:bg-gray-900 p-6 rounded-3xl flex gap-4">
                                <Mic className="w-6 h-6 text-red-600" />
                                <div><p className="font-bold dark:text-white">Audio Sensor</p><p className="text-xs text-gray-500">Sensitive to whispering and background voice.</p></div>
                            </div>
                            <div className="bg-gray-50 dark:bg-gray-900 p-6 rounded-3xl flex gap-4">
                                <Monitor className="w-6 h-6 text-red-600" />
                                <div><p className="font-bold dark:text-white">Focus Lock</p><p className="text-xs text-gray-500">Switching tabs will trigger immediate submission.</p></div>
                            </div>
                            <div className="bg-gray-50 dark:bg-gray-900 p-6 rounded-3xl flex gap-4">
                                <Clock className="w-6 h-6 text-red-600" />
