                        </div>
                    </div>
                </div>
            )}

            {/* STUDENT TAKING TEST */}
            {view === 'STU_TAKING' && activeTest && (
                <div className="flex-1 flex flex-col lg:flex-row gap-8 animate-fade-in pb-20">
                    {/* LEFT PANEL: NAVIGATION & SENSORS */}
                    <div className="w-full lg:w-80 flex flex-col gap-6 order-2 lg:order-1">
                        {/* CAMERA FEED */}
