                            <div className="absolute top-4 left-4 flex items-center gap-2 bg-black/40 px-3 py-1 rounded-full text-[10px] text-white font-black">
                                <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse"></div> SECURE REC
                            </div>
                            {audioLevel > 18 && (
                                <div className="absolute inset-0 flex items-center justify-center bg-red-600/20 backdrop-blur-[2px]">
                                    <div className="bg-red-600 text-white px-4 py-1.5 rounded-xl text-xs font-black animate-pulse flex items-center gap-2">
                                        <Mic className="w-4 h-4"/> VOICE DETECTED
                                    </div>
                                </div>
                            )}
                        </div>

                        {/* STATUS SENSORS */}
                        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] shadow-xl border dark:border-gray-700">
                             <div className="flex items-center justify-between mb-4">
                                <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest flex items-center gap-2">
                                    <Activity className="w-4 h-4 text-green-500" /> Proctoring
                                </h3>
                                <div className="flex gap-1">
                                    {[1,2,3,4,5].map(i => <div key={i} className={`w-3 h-3 rounded-full ${i <= warnings ? 'bg-red-600 animate-pulse' : 'bg-gray-100 dark:bg-gray-700'}`}></div>)}
                                </div>
                             </div>
                             <div className="space-y-4">
                                <div>
                                    <div className="flex justify-between text-[10px] font-bold text-gray-500 mb-1"><span>Audio Sensitive</span><span>{Math.round(audioLevel)}%</span></div>
                                    <div className="h-1.5 bg-gray-100 dark:bg-gray-700 rounded-full overflow-hidden">
                                        <div className={`h-full transition-all duration-150 ${audioLevel > 18 ? 'bg-red-600' : 'bg-green-500'}`} style={{width: `${Math.min(audioLevel*4, 100)}%`}}></div>
                                    </div>
                                </div>
                                <div className="flex items-center gap-3 p-3 bg-red-50 dark:bg-red-900/20 rounded-2xl">
                                    <Eye className="w-5 h-5 text-red-600" />
                                    <div>
                                        <p className="text-[10px] font-black text-red-800 dark:text-red-200 uppercase">{proctorStatus}</p>
                                        <p className="text-[10px] text-red-600">AI Gaze Locked</p>
                                    </div>
                                </div>
                             </div>
                        </div>

                        {/* QUESTION NAVIGATOR */}
                        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2rem] shadow-xl border dark:border-gray-700 flex-1">
                            <h3 className="text-xs font-black text-gray-400 uppercase tracking-widest mb-4">Hall Navigator</h3>
                            <div className="grid grid-cols-5 gap-2">
                                {activeTest.questions.map((_, i) => (
                                    <button 
                                        key={i}
                                        onClick={() => setCurrentQIdx(i)}
                                        className={`w-full aspect-square rounded-xl font-bold transition-all ${currentQIdx === i ? 'bg-red-600 text-white scale-110 shadow-lg' : answers[activeTest.questions[i].id] ? 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300' : 'bg-gray-50 dark:bg-gray-900 text-gray-400'}`}
                                    >
                                        {i + 1}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    {/* MAIN TEST AREA */}
                    <div className="flex-1 space-y-6 order-1 lg:order-2">
                        {/* HEADER: TIMER & TITLE */}
                        <div className="bg-white dark:bg-gray-800 p-6 rounded-[2.5rem] shadow-xl border dark:border-gray-700 flex justify-between items-center sticky top-0 z-20 backdrop-blur-md">
                            <div>
                                <h1 className="text-2xl font-black dark:text-white line-clamp-1">{activeTest.title}</h1>
                                <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">Question {currentQIdx + 1} of {activeTest.questions.length}</p>
                            </div>
                            <div className="flex items-center gap-3 bg-gray-50 dark:bg-gray-900 px-6 py-3 rounded-2xl border dark:border-gray-700">
                                <Clock className="w-6 h-6 text-red-600" />
                                <span className="text-3xl font-mono font-black text-red-600">
                                    {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
                                </span>
                            </div>
                        </div>

                        {/* QUESTION BOX */}
                        <div className="bg-white dark:bg-gray-800 p-10 rounded-[3rem] shadow-xl border dark:border-gray-700 min-h-[400px] flex flex-col">
                            <div className="flex-1">
                                <div className="flex gap-4 mb-10">
                                    <span className="text-5xl font-black text-red-600/20">{currentQIdx + 1}</span>
                                    <h2 className="text-3xl font-black dark:text-white leading-tight">{activeTest.questions[currentQIdx].text}</h2>
                                </div>

                                {activeTest.questions[currentQIdx].type === QuestionType.MCQ ? (
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                        {activeTest.questions[currentQIdx].options?.map((opt, oIdx) => (
                                            <button 
                                                key={oIdx}
                                                onClick={() => setAnswers({...answers, [activeTest.questions[currentQIdx].id]: opt})}
                                                className={`w-full text-left p-6 rounded-3xl border-4 transition-all flex items-center gap-4 group ${answers[activeTest.questions[currentQIdx].id] === opt ? 'border-red-600 bg-red-50 dark:bg-red-900/20' : 'border-gray-100 dark:border-gray-900 hover:bg-gray-50 dark:hover:bg-gray-750'}`}
                                            >
                                                <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black ${answers[activeTest.questions[currentQIdx].id] === opt ? 'bg-red-600 text-white' : 'bg-gray-100 dark:bg-gray-700 text-gray-400 group-hover:bg-red-100 group-hover:text-red-600'}`}>
                                                    {String.fromCharCode(65 + oIdx)}
                                                </div>
                                                <span className={`text-lg font-bold ${answers[activeTest.questions[currentQIdx].id] === opt ? 'text-red-900 dark:text-white' : 'text-gray-600 dark:text-gray-300'}`}>{opt}</span>
                                            </button>
                                        ))}
                                    </div>
                                ) : (
                                    <textarea 
                                        value={answers[activeTest.questions[currentQIdx].id] || ''}
                                        onChange={e => setAnswers({...answers, [activeTest.questions[currentQIdx].id]: e.target.value})}
                                        className="w-full p-8 bg-gray-50 dark:bg-gray-900 rounded-[2rem] border-none text-xl dark:text-white h-64 focus:ring-4 focus:ring-red-500/20"
                                        placeholder="Type your academic solution here..."
                                    />
                                )}
                            </div>

                            <div className="mt-10 flex justify-between border-t pt-8 dark:border-gray-700">
                                <button 
                                    disabled={currentQIdx === 0}
                                    onClick={() => setCurrentQIdx(currentQIdx - 1)}
                                    className="p-4 bg-gray-100 dark:bg-gray-700 rounded-2xl font-black text-gray-400 hover:text-black dark:hover:text-white disabled:opacity-30"
                                >
                                    <ChevronLeft className="w-8 h-8" />
                                </button>
                                {currentQIdx === activeTest.questions.length - 1 ? (
                                    <button 
                                        onClick={() => submitExam()}
                                        className="px-12 bg-green-600 text-white font-black text-2xl rounded-2xl shadow-xl hover:bg-green-700"
                                    >
                                        Submit Final
                                    </button>
                                ) : (
                                    <button 
                                        onClick={() => setCurrentQIdx(currentQIdx + 1)}
                                        className="p-4 bg-red-600 text-white rounded-2xl shadow-xl hover:bg-red-700"
                                    >
                                        <ChevronRight className="w-8 h-8" />
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* SUBMITTING STATE */}
            {view === 'STU_SUBMITTING' && (
                <div className="flex-1 flex flex-col items-center justify-center">
                    <div className="relative w-32 h-32">
                        <div className="absolute inset-0 border-8 border-gray-100 dark:border-gray-700 rounded-full"></div>
                        <div className="absolute inset-0 border-8 border-green-500 rounded-full border-t-transparent animate-spin"></div>
                    </div>
                    <h2 className="text-4xl font-black mt-10 dark:text-white">Closing Session Securely...</h2>
                    <p className="text-gray-500 text-lg">Validating logs and encrypting reports for review.</p>
                </div>
            )}
        </div>
    );
};

