    Copy, CheckCircle, Sparkles, Send, Mic, 
    Camera, Eye, Activity, Clock, ShieldAlert, X, GraduationCap, 
    Layout, Settings, Edit3, Trash2, List, CheckSquare, AlertCircle, 
    ChevronRight, ChevronLeft, Save, Globe, Monitor, BarChart3, Info
} from 'lucide-react';
import confetti from 'canvas-confetti';

interface ExaminationCenterProps {
    user: User;
    globalTests: TestData[];
    onAddTest: (test: TestData) => void;
    onSaveResult: (result: TestResult) => void;
}

const ExaminationCenter: React.FC<ExaminationCenterProps> = ({ user, globalTests, onAddTest, onSaveResult }) => {
    // VIEW MANAGEMENT
    const [view, setView] = useState<'HUB' | 'INV_METHOD' | 'INV_BUILDER' | 'INV_DASHBOARD' | 'INV_MONITOR' | 'STU_ENTRY' | 'STU_INSTRUCTIONS' | 'STU_TAKING' | 'STU_SUBMITTING'>('HUB');

    // INVIGILATOR STATE
    const [creationMode, setCreationMode] = useState<'AI' | 'MANUAL'>('AI');
    const [isGenerating, setIsGenerating] = useState(false);
    const [invSettings, setInvSettings] = useState({
        title: '',
        duration: 30,
        topic: '',
        qCount: 5,
        difficulty: 'Medium' as 'Easy' | 'Medium' | 'Hard',
        proctoring: true,
        tabLock: true
    });
    const [workingQuestions, setWorkingQuestions] = useState<Question[]>([]);
    const [activeEditIdx, setActiveEditIdx] = useState<number | null>(null);
    const [generatedCode, setGeneratedCode] = useState('');
    // Added copied state for the invitation code copy button to fix undefined error
    const [copied, setCopied] = useState(false);

    // STUDENT STATE
    const [joinCode, setJoinCode] = useState('');
    const [activeTest, setActiveTest] = useState<TestData | null>(null);
    const [answers, setAnswers] = useState<Record<number, string>>({});
    const [timeLeft, setTimeLeft] = useState(0);
    const [warnings, setWarnings] = useState(0);
    const [audioLevel, setAudioLevel] = useState(0);
    const [proctorStatus, setProctorStatus] = useState('Monitoring');
    const [currentQIdx, setCurrentQIdx] = useState(0);

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const lastViolationRef = useRef<number>(0);

    // --- INVIGILATOR LOGIC ---

    const handleGenerateAI = async () => {
        if (!invSettings.topic) return;
        setIsGenerating(true);
        try {
            const data = await generateTest(invSettings.topic, invSettings.difficulty, invSettings.qCount);
            setWorkingQuestions(data.questions);
            setInvSettings(prev => ({ ...prev, title: data.title }));
            setView('INV_BUILDER');
        } catch (e) {
            alert("AI generation failed. Please try a different topic.");
        } finally {
            setIsGenerating(false);
        }
    };

    const addManualQuestion = () => {
        const newQ: Question = {
            id: Date.now(),
            text: '',
            type: QuestionType.MCQ,
            options: ['', '', '', ''],
            correctAnswer: '',
            explanation: '',
            difficulty: 'Medium',
            marks: 1
        };
        setWorkingQuestions([...workingQuestions, newQ]);
        setActiveEditIdx(workingQuestions.length);
    };

    const removeQuestion = (idx: number) => {
        setWorkingQuestions(workingQuestions.filter((_, i) => i !== idx));
        if (activeEditIdx === idx) setActiveEditIdx(null);
    };

    const updateQuestion = (idx: number, updates: Partial<Question>) => {
        const updated = [...workingQuestions];
        updated[idx] = { ...updated[idx], ...updates };
        setWorkingQuestions(updated);
    };

    const finalizeTest = () => {
        if (!invSettings.title) { alert("Please provide a test name."); return; }
        if (workingQuestions.length === 0) { alert("Add at least one question."); return; }

        const code = Math.floor(100000 + Math.random() * 899999).toString();
        const newTest: TestData = {
            id: Date.now().toString(),
            title: invSettings.title,
            subject: invSettings.topic || 'General',
            creatorId: user.id,
            questions: workingQuestions,
            settings: {
                timeLimitMinutes: invSettings.duration,
                proctoring: invSettings.proctoring,
                adaptive: false,
                shuffleQuestions: true
            },
            status: 'LIVE',
            accessCode: code
        };
        onAddTest(newTest);
        setGeneratedCode(code);
        setView('INV_DASHBOARD');
    };

    // --- STUDENT LOGIC ---

    const handleJoin = () => {
        const test = globalTests.find(t => t.accessCode === joinCode);
        if (test) {
            setActiveTest(test);
            setView('STU_INSTRUCTIONS');
        } else {
            alert("Invalid Test Code. Check with your Invigilator.");
        }
    };

    const startExam = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
            streamRef.current = stream;
            setView('STU_TAKING');
            setTimeLeft((activeTest?.settings.timeLimitMinutes || 30) * 60);
        } catch (e) {
            alert("Permissions required to start the proctored exam.");
        }
    };

    const submitExam = (auto = false) => {
        setView('STU_SUBMITTING');
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        setTimeout(() => {
            const result: TestResult = {
                testId: activeTest?.id || 'public',
                studentId: user.id,
                score: Object.keys(answers).length, 
                maxScore: activeTest?.questions.length || 0,
                answers,
                dateTaken: new Date().toISOString(),
                status: 'COMPLETED',
                autoSubmitted: auto
            };
            onSaveResult(result);
            confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 } });
            setView('HUB');
            setJoinCode('');
        }, 2000);
    };

    // PROCTORING SYSTEM
    useEffect(() => {
        let visionInterval: any;
        let audioInterval: any;

        if (view === 'STU_TAKING' && streamRef.current) {
            if (videoRef.current) videoRef.current.srcObject = streamRef.current;

            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            audioContextRef.current = new AudioContext();
            analyserRef.current = audioContextRef.current.createAnalyser();
            const source = audioContextRef.current.createMediaStreamSource(streamRef.current);
            source.connect(analyserRef.current);

            visionInterval = setInterval(async () => {
                if (!videoRef.current) return;
                const canvas = document.createElement('canvas');
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;
                ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                setProctorStatus('Scanning...');
                const res = await analyzeProctoringFrame(base64);
                if (res.suspicious) triggerViolation(`AI Warning: ${res.reason}`);
                setProctorStatus('Monitoring');
            }, 7000);

            audioInterval = setInterval(() => {
                if (!analyserRef.current) return;
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteFrequencyData(data);
                const avg = data.reduce((a, b) => a + b) / data.length;
                setAudioLevel(avg);
                if (avg > 18) triggerViolation("Noise Detected");
            }, 250);
        }

        return () => {
            clearInterval(visionInterval);
            clearInterval(audioInterval);
        };
    }, [view]);

    const triggerViolation = (reason: string) => {
        if (Date.now() - lastViolationRef.current < 4000) return;
        lastViolationRef.current = Date.now();
        setWarnings(prev => {
            const next = prev + 1;
            if (next >= 5) submitExam(true);
            return next;
        });
        showViolationToast(reason);
    };

    const showViolationToast = (msg: string) => {
        const toast = document.createElement('div');
        toast.className = "fixed top-12 left-1/2 -translate-x-1/2 bg-red-600 text-white px-8 py-4 rounded-full shadow-2xl z-[999] animate-bounce font-bold border-2 border-white";
        toast.innerText = `PROCTOR ALERT: ${msg}`;
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 3500);
    };

    useEffect(() => {
        let t: any;
        if (view === 'STU_TAKING' && timeLeft > 0) {
            t = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
        } else if (view === 'STU_TAKING' && timeLeft === 0) {
            submitExam(true);
        }
        return () => clearInterval(t);
    }, [view, timeLeft]);

    return (
        <div className="p-6 max-w-7xl mx-auto min-h-[calc(100vh-4rem)] flex flex-col font-sans">

            {/* HUB VIEW */}
            {view === 'HUB' && (
                <div className="flex-1 flex flex-col justify-center animate-fade-in">
                    <div className="text-center mb-16">
                        <h1 className="text-6xl font-black mb-4 bg-gradient-to-r from-indigo-600 via-purple-600 to-red-600 bg-clip-text text-transparent">Examination Center</h1>
                        <p className="text-gray-500 text-xl font-medium">The proctored hub for guest access and public academic integrity.</p>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-12 max-w-5xl mx-auto w-full">
                        {/* INVIGILATOR HUB */}
                        <div className="bg-white dark:bg-gray-800 rounded-[3rem] p-12 shadow-2xl border-b-8 border-indigo-600 group transition-all hover:-translate-y-2">
                            <div className="w-20 h-20 bg-indigo-100 dark:bg-indigo-900/40 rounded-[2rem] flex items-center justify-center mb-8 group-hover:rotate-6 transition-transform">
                                <ShieldCheck className="w-10 h-10 text-indigo-600" />
                            </div>
                            <h2 className="text-4xl font-black dark:text-white mb-4">Invigilator</h2>
                            <p className="text-gray-500 mb-10 text-lg">Generate AI tests, build manual banks, and monitor live proctored sessions.</p>
                            <button 
                                onClick={() => setView('INV_METHOD')}
                                className="w-full py-5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold text-xl shadow-xl transition-all active:scale-95"
                            >
                                Enter Command Center
                            </button>
                        </div>

                        {/* STUDENT HUB */}
                        <div className="bg-white dark:bg-gray-800 rounded-[3rem] p-12 shadow-2xl border-b-8 border-red-600 group transition-all hover:-translate-y-2">
                            <div className="w-20 h-20 bg-red-100 dark:bg-red-900/40 rounded-[2rem] flex items-center justify-center mb-8 group-hover:-rotate-6 transition-transform">
                                <GraduationCap className="w-10 h-10 text-red-600" />
                            </div>
                            <h2 className="text-4xl font-black dark:text-white mb-4">Student</h2>
                            <p className="text-gray-500 mb-10 text-lg">Enter a unique hall code to access your exam under strict AI invigilation.</p>
                            <button 
                                onClick={() => setView('STU_ENTRY')}
                                className="w-full py-5 bg-red-600 hover:bg-red-700 text-white rounded-2xl font-bold text-xl shadow-xl transition-all active:scale-95"
                            >
                                Join Examination Hall
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* INVIGILATOR METHOD SELECTION */}
            {view === 'INV_METHOD' && (
                <div className="flex-1 flex flex-col animate-fade-in">
                    <button onClick={() => setView('HUB')} className="text-gray-500 font-bold mb-8 hover:text-black">← Return to Hub</button>
                    <div className="max-w-4xl mx-auto w-full">
                        <h2 className="text-4xl font-black mb-4 dark:text-white">Creation Method</h2>
                        <p className="text-gray-500 mb-10">Choose how you want to architect this examination session.</p>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
                            <button 
                                onClick={() => { setCreationMode('AI'); setWorkingQuestions([]); setView('INV_BUILDER'); }}
                                className="bg-white dark:bg-gray-800 p-10 rounded-[2.5rem] shadow-xl border-2 border-transparent hover:border-indigo-500 text-left transition-all group"
                            >
                                <Sparkles className="w-12 h-12 text-indigo-600 mb-6 group-hover:scale-110 transition-transform" />
                                <h3 className="text-2xl font-bold dark:text-white mb-2">AI-Generated</h3>
                                <p className="text-gray-500">Provide a topic and let AI generate a full question bank with answers and explanations.</p>
                            </button>

                            <button 
                                onClick={() => { setCreationMode('MANUAL'); setWorkingQuestions([]); setView('INV_BUILDER'); }}
                                className="bg-white dark:bg-gray-800 p-10 rounded-[2.5rem] shadow-xl border-2 border-transparent hover:border-purple-500 text-left transition-all group"
                            >
                                <Edit3 className="w-12 h-12 text-purple-600 mb-6 group-hover:scale-110 transition-transform" />
                                <h3 className="text-2xl font-bold dark:text-white mb-2">Manual Build</h3>
                                <p className="text-gray-500">Craft every question from scratch. Full control over types, options, and difficulty.</p>
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* INVIGILATOR BUILDER */}
            {view === 'INV_BUILDER' && (
                <div className="flex-1 flex flex-col lg:flex-row gap-8 animate-fade-in pb-10">
                    {/* SETTINGS PANEL */}
                    <div className="w-full lg:w-96 space-y-6">
                        <div className="bg-white dark:bg-gray-800 p-8 rounded-[2rem] shadow-xl border border-gray-100 dark:border-gray-700">
                            <h3 className="text-xl font-bold mb-6 flex items-center gap-2 dark:text-white">
                                <Settings className="w-5 h-5 text-gray-400" /> Session Architect
                            </h3>
                            <div className="space-y-4">
                                <div>
                                    <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-1">Test Name</label>
                                    <input 
                                        value={invSettings.title}
                                        onChange={e => setInvSettings({...invSettings, title: e.target.value})}
                                        className="w-full p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border-none focus:ring-2 focus:ring-indigo-500 dark:text-white"
                                        placeholder="e.g. Mid-Term Biology"
                                    />
                                </div>
                                {creationMode === 'AI' && (
                                    <div>
                                        <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-1">Topic</label>
                                        <input 
                                            value={invSettings.topic}
                                            onChange={e => setInvSettings({...invSettings, topic: e.target.value})}
                                            className="w-full p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border-none focus:ring-2 focus:ring-indigo-500 dark:text-white"
                                            placeholder="e.g. Newton's 3rd Law"
                                        />
                                    </div>
                                )}
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-1">Duration (Min)</label>
                                        <input 
                                            type="number"
                                            value={invSettings.duration}
                                            onChange={e => setInvSettings({...invSettings, duration: Number(e.target.value)})}
                                            className="w-full p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border-none dark:text-white"
                                        />
                                    </div>
                                    <div>
                                        <label className="text-xs font-black text-gray-400 uppercase tracking-widest block mb-1">Q Count</label>
                                        <input 
                                            type="number"
                                            value={invSettings.qCount}
                                            onChange={e => setInvSettings({...invSettings, qCount: Number(e.target.value)})}
                                            className="w-full p-3 bg-gray-50 dark:bg-gray-900 rounded-xl border-none dark:text-white"
                                        />
                                    </div>
                                </div>
                            </div>

                            <div className="mt-8 pt-8 border-t dark:border-gray-700 space-y-4">
                                <label className="flex items-center gap-3 cursor-pointer group">
                                    <div className={`w-10 h-5 rounded-full relative transition-colors ${invSettings.proctoring ? 'bg-indigo-600' : 'bg-gray-300'}`}>
                                        <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${invSettings.proctoring ? 'translate-x-5' : ''}`} />
                                    </div>
                                    <input type="checkbox" className="hidden" checked={invSettings.proctoring} onChange={() => setInvSettings({...invSettings, proctoring: !invSettings.proctoring})} />
                                    <span className="text-sm font-bold dark:text-gray-300">AI Proctoring</span>
                                </label>
                                <label className="flex items-center gap-3 cursor-pointer group">
                                    <div className={`w-10 h-5 rounded-full relative transition-colors ${invSettings.tabLock ? 'bg-indigo-600' : 'bg-gray-300'}`}>
                                        <div className={`absolute top-1 left-1 w-3 h-3 bg-white rounded-full transition-transform ${invSettings.tabLock ? 'translate-x-5' : ''}`} />
                                    </div>
                                    <input type="checkbox" className="hidden" checked={invSettings.tabLock} onChange={() => setInvSettings({...invSettings, tabLock: !invSettings.tabLock})} />
                                    <span className="text-sm font-bold dark:text-gray-300">Tab Focus Lock</span>
                                </label>
                            </div>

                            {creationMode === 'AI' && (
                                <button 
                                    onClick={handleGenerateAI}
                                    disabled={isGenerating || !invSettings.topic}
                                    className="w-full mt-8 py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-bold flex items-center justify-center gap-2 disabled:opacity-50"
                                >
                                    {isGenerating ? <Loader2 className="animate-spin w-5 h-5" /> : <Sparkles className="w-5 h-5" />}
                                    Generate Draft
                                </button>
                            )}
                        </div>
                    </div>

                    {/* QUESTION BUILDER AREA */}
                    <div className="flex-1 space-y-6">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-2xl font-black dark:text-white">Question Bank ({workingQuestions.length})</h2>
                            <div className="flex gap-2">
                                <button onClick={addManualQuestion} className="px-4 py-2 bg-white dark:bg-gray-800 rounded-lg font-bold border border-gray-200 dark:border-gray-700 dark:text-white hover:bg-gray-50 flex items-center gap-2">
                                    <Plus className="w-4 h-4" /> Add Manual
                                </button>
                                <button onClick={finalizeTest} className="px-6 py-2 bg-green-600 text-white rounded-lg font-bold shadow-lg hover:bg-green-700 flex items-center gap-2">
                                    <Globe className="w-4 h-4" /> Launch Test
                                </button>
                            </div>
                        </div>

                        {workingQuestions.length === 0 && !isGenerating && (
                            <div className="bg-gray-50 dark:bg-gray-900 border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-[2rem] p-20 text-center flex flex-col items-center">
                                <List className="w-16 h-16 text-gray-300 mb-4" />
                                <p className="text-gray-500 font-medium">Your question bank is empty. <br/>Use the settings panel to generate questions or add them manually.</p>
                            </div>
                        )}

                        <div className="space-y-4">
                            {workingQuestions.map((q, idx) => (
                                <div key={q.id} className="bg-white dark:bg-gray-800 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 overflow-hidden">
                                    {activeEditIdx === idx ? (
                                        <div className="p-8 space-y-6 animate-slide-in">
                                            <div className="flex justify-between items-start">
                                                <span className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-black">EDITING Q{idx + 1}</span>
                                                <button onClick={() => setActiveEditIdx(null)} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-700 rounded"><X className="w-5 h-5"/></button>
                                            </div>
                                            <input 
                                                value={q.text}
                                                onChange={e => updateQuestion(idx, { text: e.target.value })}
                                                className="w-full text-xl font-bold bg-transparent border-b-2 border-indigo-100 focus:border-indigo-600 outline-none p-2 dark:text-white"
                                                placeholder="Question Text..."
                                            />
                                            <div className="grid grid-cols-2 gap-4">
                                                <div>
                                                    <label className="text-xs font-black text-gray-400 uppercase mb-1 block">Type</label>
                                                    <select 
                                                        value={q.type}
                                                        onChange={e => updateQuestion(idx, { type: e.target.value as QuestionType })}
                                                        className="w-full p-2 bg-gray-50 dark:bg-gray-900 rounded-lg dark:text-white"
                                                    >
                                                        <option value={QuestionType.MCQ}>Multiple Choice</option>
                                                        <option value={QuestionType.SHORT}>Short Answer</option>
                                                        <option value={QuestionType.LONG}>Essay</option>
                                                        <option value={QuestionType.TRUE_FALSE}>True/False</option>
                                                    </select>
                                                </div>
                                                <div>
                                                    <label className="text-xs font-black text-gray-400 uppercase mb-1 block">Marks</label>
                                                    <input 
                                                        type="number"
                                                        value={q.marks}
                                                        onChange={e => updateQuestion(idx, { marks: Number(e.target.value) })}
                                                        className="w-full p-2 bg-gray-50 dark:bg-gray-900 rounded-lg dark:text-white"
                                                    />
                                                </div>
                                            </div>
                                            {q.type === QuestionType.MCQ && (
                                                <div className="space-y-2">
                                                    <label className="text-xs font-black text-gray-400 uppercase mb-1 block">Options (Check the correct one)</label>
                                                    {q.options?.map((opt, oIdx) => (
                                                        <div key={oIdx} className="flex gap-2">
                                                            <input 
                                                                type="checkbox"
                                                                checked={q.correctAnswer === opt && opt !== ''}
                                                                onChange={() => updateQuestion(idx, { correctAnswer: opt })}
                                                                className="mt-3 rounded text-indigo-600"
                                                            />
                                                            <input 
                                                                value={opt}
                                                                onChange={e => {
                                                                    const newOpts = [...(q.options || [])];
                                                                    newOpts[oIdx] = e.target.value;
                                                                    updateQuestion(idx, { options: newOpts });
                                                                }}
                                                                className="flex-1 p-3 bg-gray-50 dark:bg-gray-900 rounded-xl dark:text-white"
                                                                placeholder={`Option ${oIdx + 1}`}
                                                            />
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                            <button onClick={() => setActiveEditIdx(null)} className="w-full py-3 bg-indigo-600 text-white font-bold rounded-xl flex items-center justify-center gap-2">
                                                <CheckSquare className="w-5 h-5"/> Save Question
                                            </button>
                                        </div>
                                    ) : (
                                        <div className="p-6 flex justify-between items-center group">
                                            <div className="flex gap-4 items-center">
                                                <span className="w-8 h-8 flex-shrink-0 bg-gray-100 dark:bg-gray-700 rounded-full flex items-center justify-center font-bold dark:text-white">{idx + 1}</span>
                                                <div>
                                                    <p className="font-bold dark:text-white line-clamp-1">{q.text || "Untitled Question"}</p>
                                                    <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">{q.type} • {q.marks} Marks</p>
                                                </div>
                                            </div>
                                            <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button onClick={() => setActiveEditIdx(idx)} className="p-2 hover:bg-gray-100 dark:hover:bg-gray-700 rounded"><Edit3 className="w-5 h-5 text-indigo-600"/></button>
                                                <button onClick={() => removeQuestion(idx)} className="p-2 hover:bg-red-100 rounded"><Trash2 className="w-5 h-5 text-red-600"/></button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {/* INVIGILATOR DASHBOARD (Code Reveal & Monitoring Entrance) */}
            {view === 'INV_DASHBOARD' && (
                <div className="flex-1 flex flex-col items-center justify-center animate-scale-in">
                    <div className="bg-white dark:bg-gray-800 p-12 rounded-[4rem] shadow-2xl border border-indigo-50 dark:border-gray-700 max-w-2xl w-full text-center">
                        <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-8">
                            <CheckCircle className="w-12 h-12 text-green-600" />
                        </div>
                        <h2 className="text-5xl font-black mb-2 dark:text-white">Hall Is Live!</h2>
                        <p className="text-gray-500 mb-10 text-xl">Share this unique access code with your students.</p>

                        <div className="bg-indigo-50 dark:bg-gray-900 p-8 rounded-[2.5rem] mb-10 flex items-center justify-between border-2 border-indigo-100 dark:border-indigo-900/40">
                            <span className="text-7xl font-mono font-black tracking-widest text-indigo-600 select-all">{generatedCode}</span>
                            <button 
