                                  <Loader2 className="w-8 h-8" />
                              </div>
                              <h3 className="text-2xl font-bold mb-2">Method 1: AI Prompt</h3>
                              <p className="opacity-90">Simply type a topic and let AI generate questions, answers, and distractors instantly.</p>
