                        </div>
                    </div>
                </div>
            )}

            {/* VIEW: STUDENT ARENA */}
            {view === 'STU_ARENA' && activeTest && (
                <div className="flex-1 flex flex-col lg:flex-row gap-8 animate-fade-in pb-20 overflow-hidden relative">
