                                        <button onClick={() => setCurrentQIdx(currentQIdx + 1)} className="px-10 bg-red-600 text-white rounded-[2rem] shadow-2xl shadow-red-600/20 hover:bg-red-700 transition-all"><ChevronRight className="w-10 h-10" /></button>
