                                            <div className="flex justify-between items-center text-[10px] font-black"><span>T / F</span><span>{aiConfig.distributions.TF}%</span></div>
                                            <div className="w-full h-2 bg-gray-100 dark:bg-gray-900 rounded-full overflow-hidden"><div className="h-full bg-green-600 rounded" style={{width: `${aiConfig.distributions.TF}%`}}></div></div>

