                                            </div>
                                            {showExplanations && <div className="p-4 bg-indigo-50 dark:bg-indigo-900/40 rounded-2xl border border-indigo-100 dark:border-indigo-800"><p className="text-xs font-black text-indigo-600 uppercase mb-1 flex items-center gap-1"><Sparkles className="w-3 h-3"/> AI Explanation</p><p className="text-sm text-gray-700 dark:text-indigo-200 font-medium">{q.explanation}</p></div>}
                                        </div>
                                    );
                                })}
                            </div>
                        )}

                        <div className="flex gap-4">
                            <button onClick={() => { setAnswers({}); setCurrentQIdx(0); setView('STU_ARENA'); }} className="flex-1 py-5 bg-gray-100 dark:bg-gray-700 rounded-[2rem] font-black text-xl hover:bg-gray-200 flex items-center justify-center gap-2 transition-all dark:text-white"><RotateCcw className="w-5 h-5" /> Retake Demo</button>
                            <button onClick={() => setView('HUB')} className="flex-1 py-5 bg-indigo-600 text-white rounded-[2rem] font-black text-xl shadow-xl hover:bg-indigo-700 flex items-center justify-center gap-2 transition-all"><Layout className="w-5 h-5" /> Return Dashboard</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

