                                    </div>
                                ) : (
                                    <div className="relative group/input">
                                        <textarea value={answers[activeTest.questions[currentQIdx].id] || ''} onChange={e => setAnswers({...answers, [activeTest.questions[currentQIdx].id]: e.target.value})} className="w-full p-10 bg-gray-50 dark:bg-gray-900 rounded-[3rem] border-none text-2xl dark:text-white h-80 focus:ring-8 focus:ring-red-500/5 transition-all shadow-inner" placeholder="Draft your structured solution here..." />
                                        {activeTest.questions[currentQIdx].type === QuestionType.ESSAY && (
                                            <div className="absolute bottom-6 left-10 text-[10px] font-black text-gray-300 uppercase tracking-widest flex items-center gap-2">
                                                <AlertCircle className="w-3 h-3 text-indigo-400"/> Minimum Requirement: 50 Words (Current: {(answers[activeTest.questions[currentQIdx].id] || '').split(/\s+/).filter(x => x).length})
                                            </div>
                                        )}
                                        {activeTest.questions[currentQIdx].type === QuestionType.SHORT && (
                                            <div className="absolute bottom-6 left-10 text-[10px] font-black text-indigo-400 uppercase tracking-widest flex items-center gap-2">
                                                <Sparkles className="w-3 h-3"/> AI Hint: Use F = ma
                                            </div>
                                        )}
                                    </div>
                                )}
                            </div>

                            <div className="mt-12 flex justify-between border-t-2 border-gray-50 dark:border-gray-900 pt-10">
                                <button disabled={currentQIdx === 0} onClick={() => setCurrentQIdx(currentQIdx - 1)} className="p-6 bg-gray-100 dark:bg-gray-900 rounded-[2rem] font-black text-gray-400 hover:text-black dark:hover:text-white disabled:opacity-20 transition-all"><ChevronLeft className="w-10 h-10" /></button>
                                <div className="flex gap-4">
                                    {currentQIdx === activeTest.questions.length - 1 ? (
                                        <button onClick={() => submitStudentExam()} className="px-16 bg-green-600 text-white font-black text-2xl rounded-[2.5rem] shadow-2xl shadow-green-600/20 hover:bg-green-700 transition-all flex items-center gap-3"><CheckCircle className="w-8 h-8" /> Finalize Hall</button>
                                    ) : (
                                        <button onClick={() => setCurrentQIdx(currentQIdx + 1)} className="px-10 bg-red-600 text-white rounded-[2rem] shadow-2xl shadow-red-600/20 hover:bg-red-700 transition-all"><ChevronRight className="w-10 h-10" /></button>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* VIEW: STUDENT SUBMITTING */}
            {view === 'STU_SUBMITTING' && (
                <div className="flex-1 flex flex-col items-center justify-center animate-fade-in text-center">
                    <div className="relative w-48 h-48 mb-12">
                        <div className="absolute inset-0 border-[12px] border-gray-100 dark:border-gray-800 rounded-full"></div>
                        <div className="absolute inset-0 border-[12px] border-green-500 rounded-full border-t-transparent animate-spin"></div>
                        <div className="absolute inset-0 flex items-center justify-center"><Shield className="w-16 h-16 text-green-500" /></div>
                    </div>
                    <h2 className="text-5xl font-black mb-4 dark:text-white uppercase tracking-tight">Closing Hall Access</h2>
                    <p className="text-gray-500 text-2xl font-medium max-w-xl mx-auto">Evaluating proctoring logs and indexing your solutions. Stand by.</p>
                </div>
            )}

            {/* VIEW: STUDENT RESULTS (DEMO) */}
            {view === 'STU_RESULTS' && activeTest && (
                <div className="flex-1 flex flex-col items-center justify-center max-w-5xl mx-auto animate-fade-in py-10 w-full">
                    <div className="bg-white dark:bg-gray-800 p-12 rounded-[4rem] shadow-2xl border border-indigo-50 dark:border-gray-700 w-full">
                        <div className="text-center mb-12">
                             <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6"><Trophy className="w-10 h-10 text-green-600" /></div>
                             <h2 className="text-5xl font-black dark:text-white mb-2 uppercase">Arena Completed</h2>
                             <p className="text-gray-500 text-xl font-medium">Practice results processed successfully.</p>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
                            <div className="bg-indigo-50 dark:bg-indigo-900/20 p-10 rounded-[3rem] text-center border-2 border-indigo-100 dark:border-indigo-800">
                                <span className="text-xs font-black text-indigo-400 uppercase tracking-widest block mb-2">Seated Accuracy</span>
                                <span className="text-7xl font-black text-indigo-600">{Object.keys(answers).length} / {activeTest.questions.length}</span>
                            </div>
                            <div className="bg-green-50 dark:bg-green-900/20 p-10 rounded-[3rem] text-center border-2 border-green-100 dark:border-green-800">
                                <span className="text-xs font-black text-green-400 uppercase tracking-widest block mb-2">Grading Summary</span>
                                <span className="text-7xl font-black text-green-600">{Math.round((Object.keys(answers).length / activeTest.questions.length) * 100)}%</span>
                            </div>
                        </div>

                        {isDemoMode && (
                            <div className="space-y-6 mb-12 max-h-[400px] overflow-y-auto pr-4 custom-scrollbar">
                                <div className="flex justify-between items-center mb-4"><h3 className="font-black text-2xl dark:text-white uppercase tracking-tighter">Evaluation Breakdown</h3><button onClick={() => setShowExplanations(!showExplanations)} className="text-sm font-bold text-indigo-600 hover:underline">{showExplanations ? 'Hide Context' : 'View AI Context'}</button></div>
                                {activeTest.questions.map((q, idx) => {
                                    const isCorrect = answers[q.id]?.toLowerCase() === q.correctAnswer?.toLowerCase();
                                    return (
                                        <div key={idx} className="p-8 bg-gray-50 dark:bg-gray-900/50 rounded-[2.5rem] border border-gray-100 dark:border-gray-800">
                                            <div className="flex justify-between items-start mb-4">
                                                <p className="font-black text-xl dark:text-white leading-tight flex-1">{idx+1}. {q.text}</p>
                                                {q.type !== QuestionType.ESSAY && (isCorrect ? <CheckCircle className="w-8 h-8 text-green-500" /> : <div className="w-8 h-8 bg-red-100 text-red-500 rounded-full flex items-center justify-center font-black">X</div>)}
                                            </div>
                                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm mb-4">
                                                <div className="p-3 bg-white dark:bg-gray-800 rounded-xl border"><span className="text-[10px] font-black text-gray-400 block mb-1 uppercase tracking-widest">Submitted</span><p className="font-bold dark:text-white truncate">{answers[q.id] || 'NO RESPONSE'}</p></div>
                                                <div className="p-3 bg-white dark:bg-gray-800 rounded-xl border border-green-200"><span className="text-[10px] font-black text-green-400 block mb-1 uppercase tracking-widest">Correct Key</span><p className="font-bold text-green-600">{q.correctAnswer || q.modelAnswer}</p></div>
                                            </div>
                                            {showExplanations && <div className="p-4 bg-indigo-50 dark:bg-indigo-900/40 rounded-2xl border border-indigo-100 dark:border-indigo-800"><p className="text-xs font-black text-indigo-600 uppercase mb-1 flex items-center gap-1"><Sparkles className="w-3 h-3"/> AI Explanation</p><p className="text-sm text-gray-700 dark:text-indigo-200 font-medium">{q.explanation}</p></div>}
                                        </div>
                                    );
                                })}
                            </div>
                        )}

                        <div className="flex gap-4">
                            <button onClick={() => { setAnswers({}); setCurrentQIdx(0); setView('STU_ARENA'); }} className="flex-1 py-5 bg-gray-100 dark:bg-gray-700 rounded-[2rem] font-black text-xl hover:bg-gray-200 flex items-center justify-center gap-2 transition-all dark:text-white"><RotateCcw className="w-5 h-5" /> Retake Demo</button>
                            <button onClick={() => setView('HUB')} className="flex-1 py-5 bg-indigo-600 text-white rounded-[2rem] font-black text-xl shadow-xl hover:bg-indigo-700 flex items-center justify-center gap-2 transition-all"><Layout className="w-5 h-5" /> Return Dashboard</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

