interface ExaminationCenterProps {
    user: User;
    globalTests: TestData[];
    onAddTest: (test: TestData) => void;
    onSaveResult: (result: TestResult) => void;
}

const ExaminationCenter: React.FC<ExaminationCenterProps> = ({ user, globalTests, onAddTest, onSaveResult }) => {
    // --- NAVIGATION LOGIC ---
    // Start view based on role to avoid manual selection cards
    const getInitialView = () => {
        if (user.role === UserRole.TEACHER) return 'INV_STEP1';
        return 'STU_ENTRY'; // Default for Student and Guest Admin
    };

    const [view, setView] = useState<'INV_STEP1' | 'INV_STEP2' | 'INV_STEP3' | 'INV_DASHBOARD' | 'INV_MONITOR' | 'STU_ENTRY' | 'STU_LOADING' | 'STU_LOBBY' | 'STU_ARENA' | 'STU_SUBMITTING' | 'STU_RESULTS'>(getInitialView());

    // --- INVIGILATOR STATE ---
    const [creationMethod, setCreationMethod] = useState<'AI' | 'MANUAL'>('AI');
    const [isGenerating, setIsGenerating] = useState(false);
    const [workingTest, setWorkingTest] = useState<Partial<TestData>>({
        title: 'New Physics Assessment',
        subject: 'Physics',
        instructions: 'Follow all instructions carefully. AI proctoring is enabled.',
        questions: [],
        settings: {
            timeLimitMinutes: 30,
            proctoring: true,
            requireWebcam: true,
            preventTabSwitch: true,
            allowCalculator: false,
            allowInternet: false,
            adaptive: false,
            shuffleQuestions: true
        }
    });
    const [aiConfig, setAiConfig] = useState({
        topic: '',
        count: 10,
        difficulty: 'Medium' as 'Easy' | 'Medium' | 'Hard' | 'Mixed',
        distributions: { MCQ: 60, TF: 20, SHORT: 10, ESSAY: 10 }
    });
    const [activeEditIdx, setActiveEditIdx] = useState<number | null>(null);
    const [generatedCode, setGeneratedCode] = useState('');
    const [copied, setCopied] = useState(false);
    const [monitoringStudents, setMonitoringStudents] = useState([
        { id: '1', name: 'John Doe', question: 3, timeLeft: '12:45', status: 'Normal' },
        { id: '2', name: 'Jane Smith', question: 5, timeLeft: '08:30', status: 'Warning', alert: 'Multiple tab switches detected' },
        { id: '3', name: 'Bob Wilson', question: 'Submitted', timeLeft: '--:--', status: 'Completed' }
    ]);

    // --- STUDENT STATE ---
    const [joinCode, setJoinCode] = useState('');
    const [activeTest, setActiveTest] = useState<TestData | null>(null);
    const [answers, setAnswers] = useState<Record<number, string>>({});
    const [timeLeft, setTimeLeft] = useState(0);
    const [warnings, setWarnings] = useState(0);
    const [audioLevel, setAudioLevel] = useState(0);
    const [proctorStatus, setProctorStatus] = useState('Monitoring');
    const [currentQIdx, setCurrentQIdx] = useState(0);
    const [isDemoMode, setIsDemoMode] = useState(false);
    const [showExplanations, setShowExplanations] = useState(false);

    // --- REFS ---
    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const lastViolationRef = useRef<number>(0);

    // --- HANDLERS: INVIGILATOR ---

    const handleGenerateAI = async () => {
        if (!aiConfig.topic) return;
        setIsGenerating(true);
        try {
            const data = await generateTest(aiConfig.topic, aiConfig.difficulty, aiConfig.count);
            setWorkingTest(prev => ({
                ...prev,
                title: data.title || `${aiConfig.topic} Assessment`,
                subject: aiConfig.topic,
                questions: data.questions
            }));
            setView('INV_STEP2');
        } catch (e) {
            alert("AI generation failed. Please try a different topic.");
        } finally {
            setIsGenerating(false);
        }
    };

    const addManualQuestion = () => {
        const newQ: Question = {
            id: Date.now(),
            text: '',
            type: QuestionType.MCQ,
            options: ['', '', '', ''],
            correctAnswer: '',
            explanation: '',
            difficulty: 'Medium',
            marks: 1
        };
        setWorkingTest(prev => ({
            ...prev,
            questions: [...(prev.questions || []), newQ]
        }));
        setActiveEditIdx((workingTest.questions?.length || 0));
    };

    const deleteQuestion = (index: number) => {
        setWorkingTest(prev => ({
            ...prev,
            questions: prev.questions?.filter((_, i) => i !== index)
        }));
        if (activeEditIdx === index) setActiveEditIdx(null);
    };

    const finalizeTestCreation = () => {
        if (!workingTest.title || (workingTest.questions?.length || 0) === 0) {
            alert("Please provide a title and at least one question.");
            return;
        }
        const code = `PHY-${Math.random().toString(36).substring(2,6).toUpperCase()}-${Math.random().toString(36).substring(2,6).toUpperCase()}`;
        const newTest: TestData = {
            ...workingTest as TestData,
            id: Date.now().toString(),
            creatorId: user.id,
            status: 'LIVE',
            accessCode: code,
            resultsPublished: false
        };
        onAddTest(newTest);
        setGeneratedCode(code);
        setView('INV_DASHBOARD');
    };

    // --- HANDLERS: STUDENT ---

    const validateJoinCode = () => {
        if (joinCode === '000000') {
            setView('STU_LOADING');
            setTimeout(() => {
                setIsDemoMode(true);
                setActiveTest(PHYSICS_DEMO_TEST);
                setView('STU_ARENA');
                setTimeLeft(20 * 60);
            }, 1500);
        } else {
            const test = globalTests.find(t => t.accessCode === joinCode);
            if (test) {
                setIsDemoMode(false);
                setActiveTest(test);
                setView('STU_LOBBY');
            } else {
                alert("Invalid code. Please check and try again.");
            }
        }
    };

    const startStudentArena = async () => {
        if (!activeTest) return;

        if (activeTest.settings.requireWebcam && !isDemoMode) {
            try {
                const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
                streamRef.current = stream;
            } catch (e) {
                alert("Camera and Microphone permissions required.");
                return;
            }
        }

        setTimeLeft((activeTest.settings.timeLimitMinutes || 20) * 60);
        setCurrentQIdx(0);
        setAnswers({});
        setWarnings(0);
        setView('STU_ARENA');
    };

    const submitStudentExam = (auto = false) => {
        setView('STU_SUBMITTING');
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());

        setTimeout(() => {
            let correct = 0;
            activeTest?.questions.forEach(q => {
                const userAns = answers[q.id]?.trim().toLowerCase();
                const correctAns = q.correctAnswer?.trim().toLowerCase();
                if (userAns === correctAns) correct++;
            });

            const result: TestResult = {
                testId: activeTest?.id || 'public',
                studentId: user.id,
                score: correct,
                maxScore: activeTest?.questions.length || 0,
                answers,
                dateTaken: new Date().toISOString(),
                status: 'COMPLETED',
                autoSubmitted: auto
            };
            onSaveResult(result);
            confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 } });
            setView('STU_RESULTS');
        }, 2000);
    };

    // --- PROCTORING SYSTEM ---
    useEffect(() => {
        let visionInterval: any;
        let audioInterval: any;

        if (view === 'STU_ARENA' && activeTest?.settings.proctoring && streamRef.current && !isDemoMode) {
            if (videoRef.current) videoRef.current.srcObject = streamRef.current;
            visionInterval = setInterval(async () => {
                if (!videoRef.current) return;
                const canvas = document.createElement('canvas');
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;
                ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                setProctorStatus('Scanning...');
                const res = await analyzeProctoringFrame(base64);
                if (res.suspicious) triggerViolation(`AI Warning: ${res.reason}`);
                setProctorStatus('Monitoring');
            }, 8000);

            audioInterval = setInterval(() => {
                if (!analyserRef.current) return;
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteFrequencyData(data);
                const avg = data.reduce((a, b) => a + b) / data.length;
                setAudioLevel(avg);
                if (avg > 25) triggerViolation("Noise Detected");
            }, 500);
        }

        return () => {
            clearInterval(visionInterval);
            clearInterval(audioInterval);
        };
    }, [view, activeTest, isDemoMode]);

    const triggerViolation = (reason: string) => {
        if (isDemoMode) return;
        if (Date.now() - lastViolationRef.current < 5000) return;
        lastViolationRef.current = Date.now();
        setWarnings(prev => {
            const next = prev + 1;
            if (next >= 5) submitStudentExam(true);
            return next;
        });
        showViolationToast(reason);
    };

    const showViolationToast = (msg: string) => {
        const toast = document.createElement('div');
        toast.className = "fixed top-12 left-1/2 -translate-x-1/2 bg-red-600 text-white px-8 py-4 rounded-full shadow-2xl z-[999] animate-bounce font-bold border-2 border-white";
        toast.innerText = `PROCTOR ALERT: ${msg}`;
        document.body.appendChild(toast);
        setTimeout(() => toast.remove(), 4000);
    };

    useEffect(() => {
        let t: any;
        if (view === 'STU_ARENA' && timeLeft > 0) {
            t = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
        } else if (view === 'STU_ARENA' && timeLeft === 0) {
            submitStudentExam(true);
        }
        return () => clearInterval(t);
    }, [view, timeLeft]);

    const renderPortalHeader = () => (
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-10 border-b border-gray-100 dark:border-gray-800 pb-8">
            <div className="mb-4 md:mb-0">
                <h1 className="text-3xl font-black bg-gradient-to-r from-red-600 to-indigo-600 bg-clip-text text-transparent uppercase tracking-tighter">Examination Arena</h1>
                <p className="text-xs text-gray-400 font-bold uppercase tracking-widest mt-1">
                    {view.startsWith('INV') ? 'Invigilator Portal • Session Management' : 'Student Portal • Hall Authentication'}
                </p>
            </div>

            {/* Context Switcher for Guests/Admins to prevent role-lock confusion */}
            {user.role === UserRole.ADMIN && (
                <div className="flex bg-gray-50 dark:bg-gray-900 p-1.5 rounded-2xl border border-gray-100 dark:border-gray-800 shadow-inner">
                    <button 
                        onClick={() => setView('STU_ENTRY')}
                        className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase transition-all duration-300 flex items-center gap-2 ${view.startsWith('STU') ? 'bg-white dark:bg-gray-800 shadow-md text-red-600 ring-1 ring-black/5' : 'text-gray-400 hover:text-gray-600'}`}
                    >
                        <GraduationCap className="w-4 h-4" /> Student Portal
                    </button>
                    <button 
                        onClick={() => setView('INV_STEP1')}
                        className={`px-6 py-2.5 rounded-xl text-xs font-black uppercase transition-all duration-300 flex items-center gap-2 ${view.startsWith('INV') ? 'bg-white dark:bg-gray-800 shadow-md text-indigo-600 ring-1 ring-black/5' : 'text-gray-400 hover:text-gray-600'}`}
                    >
                        <ShieldCheck className="w-4 h-4" /> Invigilator Portal
                    </button>
                </div>
            )}
        </div>
    );

    return (
        <div className="p-6 max-w-7xl mx-auto min-h-[calc(100vh-4rem)] flex flex-col font-sans overflow-hidden">

            {/* VIEW: ROLE-BASED AUTOMATIC REDIRECTION INTERFACES */}

            {/* INVIGILATOR STEP 1: Creation Start */}
            {view === 'INV_STEP1' && (
                <div className="flex-1 flex flex-col animate-fade-in">
