                                        >
                                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-lg flex-shrink-0 transition-all ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'bg-red-600 text-white scale-110 shadow-lg' : 'bg-gray-100 dark:bg-gray-700 text-gray-400 group-hover:bg-red-100 group-hover:text-red-600'}`}>{String.fromCharCode(65 + oIdx)}</div>
                                            <span className={`text-lg font-bold ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'text-red-900 dark:text-white' : 'text-gray-600 dark:text-gray-300'}`}>{opt}</span>
