                            <div className="mt-12 flex justify-between items-center border-t-2 border-gray-50 dark:border-gray-800 pt-10">
                                <button disabled={currentQIdx === 0} onClick={() => setCurrentQIdx(currentQIdx - 1)} className="p-5 bg-gray-100 dark:bg-gray-800 rounded-2xl font-black text-gray-400 hover:text-black dark:hover:text-white disabled:opacity-10 transition-all"><ChevronLeft className="w-8 h-8" /></button>

