                                    {currentQIdx === MOCK_QUESTIONS.length - 1 ? (
                                        <button onClick={finalizeExam} className="px-12 bg-green-600 text-white font-black text-xl rounded-2xl shadow-xl shadow-green-600/20 hover:bg-green-700 transition-all flex items-center gap-3 active:scale-95">Finish & Submit</button>
                                    ) : (
                                        <button onClick={() => setCurrentQIdx(currentQIdx + 1)} className="px-8 bg-red-600 text-white rounded-2xl shadow-xl shadow-red-600/20 hover:bg-red-700 transition-all active:scale-95"><ChevronRight className="w-8 h-8" /></button>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* TERMINATED PHASE */}
            {phase === 'TERMINATED' && (
                <div className="flex-1 flex flex-col items-center justify-center animate-fade-in p-8">
                    <div className="w-full max-w-md bg-red-50 dark:bg-red-900/20 p-12 rounded-[3rem] shadow-2xl border-4 border-red-600 text-center">
                        <div className="w-24 h-24 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-8 animate-pulse"><AlertTriangle className="w-12 h-12 text-red-600" /></div>
                        <h2 className="text-3xl font-black text-red-600 mb-4 uppercase tracking-tighter">Session Terminated</h2>
                        <p className="text-red-900 dark:text-red-200 font-bold mb-8 italic">Multiple security violations or intentional lockdown breach detected. Your identity and logs have been reported to the exam board.</p>
                        <button onClick={() => window.location.reload()} className="w-full py-4 bg-red-600 text-white rounded-2xl font-black hover:bg-red-700 transition-all">Exit Portal</button>
                    </div>
                </div>
            )}

            {/* SUBMITTING PHASE */}
            {phase === 'SUBMITTING' && (
                <div className="flex-1 flex flex-col items-center justify-center animate-fade-in text-center p-8">
                    <Loader2 className="w-16 h-16 text-indigo-600 animate-spin mb-8" />
                    <h2 className="text-4xl font-black dark:text-white uppercase tracking-tight">Closing Hall Access</h2>
                    <p className="text-gray-500 text-lg">Encrypting proctoring logs and indexing your final responses...</p>
                </div>
            )}

            {/* RESULT PHASE */}
            {phase === 'RESULT' && (
                <div className="flex-1 flex flex-col items-center justify-center animate-fade-in p-8">
                    <div className="w-full max-w-2xl bg-white dark:bg-gray-900 p-12 rounded-[4rem] shadow-2xl border-t-8 border-indigo-600 text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 p-12 opacity-5"><Shield className="w-48 h-48" /></div>
                        <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6"><Trophy className="w-10 h-10 text-green-600" /></div>
                        <h2 className="text-5xl font-black dark:text-white mb-2 uppercase">Examination Completed</h2>
                        <p className="text-gray-500 text-xl font-medium mb-12">Session results recorded successfully.</p>

                        <div className="grid grid-cols-2 gap-6 mb-12">
                            <div className="p-8 bg-gray-50 dark:bg-gray-800 rounded-[2.5rem] border border-gray-100 dark:border-gray-700">
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Items Answered</p>
                                <p className="text-5xl font-black dark:text-white">{Object.keys(answers).length} / {MOCK_QUESTIONS.length}</p>
                            </div>
                            <div className="p-8 bg-gray-50 dark:bg-gray-800 rounded-[2.5rem] border border-gray-100 dark:border-gray-700">
                                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Integrity Rating</p>
                                <p className={`text-5xl font-black ${warnings === 0 ? 'text-green-600' : 'text-orange-500'}`}>{100 - (warnings * 20)}%</p>
                            </div>
                        </div>

                        <button onClick={() => window.location.reload()} className="w-full py-6 bg-indigo-600 text-white rounded-[2.5rem] font-black text-xl hover:bg-indigo-700 shadow-xl transition-all active:scale-95">Return to Portal Home</button>
                    </div>
                </div>
            )}

        </div>
    );
};

export default ExaminationCenter;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeProctoringFrame } from '../services/gemini';
import { TestData, User, TestResult, QuestionType, Question } from '../types';
import { 
    Play, ShieldCheck, Hash, CheckCircle, Camera, Eye, Activity, 
    Clock, ShieldAlert, X, GraduationCap, AlertCircle, 
    ChevronRight, ChevronLeft, Globe, Monitor, Info, Shield, 
    Calculator, MessageSquare, AlertTriangle, ArrowRight,
    Trophy, RotateCcw, Layers, Lock, UserCheck, Mic, Laptop,
    Loader2
} from 'lucide-react';
import confetti from 'canvas-confetti';

// --- MOCK REGISTRATION DATA ---
const VALID_EXAMS = [
    { id: 'PHY-2025-01', name: 'National Physics Olympiad (Junior)', validIds: ['ID-111', 'ID-222', 'ID-333'] },
    { id: 'MAT-2025-05', name: 'Advanced Calculus Certification', validIds: ['ID-444', 'ID-555'] },
    { id: 'ENG-2025-09', name: 'Global English Proficiency Test', validIds: ['ID-777', 'ID-888'] }
];

const MOCK_QUESTIONS: Question[] = [
    { id: 1, text: "Which particle carries a positive charge?", type: QuestionType.MCQ, options: ["Electron", "Neutron", "Proton", "Photon"], correctAnswer: "Proton", difficulty: "Easy", explanation: "Protons are positive particles in the nucleus.", marks: 2 },
    { id: 2, text: "What is the speed of light in a vacuum (approx)?", type: QuestionType.MCQ, options: ["300,000 km/s", "150,000 km/s", "500,000 km/s", "200,000 km/s"], correctAnswer: "300,000 km/s", difficulty: "Medium", explanation: "Light travels at roughly 3e8 m/s.", marks: 2 },
    { id: 3, text: "The first law of thermodynamics is concerned with the conservation of...", type: QuestionType.MCQ, options: ["Mass", "Energy", "Momentum", "Charge"], correctAnswer: "Energy", difficulty: "Medium", explanation: "Energy cannot be created or destroyed.", marks: 2 },
    { id: 4, text: "What is the unit of electrical resistance?", type: QuestionType.MCQ, options: ["Volt", "Ampere", "Ohm", "Watt"], correctAnswer: "Ohm", difficulty: "Easy", explanation: "Named after Georg Simon Ohm.", marks: 2 },
    { id: 5, text: "Which color of light has the longest wavelength?", type: QuestionType.MCQ, options: ["Blue", "Green", "Violet", "Red"], correctAnswer: "Red", difficulty: "Hard", explanation: "Red light has wavelengths around 700nm.", marks: 2 }
];

type PortalPhase = 'WELCOME' | 'BIOMETRIC' | 'AUTH' | 'PRE_EXAM' | 'ARENA' | 'SUBMITTING' | 'RESULT' | 'TERMINATED';

/* Updated ExaminationCenter props to match the parameters passed from App.tsx and fix IntrinsicAttributes error */
const ExaminationCenter: React.FC<{ 
    user: User; 
    globalTests: TestData[];
    onAddTest: (test: TestData) => void;
    onSaveResult: (result: TestResult) => void 
}> = ({ user, globalTests, onAddTest, onSaveResult }) => {
    const [phase, setPhase] = useState<PortalPhase>('WELCOME');
    const [selectedExamId, setSelectedExamId] = useState('');
    const [appNumber, setAppNumber] = useState('');
    const [capturedFace, setCapturedFace] = useState<string | null>(null);
    const [isFaceVerified, setIsFaceVerified] = useState(false);

    // Exam Arena State
    const [currentQIdx, setCurrentQIdx] = useState(0);
    const [answers, setAnswers] = useState<Record<number, string>>({});
    const [timeLeft, setTimeLeft] = useState(600); // 10 minutes
    const [warnings, setWarnings] = useState(0);
    const [audioLevel, setAudioLevel] = useState(0);
    const [proctorStatus, setProctorStatus] = useState('Standby');

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const lastViolationRef = useRef<number>(0);

    // --- KEYBOARD LOCKDOWN ---
    useEffect(() => {
        if (phase === 'ARENA') {
            const blockKeyboard = (e: KeyboardEvent) => {
                // Allow only F5, F12 for dev or block everything for production
                e.preventDefault();
                showViolationToast("KEYBOARD DISABLED: Mouse Use Only");
            };
            window.addEventListener('keydown', blockKeyboard);
            return () => window.removeEventListener('keydown', blockKeyboard);
        }
    }, [phase]);

    // --- FULLSCREEN LOCKDOWN ---
    useEffect(() => {
        const handleFSChange = () => {
            if (!document.fullscreenElement && phase === 'ARENA') {
                triggerViolation("FULLSCREEN EXIT DETECTED", true);
            }
        };
        document.addEventListener('fullscreenchange', handleFSChange);
        return () => document.removeEventListener('fullscreenchange', handleFSChange);
    }, [phase]);

    // --- PROCTORING AGENT ---
    useEffect(() => {
        let visionInterval: any;
        if (phase === 'ARENA' && streamRef.current) {
            visionInterval = setInterval(async () => {
                if (!videoRef.current) return;
                const canvas = document.createElement('canvas');
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;
                ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                setProctorStatus('Scanning Presence...');
                try {
                    const res = await analyzeProctoringFrame(base64);
                    if (res.suspicious) triggerViolation(`AI Alert: ${res.reason}`);
                } catch (e) {}
                setProctorStatus('Active Monitoring');
            }, 10000);
        }
        return () => clearInterval(visionInterval);
    }, [phase]);

    const triggerViolation = (reason: string, fatal: boolean = false) => {
        if (Date.now() - lastViolationRef.current < 4000) return;
        lastViolationRef.current = Date.now();

        if (fatal) {
            setPhase('TERMINATED');
            return;
        }

        setWarnings(prev => {
            const next = prev + 1;
            if (next >= 5) setPhase('TERMINATED');
            return next;
        });
        showViolationToast(reason);
    };

    const showViolationToast = (msg: string) => {
        const t = document.createElement('div');
        t.className = "fixed top-10 left-1/2 -translate-x-1/2 bg-red-600 text-white px-8 py-4 rounded-full shadow-2xl z-[999] animate-bounce font-bold border-2 border-white uppercase text-sm";
        t.innerText = `SECURITY ALERT: ${msg}`;
        document.body.appendChild(t);
        setTimeout(() => t.remove(), 3000);
    };

    // --- PHASE TRANSITIONS ---
    const handleExamSelect = async (id: string) => {
        setSelectedExamId(id);
        setPhase('BIOMETRIC');
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
            streamRef.current = stream;
            if (videoRef.current) videoRef.current.srcObject = stream;
        } catch (e) {
            alert("Mandatory Camera Access Denied. Entrance Blocked.");
            setPhase('WELCOME');
        }
    };

    const captureIdentity = () => {
        if (!videoRef.current) return;
        const canvas = document.createElement('canvas');
        canvas.width = 640; canvas.height = 480;
        canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0);
        setCapturedFace(canvas.toDataURL('image/jpeg'));
        setPhase('AUTH');
    };

    const validateAccess = () => {
        const exam = VALID_EXAMS.find(e => e.id === selectedExamId);
        if (exam?.validIds.includes(appNumber)) {
            setIsFaceVerified(true);
            setPhase('PRE_EXAM');
        } else {
            alert("Invalid Application Number for selected exam.");
        }
    };

    const startExamArena = () => {
        document.documentElement.requestFullscreen().then(() => {
            setPhase('ARENA');
            setTimeLeft(600);
        }).catch(() => {
            alert("Full-screen mode is required to start.");
        });
    };

    const finalizeExam = () => {
        setPhase('SUBMITTING');
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        setTimeout(() => {
            setPhase('RESULT');
            confetti({ particleCount: 100, spread: 60, origin: { y: 0.7 } });
        }, 3000);
    };

    useEffect(() => {
        let t: any;
        if (phase === 'ARENA' && timeLeft > 0) t = setInterval(() => setTimeLeft(p => p - 1), 1000);
        else if (phase === 'ARENA' && timeLeft === 0) finalizeExam();
        return () => clearInterval(t);
    }, [phase, timeLeft]);

    return (
        <div className="min-h-[calc(100vh-4rem)] bg-gray-50 dark:bg-gray-950 flex flex-col font-sans transition-all duration-500">

            {/* WELCOME PHASE */}
            {phase === 'WELCOME' && (
                <div className="flex-1 flex flex-col items-center justify-center animate-fade-in p-8 text-center">
                    <div className="w-20 h-20 bg-indigo-100 dark:bg-indigo-900/30 rounded-3xl flex items-center justify-center mb-8 shadow-xl">
                        <ShieldCheck className="w-10 h-10 text-indigo-600" />
                    </div>
                    <h1 className="text-4xl font-black dark:text-white mb-2 uppercase tracking-tighter">Unified Examination Portal</h1>
                    <p className="text-gray-500 dark:text-gray-400 mb-12 text-lg max-w-md">Authorized guest entry for proctored digital certifications.</p>

                    <div className="w-full max-w-lg space-y-4">
                        <label className="block text-xs font-black text-gray-400 uppercase tracking-widest text-left ml-4 mb-2">Select Registered Examination</label>
                        <div className="grid grid-cols-1 gap-4">
                            {VALID_EXAMS.map(e => (
                                <button 
                                    key={e.id}
                                    onClick={() => handleExamSelect(e.id)}
                                    className="p-6 bg-white dark:bg-gray-900 rounded-[2rem] shadow-lg border-2 border-transparent hover:border-indigo-500 transition-all flex items-center justify-between group text-left"
                                >
                                    <div>
                                        <h3 className="font-bold dark:text-white group-hover:text-indigo-600 transition-colors">{e.name}</h3>
