                    {aiWarning && (
                        <div className="fixed top-20 left-1/2 -translate-x-1/2 z-[100] bg-red-600 text-white px-10 py-5 rounded-[2rem] shadow-2xl animate-bounce font-black uppercase text-sm border-4 border-white flex items-center gap-4">
