            {/* APP VERIFICATION */}
            {phase === 'VERIFY_APP' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-md bg-white dark:bg-slate-900 p-10 rounded-2xl shadow-xl border border-slate-100 dark:border-slate-800 text-center">
