                                    placeholder="Enter your application number"
                                    className="w-full pl-12 p-4 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 text-lg font-black tracking-widest text-slate-900 dark:text-white outline-none focus:ring-2 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all"
                                />
                            </div>
                        </div>

                        {isVerifying ? (
                            <div className="h-14 flex items-center justify-center gap-3 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 rounded-xl font-bold">
                                <Loader2 className="w-5 h-5 animate-spin" />
                                <span>Verifying...</span>
                            </div>
                        ) : isAppVerified ? (
                            <div className="p-4 bg-green-50 dark:bg-green-900/20 border border-green-100 dark:border-green-800/30 rounded-xl flex flex-col items-center animate-scale-in">
                                <div className="w-10 h-10 bg-green-100 dark:bg-green-800/40 rounded-full flex items-center justify-center mb-2">
                                    <CheckCircle className="w-6 h-6 text-green-600" />
                                </div>
                                <span className="text-green-600 font-bold text-sm tracking-tight italic">✔ Application number verified successfully</span>
                            </div>
                        ) : (
                            <button 
                                onClick={handleVerifyApp} 
                                disabled={!appNumber}
                                className="w-full h-14 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-black text-lg shadow-lg shadow-indigo-600/20 transition-all active:scale-95 disabled:opacity-50 disabled:grayscale"
                            >
                                Verify & Continue
                            </button>
                        )}

                        <button 
                            onClick={() => setPhase('WELCOME')} 
                            className="mt-8 text-slate-400 hover:text-indigo-600 text-xs font-bold uppercase tracking-tighter transition-colors flex items-center justify-center gap-2 mx-auto"
                        >
                            <ChevronLeft className="w-3 h-3" /> Choose a different exam
                        </button>
                    </div>
                </div>
            )}

            {/* IDENTITY CAPTURE */}
            {phase === 'IDENTITY_CAPTURE' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-4xl bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-2xl text-center">
