    { id: 5, text: "What is the standard port for SSH?", type: QuestionType.MCQ, options: ["21", "22", "80", "443"], correctAnswer: "22", difficulty: "Hard", explanation: "SSH typically uses port 22.", marks: 2 }
];

type PortalPhase = 'WELCOME' | 'VERIFY_APP' | 'IDENTITY_CAPTURE' | 'MATCHING' | 'INSTRUCTIONS' | 'ARENA' | 'SUBMITTING' | 'RESULT' | 'BLOCKED';

interface ExaminationCenterProps {
    user: User;
    onSaveResult: (result: TestResult) => void;
    onLogout: () => void; 
    globalTests?: any;
    onAddTest?: any;
}

const ExaminationCenter: React.FC<ExaminationCenterProps> = ({ user, onSaveResult, onLogout }) => {
    const [phase, setPhase] = useState<PortalPhase>('WELCOME');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedExam, setSelectedExam] = useState('');
    const [appNumber, setAppNumber] = useState('');
    const [isAppVerified, setIsAppVerified] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);

    // Identity State
    const [captures, setCaptures] = useState<{ front: string | null; left: string | null; right: string | null }>({ front: null, left: null, right: null });
    const [matchingStatus, setMatchingStatus] = useState<'idle' | 'processing' | 'matched' | 'failed'>('idle');

    // Exam Arena State
    const [currentQIdx, setCurrentQIdx] = useState(0);
    const [answers, setAnswers] = useState<Record<number, string>>({});
    const [timeLeft, setTimeLeft] = useState(600); // 10 mins
    const [warnings, setWarnings] = useState(0);
    const [proctorStatus, setProctorStatus] = useState('Monitoring');
    const [aiWarning, setAiWarning] = useState<string | null>(null);

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const lastViolationRef = useRef<number>(0);

    // Filtered Exams
    const filteredExams = EXAM_LIST.filter(e => e.toLowerCase().includes(searchTerm.toLowerCase()));

    // --- KEYBOARD LOCKDOWN ---
    useEffect(() => {
        if (phase === 'ARENA') {
            const blockKeys = (e: KeyboardEvent) => {
                e.preventDefault();
                setAiWarning("KEYBOARD INPUT DETECTED: Mouse Use Only.");
                setTimeout(() => setAiWarning(null), 3000);
            };
            window.addEventListener('keydown', blockKeys);
            return () => window.removeEventListener('keydown', blockKeys);
        }
    }, [phase]);

    // --- FULLSCREEN ENFORCEMENT ---
    useEffect(() => {
        const handleFS = () => {
            if (!document.fullscreenElement && phase === 'ARENA') {
                setPhase('BLOCKED');
            }
        };
        document.addEventListener('fullscreenchange', handleFS);
        return () => document.removeEventListener('fullscreenchange', handleFS);
    }, [phase]);

    // --- PROCTORING AGENT ---
    useEffect(() => {
        let visionInterval: any;
        if (phase === 'ARENA' && streamRef.current) {
            visionInterval = setInterval(async () => {
                if (!videoRef.current) return;
                const canvas = document.createElement('canvas');
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;
                ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                setProctorStatus('Scanning behavior...');
                try {
                    const res = await analyzeProctoringFrame(base64);
                    if (res.suspicious) {
                        triggerViolation(res.reason);
                    } else {
                        setAiWarning(null);
                    }
                } catch (e) {}
                setProctorStatus('Active AI Monitoring');
            }, 8000);
        }
        return () => clearInterval(visionInterval);
    }, [phase]);

    const triggerViolation = (reason: string) => {
        if (Date.now() - lastViolationRef.current < 4000) return;
        lastViolationRef.current = Date.now();

        setWarnings(prev => {
            const next = prev + 1;
            setAiWarning(`Please look straight at the screen. This is warning #${next}.`);
            if (next >= 5) setPhase('BLOCKED');
            return next;
        });
    };

    // --- CAMERA ACCESS ---
    const startCamera = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
            streamRef.current = stream;
            if (videoRef.current) videoRef.current.srcObject = stream;
        } catch (e) {
            alert("Camera access is mandatory to enter the hall.");
        }
    };

    // --- HANDLERS ---
    const handleVerifyApp = () => {
        if (!appNumber.trim()) {
            alert("Please enter your application number.");
            return;
        }

        setIsVerifying(true);
        // Allow any application number for now
        setTimeout(() => {
            setIsVerifying(false);
            setIsAppVerified(true);
            setTimeout(() => {
                setPhase('IDENTITY_CAPTURE');
                startCamera();
            }, 1200);
        }, 1500);
    };

    const captureView = (view: 'front' | 'left' | 'right') => {
        if (!videoRef.current) return;
        const canvas = document.createElement('canvas');
        canvas.width = 640; canvas.height = 480;
        canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0);
        setCaptures(prev => ({ ...prev, [view]: canvas.toDataURL('image/jpeg') }));
    };

    const runIdentityMatch = () => {
        setPhase('MATCHING');
        setMatchingStatus('processing');
        setTimeout(() => {
            setMatchingStatus('matched');
            setTimeout(() => setPhase('INSTRUCTIONS'), 1500);
        }, 3000);
    };

    const startTest = () => {
        document.documentElement.requestFullscreen().then(() => {
            setPhase('ARENA');
        }).catch(() => alert("Full-screen required."));
    };

    const finalizeTest = () => {
        setPhase('SUBMITTING');
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        setTimeout(() => {
            setPhase('RESULT');
            confetti({ particleCount: 150, spread: 70, origin: { y: 0.6 } });
        }, 3000);
    };

    useEffect(() => {
        let t: any;
        if (phase === 'ARENA' && timeLeft > 0) t = setInterval(() => setTimeLeft(p => p - 1), 1000);
        else if (phase === 'ARENA' && timeLeft === 0) finalizeTest();
        return () => clearInterval(t);
    }, [phase, timeLeft]);

    return (
        <div className="min-h-[calc(100vh)] bg-slate-50 dark:bg-slate-950 flex flex-col font-sans transition-colors duration-500 relative">

            {/* UNIFIED PORTAL HEADER (Replaces sidebar functionality) */}
            <header className="sticky top-0 z-[100] w-full bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 px-8 py-4 flex justify-between items-center shadow-sm">
                <div className="flex items-center gap-2">
                    <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-indigo-600/20 shadow-lg">
                        <ShieldCheck className="w-5 h-5 text-white" />
                    </div>
                    <span className="text-xl font-black bg-gradient-to-r from-indigo-600 to-purple-600 bg-clip-text text-transparent">
                        MyClassroom
                    </span>
                    <span className="ml-3 px-2 py-0.5 bg-slate-100 dark:bg-slate-800 rounded text-[10px] font-black text-slate-500 uppercase tracking-widest border border-slate-200 dark:border-slate-700">
                        Exam Mode
                    </span>
                </div>

                <button 
                    onClick={onLogout}
                    className="flex items-center gap-2 px-4 py-2 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 border border-red-200 dark:border-red-800 rounded-xl font-bold text-sm hover:bg-red-100 transition-all shadow-sm active:scale-95 group"
                >
                    <LogOut className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                    Log Out
                </button>
            </header>

            {/* WELCOME & SELECTION */}
            {phase === 'WELCOME' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in text-center">
                    <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center mb-8 shadow-2xl animate-pulse">
                        <ShieldCheck className="w-10 h-10 text-white" />
                    </div>
                    <h1 className="text-4xl font-black text-slate-900 dark:text-white mb-2 uppercase tracking-tighter">Test yourself with MyClassroom</h1>
                    <p className="text-slate-500 mb-10 text-lg">— your own trusted app —</p>

                    <div className="w-full max-w-xl space-y-4">
                        <div className="relative group">
                            <Search className="absolute left-6 top-6 text-slate-400 w-6 h-6 group-focus-within:text-indigo-600 transition-colors" />
                            <input 
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                placeholder="Search for your examination..."
                                className="w-full pl-16 p-6 bg-white dark:bg-slate-900 rounded-[2rem] shadow-xl border-none text-xl dark:text-white outline-none focus:ring-4 focus:ring-indigo-500/10"
                            />
                        </div>

                        <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl max-h-[350px] overflow-y-auto p-4 border border-slate-100 dark:border-slate-800 scrollbar-hide">
                            {filteredExams.length > 0 ? filteredExams.map(exam => (
                                <button 
                                    key={exam}
                                    onClick={() => { setSelectedExam(exam); setPhase('VERIFY_APP'); }}
                                    className="w-full text-left p-6 rounded-2xl hover:bg-indigo-50 dark:hover:bg-indigo-900/30 transition-all flex items-center justify-between group"
                                >
                                    <span className="font-bold dark:text-slate-200 group-hover:text-indigo-600">{exam}</span>
                                    <ChevronRight className="w-5 h-5 text-slate-300 group-hover:translate-x-1 transition-transform" />
                                </button>
                            )) : <p className="p-8 text-slate-400 italic">No exams found matching your search.</p>}
                        </div>
                    </div>
                </div>
            )}

            {/* APP VERIFICATION */}
            {phase === 'VERIFY_APP' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-md bg-white dark:bg-slate-900 p-10 rounded-2xl shadow-2xl border border-slate-100 dark:border-slate-800 text-center">
                        <h2 className="text-2xl font-black mb-1 text-slate-900 dark:text-white leading-tight">{selectedExam}</h2>
                        <p className="text-slate-400 text-xs font-semibold uppercase tracking-widest mb-10 opacity-70">Candidate Verification Required</p>

                        <div className="text-left mb-8">
                            <label className="block text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em] mb-2 ml-1">
                                Application Number
                            </label>
                            <div className="relative group">
                                <Hash className="absolute left-4 top-4 text-slate-300 w-5 h-5 group-focus-within:text-indigo-500 transition-colors" />
                                <input 
                                    value={appNumber}
                                    onChange={e => { 
                                        const val = e.target.value.toUpperCase().replace(/\s/g, '');
                                        setAppNumber(val); 
                                        setIsAppVerified(false); 
                                    }}
                                    onPaste={e => e.preventDefault()}
                                    placeholder="Enter your application number"
                                    className="w-full pl-12 p-4 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 text-lg font-black tracking-widest text-slate-900 dark:text-white outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                />
                            </div>
                        </div>

                        {isVerifying ? (
                            <div className="h-14 flex items-center justify-center gap-3 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 rounded-xl font-black">
                                <Loader2 className="w-5 h-5 animate-spin" />
                                <span>VERIFYING...</span>
                            </div>
                        ) : isAppVerified ? (
                            <div className="p-4 bg-green-50 dark:bg-green-900/10 border border-green-100 dark:border-green-800/30 rounded-xl flex flex-col items-center animate-scale-in">
                                <div className="w-10 h-10 bg-green-100 dark:bg-green-800/40 rounded-full flex items-center justify-center mb-2">
                                    <CheckCircle className="w-6 h-6 text-green-600" />
                                </div>
                                <span className="text-green-600 font-bold text-sm tracking-tight italic">✔ Application number verified successfully</span>
                            </div>
                        ) : (
                            <button 
                                onClick={handleVerifyApp} 
                                disabled={!appNumber}
                                className="w-full h-14 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-black text-lg shadow-lg shadow-indigo-600/20 transition-all active:scale-95 disabled:opacity-50 disabled:grayscale"
                            >
                                Verify & Continue
                            </button>
                        )}

                        <button 
                            onClick={() => setPhase('WELCOME')} 
                            className="mt-8 text-slate-400 hover:text-indigo-600 text-[10px] font-black uppercase tracking-widest transition-colors flex items-center justify-center gap-2 mx-auto"
                        >
                            <ChevronLeft className="w-3 h-3" /> Choose a different exam
                        </button>
                    </div>
                </div>
            )}

            {/* IDENTITY CAPTURE */}
            {phase === 'IDENTITY_CAPTURE' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-4xl bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-2xl text-center">
                        <h2 className="text-3xl font-black mb-2 dark:text-white uppercase tracking-tighter">Identity Verification</h2>
                        <p className="text-slate-500 mb-8">Please capture three clear views of your face.</p>

                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 items-center">
                            <div className="relative aspect-video bg-black rounded-[2rem] overflow-hidden border-4 border-slate-100 dark:border-slate-800">
                                <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover scale-x-[-1]" />
                                <div className="absolute inset-0 border-[30px] border-black/30 pointer-events-none rounded-[2rem]"></div>
                            </div>

                            <div className="grid grid-cols-3 gap-3">
                                {[
                                    { key: 'front', label: 'Front View' },
                                    { key: 'left', label: 'Left View' },
                                    { key: 'right', label: 'Right View' }
                                ].map(view => (
                                    <div key={view.key} className="space-y-2">
                                        <div className="aspect-[3/4] bg-slate-100 dark:bg-slate-800 rounded-2xl overflow-hidden relative border-2 border-slate-200 dark:border-slate-700">
                                            {(captures as any)[view.key] ? (
                                                <img src={(captures as any)[view.key]} alt={view.label} className="w-full h-full object-cover" />
                                            ) : <div className="h-full flex items-center justify-center text-slate-400 text-[10px] uppercase font-bold">{view.label}</div>}
                                        </div>
                                        <button 
                                            onClick={() => captureView(view.key as any)}
                                            className={`w-full py-2 rounded-xl text-[10px] font-black uppercase transition-all ${(captures as any)[view.key] ? 'bg-green-100 text-green-700' : 'bg-indigo-600 text-white shadow-lg'}`}
                                        >
                                            {(captures as any)[view.key] ? 'Retake' : `Snap ${view.key}`}
                                        </button>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <button 
                            disabled={!captures.front || !captures.left || !captures.right}
                            onClick={runIdentityMatch}
                            className="mt-10 w-full py-6 bg-indigo-600 hover:bg-indigo-700 text-white rounded-[2.5rem] font-black text-xl shadow-2xl disabled:opacity-30 disabled:grayscale transition-all"
                        >
                            Verify & Match Identity
                        </button>
                    </div>
                </div>
            )}

            {/* MATCHING PHASE */}
            {phase === 'MATCHING' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in text-center">
                    {matchingStatus === 'processing' ? (
                        <>
                            <div className="relative w-32 h-32 mb-8">
                                <div className="absolute inset-0 border-8 border-slate-100 dark:border-slate-800 rounded-full"></div>
                                <div className="absolute inset-0 border-8 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                                <UserCheck className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 text-indigo-600" />
                            </div>
                            <h2 className="text-3xl font-black dark:text-white uppercase tracking-tighter">Comparing Biometrics</h2>
                            <p className="text-slate-500 animate-pulse">Running neural match with registry photo...</p>
                        </>
                    ) : (
                        <div className="animate-scale-in">
                            <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                                <CheckCircle className="w-12 h-12 text-green-600" />
                            </div>
                            <h2 className="text-3xl font-black text-green-600 uppercase tracking-tighter">Face Match Successful</h2>
                            <p className="text-slate-500">Identity verified against application records.</p>
                        </div>
                    )}
                </div>
            )}

            {/* INSTRUCTIONS */}
            {phase === 'INSTRUCTIONS' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-2xl bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-2xl border-t-8 border-indigo-600">
                        <h2 className="text-4xl font-black mb-6 dark:text-white uppercase tracking-tighter">Exam Rules & Permissions</h2>
                        <div className="space-y-4 mb-10">
                            {[
                                { icon: Monitor, label: "Full-screen mode is mandatory." },
                                { icon: Camera, label: "Continuous camera monitoring by AI." },
                                { icon: Mic, label: "Microphone must remain active." },
                                { icon: Laptop, label: "Keyboard is locked. Mouse interaction only." },
                                { icon: ShieldAlert, label: "Strict AI invigilation enforced." }
                            ].map((rule, i) => (
                                <div key={i} className="flex items-center gap-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl">
                                    <rule.icon className="w-6 h-6 text-indigo-600" />
                                    <span className="font-bold text-slate-700 dark:text-slate-200">{rule.label}</span>
                                </div>
                            ))}
                        </div>
                        <button onClick={startTest} className="w-full py-6 bg-indigo-600 hover:bg-indigo-700 text-white rounded-[2rem] font-black text-2xl shadow-2xl flex items-center justify-center gap-3">
                            <Play className="w-6 h-6 fill-current" /> Start Examination
                        </button>
                    </div>
                </div>
            )}

            {/* ARENA PHASE */}
            {phase === 'ARENA' && (
                <div className="flex-1 flex flex-col lg:flex-row gap-6 p-6 animate-fade-in overflow-hidden relative select-none">
                    {/* RED ALERT BANNER IF WARNINGS PRESENT */}
                    {aiWarning && (
                        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-red-600 text-white px-10 py-5 rounded-[2rem] shadow-2xl animate-bounce font-black uppercase text-sm border-4 border-white flex items-center gap-4">
                            <AlertTriangle className="w-8 h-8" /> {aiWarning}
                        </div>
                    )}

                    <div className="w-full lg:w-72 flex flex-col gap-4">
                        <div className="bg-black rounded-[2rem] aspect-video overflow-hidden border-2 border-red-600 relative shadow-2xl">
                            <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover scale-x-[-1]" />
                            <div className="absolute top-3 left-3 flex items-center gap-2 bg-black/50 backdrop-blur-md px-2 py-1 rounded-full text-[8px] font-black text-white">
                                <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-pulse"></div> AI INVIGILATOR LIVE
                            </div>
                        </div>

                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800">
                             <div className="flex justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">
                                <span>Integrity Meter</span>
                                <span className="text-red-600">{warnings}/5 Flags</span>
                             </div>
                             <div className="flex gap-1.5">
                                {[1,2,3,4,5].map(i => <div key={i} className={`h-2 flex-1 rounded-full transition-all duration-700 ${i <= warnings ? 'bg-red-600 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.5)]' : 'bg-slate-100 dark:bg-slate-800'}`}></div>)}
                             </div>
                             <p className="mt-4 text-[10px] text-slate-400 font-bold uppercase flex items-center gap-2"><Laptop className="w-3 h-3"/> Keypad Locked</p>
                        </div>

                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800 flex-1">
                            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2"><Activity className="w-4 h-4 text-indigo-500" /> Exam Progress</h4>
                            <div className="grid grid-cols-4 gap-2">
                                {MOCK_QUESTIONS.map((_, i) => (
                                    <button 
                                        key={i} 
                                        onClick={() => setCurrentQIdx(i)}
                                        className={`aspect-square rounded-xl font-black text-xs transition-all ${currentQIdx === i ? 'bg-indigo-600 text-white shadow-lg' : answers[MOCK_QUESTIONS[i].id] ? 'bg-green-100 text-green-700' : 'bg-slate-50 dark:bg-slate-800 text-slate-400'}`}
                                    >
                                        {i + 1}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    <div className="flex-1 flex flex-col gap-6 overflow-hidden">
                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800 flex justify-between items-center">
                            <div>
                                <h3 className="text-xl font-black dark:text-white line-clamp-1">{selectedExam}</h3>
                                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Application: {appNumber}</p>
                            </div>
                            <div className="flex items-center gap-4 bg-red-50 dark:bg-red-900/30 px-8 py-3 rounded-2xl border border-red-100 dark:border-red-900/20 shadow-inner">
                                <Clock className="w-6 h-6 text-red-600 animate-pulse" />
                                <span className="text-3xl font-mono font-black text-red-600 tabular-nums">
                                    {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
                                </span>
                            </div>
                        </div>

                        <div className="flex-1 bg-white dark:bg-slate-900 p-12 rounded-[3.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 overflow-y-auto flex flex-col group relative">
                            <div className="flex-1">
                                <div className="flex gap-6 mb-12">
                                    <span className="text-8xl font-black text-indigo-600/5 select-none leading-none -mt-3">{currentQIdx + 1}</span>
                                    <h2 className="text-3xl font-black dark:text-white leading-tight">{MOCK_QUESTIONS[currentQIdx].text}</h2>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-4xl">
                                    {MOCK_QUESTIONS[currentQIdx].options?.map((opt, oIdx) => (
                                        <button 
                                            key={oIdx} 
                                            onClick={() => setAnswers({...answers, [MOCK_QUESTIONS[currentQIdx].id]: opt})}
                                            className={`w-full text-left p-8 rounded-[2rem] border-4 transition-all flex items-center gap-6 group relative overflow-hidden ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/20 ring-8 ring-indigo-600/5' : 'border-slate-50 dark:border-slate-800/50 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
                                        >
                                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-lg flex-shrink-0 transition-all ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'bg-indigo-600 text-white scale-110 shadow-lg' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 group-hover:bg-indigo-100 group-hover:text-indigo-600'}`}>{String.fromCharCode(65 + oIdx)}</div>
                                            <span className={`text-lg font-bold ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'text-indigo-900 dark:text-white' : 'text-slate-600 dark:text-slate-300'}`}>{opt}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div className="mt-12 flex justify-between items-center border-t-2 border-slate-50 dark:border-slate-800 pt-10">
                                <button disabled={currentQIdx === 0} onClick={() => setCurrentQIdx(currentQIdx - 1)} className="p-5 bg-slate-100 dark:bg-slate-800 rounded-2xl font-black text-slate-400 hover:text-black dark:hover:text-white disabled:opacity-10 transition-all"><ChevronLeft className="w-8 h-8" /></button>

                                <div className="flex gap-4">
                                    {currentQIdx === MOCK_QUESTIONS.length - 1 ? (
                                        <button onClick={finalizeTest} className="px-12 bg-green-600 text-white font-black text-xl rounded-[2rem] shadow-xl hover:bg-green-700 transition-all active:scale-95">Finish Session</button>
                                    ) : (
                                        <button onClick={() => setCurrentQIdx(currentQIdx + 1)} className="px-10 bg-indigo-600 text-white rounded-[2rem] shadow-xl hover:bg-indigo-700 transition-all active:scale-95"><ChevronRight className="w-8 h-8" /></button>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* BLOCKED PHASE */}
            {phase === 'BLOCKED' && (
                <div className="flex-1 flex flex-col items-center justify-center p-8 text-center animate-fade-in">
                    <div className="w-24 h-24 bg-red-100 rounded-[2rem] flex items-center justify-center mb-8 animate-bounce">
                        <AlertTriangle className="w-12 h-12 text-red-600" />
                    </div>
                    <h2 className="text-4xl font-black text-red-600 uppercase tracking-tighter mb-4">Session Terminated</h2>
                    <p className="text-slate-500 max-w-md mb-10 leading-relaxed font-bold">
                        Security breach detected. Full-screen exit or excessive AI behavioral flags have resulted in immediate termination of this assessment.
                    </p>
                    <button onClick={() => window.location.reload()} className="px-10 py-5 bg-red-600 text-white rounded-[2rem] font-black text-xl hover:bg-red-700 shadow-2xl transition-all">Exit Portal</button>
                </div>
            )}

            {/* SUBMITTING */}
            {phase === 'SUBMITTING' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in text-center">
                    <Loader2 className="w-16 h-16 text-indigo-600 animate-spin mb-8" />
                    <h2 className="text-4xl font-black dark:text-white uppercase tracking-tighter">Finalizing Response</h2>
                    <p className="text-slate-500">Encrypting behavioral logs and indexing MCQ data...</p>
                </div>
            )}

            {/* RESULT */}
            {phase === 'RESULT' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-2xl bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-2xl border-t-8 border-indigo-600 text-center relative overflow-hidden">
                        <div className="absolute top-0 right-0 p-12 opacity-5"><Shield className="w-48 h-48" /></div>
                        <div className="w-20 h-20 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6"><Trophy className="w-10 h-10 text-green-600" /></div>
                        <h2 className="text-5xl font-black dark:text-white mb-2 uppercase tracking-tighter">Test Completed</h2>
                        <p className="text-slate-500 text-lg mb-12">Your responses for <span className="font-bold text-indigo-600">{selectedExam}</span> have been submitted.</p>

                        <div className="grid grid-cols-2 gap-6 mb-12">
                            <div className="p-8 bg-slate-50 dark:bg-slate-800 rounded-[2.5rem] border border-slate-100 dark:border-slate-700">
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Score Result</p>
                                <p className="text-5xl font-black dark:text-white">{Object.keys(answers).length} / {MOCK_QUESTIONS.length}</p>
                            </div>
                            <div className="p-8 bg-slate-50 dark:bg-slate-800 rounded-[2.5rem] border border-slate-100 dark:border-slate-700">
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">AI Integrity Score</p>
                                <p className={`text-5xl font-black ${warnings === 0 ? 'text-green-600' : 'text-orange-500'}`}>{100 - (warnings * 20)}%</p>
                            </div>
                        </div>

                        <button onClick={() => window.location.reload()} className="w-full py-6 bg-indigo-600 text-white rounded-[2.5rem] font-black text-xl hover:bg-indigo-700 shadow-xl transition-all active:scale-95">Return Home</button>
                    </div>
                </div>
            )}

        </div>
    );
};

export default ExaminationCenter;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeProctoringFrame } from '../services/gemini';
import { TestResult, QuestionType, Question, User } from '../types';
import { 
    Play, ShieldCheck, Hash, CheckCircle, Camera, Activity, 
    Clock, ShieldAlert, ChevronRight, ChevronLeft, 
    Shield, UserCheck, Mic, Laptop, Search, Loader2, AlertTriangle, 
    Trophy, Monitor, LogOut
} from 'lucide-react';
import confetti from 'canvas-confetti';

// --- CONSTANTS ---
const EXAM_LIST = [
    "NISM (Capital Markets)", "NCFM", "Graduate Record Examinations (GRE)", 
    "Test of English as a Foreign Language (TOEFL iBT)", "Graduate Management Admission Test (GMAT)", 
    "International English Language Testing System (IELTS)", "Microsoft Certification Exams", 
    "Amazon Web Services (AWS) Certification", "Cisco Certification Exams (CCNA)", 
    "Cisco Certification Exams (CCNP)", "Test of Professional Skills (TOPS) & Other Corporate Hiring Tests", 
    "Certifications by Google (Google Career Certificates)"
];

const MOCK_QUESTIONS: Question[] = [
    { id: 1, text: "In a stock market context, what does IPO stand for?", type: QuestionType.MCQ, options: ["Internal Profit Option", "Initial Public Offering", "International Payment Order", "Investment Portfolio Overhaul"], correctAnswer: "Initial Public Offering", difficulty: "Easy", explanation: "IPO is the first time a company sells stock to the public.", marks: 2 },
    { id: 2, text: "Which protocol is primarily used for secure communication over a computer network?", type: QuestionType.MCQ, options: ["HTTP", "FTP", "HTTPS", "SMTP"], correctAnswer: "HTTPS", difficulty: "Medium", explanation: "HTTPS encrypts communication between a browser and a server.", marks: 2 },
    { id: 3, text: "What is the primary function of a router in a network?", type: QuestionType.MCQ, options: ["To store data", "To route packets between networks", "To provide power to devices", "To display web pages"], correctAnswer: "To route packets between networks", difficulty: "Medium", explanation: "Routers forward data packets across network boundaries.", marks: 2 },
    { id: 4, text: "Cloud computing 'AWS' stands for what?", type: QuestionType.MCQ, options: ["Advanced Web Systems", "Amazon Web Services", "Apple Web Software", "Apex Wireless Solutions"], correctAnswer: "Amazon Web Services", difficulty: "Easy", explanation: "AWS is Amazon's cloud platform.", marks: 2 },
    { id: 5, text: "What is the standard port for SSH?", type: QuestionType.MCQ, options: ["21", "22", "80", "443"], correctAnswer: "22", difficulty: "Hard", explanation: "SSH typically uses port 22.", marks: 2 }
];

type PortalPhase = 'WELCOME' | 'VERIFY_APP' | 'IDENTITY_CAPTURE' | 'MATCHING' | 'INSTRUCTIONS' | 'ARENA' | 'SUBMITTING' | 'RESULT' | 'BLOCKED';

interface ExaminationCenterProps {
    user: User;
    onSaveResult: (result: TestResult) => void;
    onLogout: () => void; 
    globalTests?: any;
    onAddTest?: any;
}

const ExaminationCenter: React.FC<ExaminationCenterProps> = ({ user, onSaveResult, onLogout }) => {
    const [phase, setPhase] = useState<PortalPhase>('WELCOME');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedExam, setSelectedExam] = useState('');
    const [appNumber, setAppNumber] = useState('');
    const [isAppVerified, setIsAppVerified] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);

    // Identity State
    const [captures, setCaptures] = useState<{ front: string | null; left: string | null; right: string | null }>({ front: null, left: null, right: null });
    const [matchingStatus, setMatchingStatus] = useState<'idle' | 'processing' | 'matched' | 'failed'>('idle');

    // Exam Arena State
    const [currentQIdx, setCurrentQIdx] = useState(0);
    const [answers, setAnswers] = useState<Record<number, string>>({});
    const [timeLeft, setTimeLeft] = useState(600); // 10 mins
    const [warnings, setWarnings] = useState(0);
    const [proctorStatus, setProctorStatus] = useState('Monitoring');
    const [aiWarning, setAiWarning] = useState<string | null>(null);

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const lastViolationRef = useRef<number>(0);

    // Filtered Exams
    const filteredExams = EXAM_LIST.filter(e => e.toLowerCase().includes(searchTerm.toLowerCase()));

    // --- KEYBOARD LOCKDOWN ---
    useEffect(() => {
        if (phase === 'ARENA') {
            const blockKeys = (e: KeyboardEvent) => {
                e.preventDefault();
                setAiWarning("KEYBOARD INPUT DETECTED: Mouse Use Only.");
                setTimeout(() => setAiWarning(null), 3000);
            };
            window.addEventListener('keydown', blockKeys);
            return () => window.removeEventListener('keydown', blockKeys);
        }
    }, [phase]);

    // --- FULLSCREEN ENFORCEMENT ---
    useEffect(() => {
        const handleFS = () => {
            if (!document.fullscreenElement && phase === 'ARENA') {
                setPhase('BLOCKED');
            }
        };
        document.addEventListener('fullscreenchange', handleFS);
        return () => document.removeEventListener('fullscreenchange', handleFS);
    }, [phase]);

    // --- PROCTORING AGENT ---
    useEffect(() => {
        let visionInterval: any;
        if (phase === 'ARENA' && streamRef.current) {
            visionInterval = setInterval(async () => {
                if (!videoRef.current) return;
                const canvas = document.createElement('canvas');
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;
                ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                setProctorStatus('Scanning behavior...');
                try {
                    const res = await analyzeProctoringFrame(base64);
                    if (res.suspicious) {
                        triggerViolation(res.reason);
                    } else {
                        setAiWarning(null);
                    }
                } catch (e) {}
                setProctorStatus('Active AI Monitoring');
            }, 8000);
        }
        return () => clearInterval(visionInterval);
    }, [phase]);

    const triggerViolation = (reason: string) => {
        if (Date.now() - lastViolationRef.current < 4000) return;
        lastViolationRef.current = Date.now();

        setWarnings(prev => {
            const next = prev + 1;
            setAiWarning(`Please look straight at the screen. This is warning #${next}.`);
            if (next >= 5) setPhase('BLOCKED');
            return next;
        });
    };

    // --- CAMERA ACCESS ---
    const startCamera = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
            streamRef.current = stream;
            if (videoRef.current) videoRef.current.srcObject = stream;
        } catch (e) {
            alert("Camera access is mandatory to enter the hall.");
        }
    };

    // --- HANDLERS ---
    const handleVerifyApp = () => {
        if (!appNumber.trim()) {
            alert("Please enter your application number.");
            return;
        }

        setIsVerifying(true);
        // Requirement: Allow any application number
        setTimeout(() => {
            setIsVerifying(false);
            setIsAppVerified(true);
            // Wait to show success feedback
            setTimeout(() => {
                setPhase('IDENTITY_CAPTURE');
                startCamera();
            }, 1200);
        }, 1500);
    };

    const captureView = (view: 'front' | 'left' | 'right') => {
        if (!videoRef.current) return;
        const canvas = document.createElement('canvas');
        canvas.width = 640; canvas.height = 480;
        canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0);
        setCaptures(prev => ({ ...prev, [view]: canvas.toDataURL('image/jpeg') }));
    };

    const runIdentityMatch = () => {
        setPhase('MATCHING');
        setMatchingStatus('processing');
        setTimeout(() => {
            setMatchingStatus('matched');
            setTimeout(() => setPhase('INSTRUCTIONS'), 1500);
        }, 3000);
    };

    const startTest = () => {
        document.documentElement.requestFullscreen().then(() => {
            setPhase('ARENA');
        }).catch(() => alert("Full-screen required."));
    };

    const finalizeTest = () => {
        setPhase('SUBMITTING');
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());

        // Requirement: "as soon as the test the person redirect to the main screen"
        setTimeout(() => {
            onLogout(); // Redirect to login/main screen
        }, 2500);
    };

    useEffect(() => {
        let t: any;
        if (phase === 'ARENA' && timeLeft > 0) t = setInterval(() => setTimeLeft(p => p - 1), 1000);
        else if (phase === 'ARENA' && timeLeft === 0) finalizeTest();
        return () => clearInterval(t);
    }, [phase, timeLeft]);

    return (
        <div className="min-h-[calc(100vh)] bg-slate-50 dark:bg-slate-950 flex flex-col font-sans transition-colors duration-500 relative">

            {/* PORTAL HEADER */}
            <header className="sticky top-0 z-[100] w-full bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 px-8 py-4 flex justify-between items-center shadow-sm">
                <div className="flex items-center gap-2">
                    <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-indigo-600/20 shadow-lg">
                        <ShieldCheck className="w-5 h-5 text-white" />
                    </div>
                    <span className="text-xl font-black bg-gradient-to-r from-indigo-600 to-purple-600 bg-clip-text text-transparent">
                        MyClassroom
                    </span>
                    <span className="ml-3 px-2 py-0.5 bg-slate-100 dark:bg-slate-800 rounded text-[10px] font-black text-slate-500 uppercase tracking-widest border border-slate-200 dark:border-slate-700">
                        Exam Mode
                    </span>
                </div>

                <button 
                    onClick={onLogout}
                    className="flex items-center gap-2 px-4 py-2 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 border border-red-200 dark:border-red-800 rounded-xl font-bold text-sm hover:bg-red-100 transition-all shadow-sm active:scale-95 group"
                >
                    <LogOut className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                    Log Out
                </button>
            </header>

            {/* WELCOME PHASE */}
            {phase === 'WELCOME' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in text-center">
                    <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center mb-8 shadow-2xl animate-pulse">
                        <ShieldCheck className="w-10 h-10 text-white" />
                    </div>
                    <h1 className="text-4xl font-black text-slate-900 dark:text-white mb-2 uppercase tracking-tighter">Test yourself with MyClassroom</h1>
                    <p className="text-slate-500 mb-10 text-lg">— your own trusted app —</p>

                    <div className="w-full max-w-xl space-y-4">
                        <div className="relative group">
                            <Search className="absolute left-6 top-6 text-slate-400 w-6 h-6 group-focus-within:text-indigo-600 transition-colors" />
                            <input 
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                placeholder="Search for your examination..."
                                className="w-full pl-16 p-6 bg-white dark:bg-slate-900 rounded-[2rem] shadow-xl border-none text-xl dark:text-white outline-none focus:ring-4 focus:ring-indigo-500/10"
                            />
                        </div>

                        <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl max-h-[350px] overflow-y-auto p-4 border border-slate-100 dark:border-slate-800 scrollbar-hide">
                            {filteredExams.length > 0 ? filteredExams.map(exam => (
                                <button 
                                    key={exam}
                                    onClick={() => { setSelectedExam(exam); setPhase('VERIFY_APP'); }}
                                    className="w-full text-left p-6 rounded-2xl hover:bg-indigo-50 dark:hover:bg-indigo-900/30 transition-all flex items-center justify-between group"
                                >
                                    <span className="font-bold dark:text-slate-200 group-hover:text-indigo-600">{exam}</span>
                                    <ChevronRight className="w-5 h-5 text-slate-300 group-hover:translate-x-1 transition-transform" />
                                </button>
                            )) : <p className="p-8 text-slate-400 italic">No exams found matching your search.</p>}
                        </div>
                    </div>
                </div>
            )}

            {/* VERIFY APP PHASE */}
            {phase === 'VERIFY_APP' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-md bg-white dark:bg-slate-900 p-10 rounded-2xl shadow-2xl border border-slate-100 dark:border-slate-800 text-center flex flex-col">
                        <h2 className="text-3xl font-black mb-1 text-slate-900 dark:text-white leading-tight">{selectedExam}</h2>
                        <p className="text-slate-400 text-xs font-semibold uppercase tracking-widest mb-10 opacity-70">Candidate Verification Required</p>

                        <div className="text-left mb-8">
                            <label className="block text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em] mb-2 ml-1">
                                Application Number
                            </label>
                            <div className="relative group">
                                <Hash className="absolute left-4 top-4 text-slate-300 w-5 h-5 group-focus-within:text-indigo-500 transition-colors" />
                                <input 
                                    value={appNumber}
                                    onChange={e => { 
                                        const val = e.target.value.toUpperCase().replace(/\s/g, '');
                                        setAppNumber(val); 
                                        setIsAppVerified(false); 
                                    }}
                                    onPaste={e => e.preventDefault()}
                                    onCopy={e => e.preventDefault()}
                                    placeholder="Enter your application number"
                                    className="w-full pl-12 p-4 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 text-lg font-black tracking-widest text-slate-900 dark:text-white outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                />
                            </div>
                        </div>

                        {isVerifying ? (
                            <div className="h-14 flex items-center justify-center gap-3 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 rounded-xl font-black">
                                <Loader2 className="w-5 h-5 animate-spin" />
                                <span>VERIFYING...</span>
                            </div>
                        ) : isAppVerified ? (
                            <div className="p-4 bg-green-50 dark:bg-green-900/10 border border-green-100 dark:border-green-800/30 rounded-xl flex flex-col items-center animate-scale-in">
                                <div className="w-10 h-10 bg-green-100 dark:bg-green-800/40 rounded-full flex items-center justify-center mb-2">
                                    <CheckCircle className="w-6 h-6 text-green-600" />
                                </div>
                                <span className="text-green-600 font-bold text-sm tracking-tight italic">✔ Application number verified successfully</span>
                            </div>
                        ) : (
                            <button 
                                onClick={handleVerifyApp} 
                                disabled={!appNumber}
                                className="w-full h-14 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-black text-lg shadow-lg shadow-indigo-600/20 transition-all active:scale-95 disabled:opacity-50 disabled:grayscale"
                            >
                                Verify & Continue
                            </button>
                        )}

                        <button 
                            onClick={() => setPhase('WELCOME')} 
                            className="mt-8 text-slate-400 hover:text-indigo-600 text-[10px] font-black uppercase tracking-widest transition-colors flex items-center justify-center gap-2 mx-auto"
                        >
                            <ChevronLeft className="w-3 h-3" /> Choose a different exam
                        </button>
                    </div>
                </div>
            )}

            {/* IDENTITY CAPTURE PHASE */}
            {phase === 'IDENTITY_CAPTURE' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-4xl bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-2xl text-center">
                        <h2 className="text-3xl font-black mb-2 dark:text-white uppercase tracking-tighter">Identity Verification</h2>
                        <p className="text-slate-500 mb-8">Please capture three clear views of your face.</p>

                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 items-center">
                            <div className="relative aspect-video bg-black rounded-[2rem] overflow-hidden border-4 border-slate-100 dark:border-slate-800">
                                <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover scale-x-[-1]" />
                                <div className="absolute inset-0 border-[30px] border-black/30 pointer-events-none rounded-[2rem]"></div>
                            </div>

                            <div className="grid grid-cols-3 gap-3">
                                {[
                                    { key: 'front', label: 'Front View' },
                                    { key: 'left', label: 'Left View' },
                                    { key: 'right', label: 'Right View' }
                                ].map(view => (
                                    <div key={view.key} className="space-y-2">
                                        <div className="aspect-[3/4] bg-slate-100 dark:bg-slate-800 rounded-2xl overflow-hidden relative border-2 border-slate-200 dark:border-slate-700">
                                            {(captures as any)[view.key] ? (
                                                <img src={(captures as any)[view.key]} alt={view.label} className="w-full h-full object-cover" />
                                            ) : <div className="h-full flex items-center justify-center text-slate-400 text-[10px] uppercase font-bold">{view.label}</div>}
                                        </div>
                                        <button 
                                            onClick={() => captureView(view.key as any)}
                                            className={`w-full py-2 rounded-xl text-[10px] font-black uppercase transition-all ${(captures as any)[view.key] ? 'bg-green-100 text-green-700' : 'bg-indigo-600 text-white shadow-lg'}`}
                                        >
                                            {(captures as any)[view.key] ? 'Retake' : `Snap ${view.key}`}
                                        </button>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <button 
                            disabled={!captures.front || !captures.left || !captures.right}
                            onClick={runIdentityMatch}
                            className="mt-10 w-full py-6 bg-indigo-600 hover:bg-indigo-700 text-white rounded-[2.5rem] font-black text-xl shadow-2xl disabled:opacity-30 disabled:grayscale transition-all"
                        >
                            Verify & Match Identity
                        </button>
                    </div>
                </div>
            )}

            {/* MATCHING PHASE */}
            {phase === 'MATCHING' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in text-center">
                    {matchingStatus === 'processing' ? (
                        <>
                            <div className="relative w-32 h-32 mb-8">
                                <div className="absolute inset-0 border-8 border-slate-100 dark:border-slate-800 rounded-full"></div>
                                <div className="absolute inset-0 border-8 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                                <UserCheck className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 text-indigo-600" />
                            </div>
                            <h2 className="text-3xl font-black dark:text-white uppercase tracking-tighter">Comparing Biometrics</h2>
                            <p className="text-slate-500 animate-pulse">Running neural match with registry photo...</p>
                        </>
                    ) : (
                        <div className="animate-scale-in">
                            <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                                <CheckCircle className="w-12 h-12 text-green-600" />
                            </div>
                            <h2 className="text-3xl font-black text-green-600 uppercase tracking-tighter">Face Match Successful</h2>
                            <p className="text-slate-500">Identity verified against application records.</p>
                        </div>
                    )}
                </div>
            )}

            {/* INSTRUCTIONS PHASE */}
            {phase === 'INSTRUCTIONS' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-2xl bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-2xl border-t-8 border-indigo-600">
                        <h2 className="text-4xl font-black mb-6 dark:text-white uppercase tracking-tighter">Exam Rules & Permissions</h2>
                        <div className="space-y-4 mb-10">
                            {[
                                { icon: Monitor, label: "Full-screen mode is mandatory." },
                                { icon: Camera, label: "Continuous camera monitoring by AI." },
                                { icon: Mic, label: "Microphone must remain active." },
                                { icon: Laptop, label: "Keyboard is locked. Mouse interaction only." },
                                { icon: ShieldAlert, label: "Strict AI invigilation enforced." }
                            ].map((rule, i) => (
                                <div key={i} className="flex items-center gap-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl">
                                    <rule.icon className="w-6 h-6 text-indigo-600" />
                                    <span className="font-bold text-slate-700 dark:text-slate-200">{rule.label}</span>
                                </div>
                            ))}
                        </div>
                        <button onClick={startTest} className="w-full py-6 bg-indigo-600 hover:bg-indigo-700 text-white rounded-[2rem] font-black text-2xl shadow-2xl flex items-center justify-center gap-3">
                            <Play className="w-6 h-6 fill-current" /> Start Examination
                        </button>
                    </div>
                </div>
            )}

            {/* ARENA PHASE */}
            {phase === 'ARENA' && (
                <div className="flex-1 flex flex-col lg:flex-row gap-6 p-6 animate-fade-in overflow-hidden relative select-none">
                    {aiWarning && (
                        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-red-600 text-white px-10 py-5 rounded-[2rem] shadow-2xl animate-bounce font-black uppercase text-sm border-4 border-white flex items-center gap-4">
                            <AlertTriangle className="w-8 h-8" /> {aiWarning}
                        </div>
                    )}

                    <div className="w-full lg:w-72 flex flex-col gap-4">
                        <div className="bg-black rounded-[2rem] aspect-video overflow-hidden border-2 border-red-600 relative shadow-2xl">
                            <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover scale-x-[-1]" />
                            <div className="absolute top-3 left-3 flex items-center gap-2 bg-black/50 backdrop-blur-md px-2 py-1 rounded-full text-[8px] font-black text-white">
                                <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-pulse"></div> AI INVIGILATOR LIVE
                            </div>
                        </div>

                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800">
                             <div className="flex justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">
                                <span>Integrity Meter</span>
                                <span className="text-red-600">{warnings}/5 Flags</span>
                             </div>
                             <div className="flex gap-1.5">
                                {[1,2,3,4,5].map(i => <div key={i} className={`h-2 flex-1 rounded-full transition-all duration-700 ${i <= warnings ? 'bg-red-600 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.5)]' : 'bg-slate-100 dark:bg-slate-800'}`}></div>)}
                             </div>
                             <p className="mt-4 text-[10px] text-slate-400 font-bold uppercase flex items-center gap-2"><Laptop className="w-3 h-3"/> Keypad Locked</p>
                        </div>

                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800 flex-1">
                            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2"><Activity className="w-4 h-4 text-indigo-500" /> Exam Progress</h4>
                            <div className="grid grid-cols-4 gap-2">
                                {MOCK_QUESTIONS.map((_, i) => (
                                    <button 
                                        key={i} 
                                        onClick={() => setCurrentQIdx(i)}
                                        className={`aspect-square rounded-xl font-black text-xs transition-all ${currentQIdx === i ? 'bg-indigo-600 text-white shadow-lg' : answers[MOCK_QUESTIONS[i].id] ? 'bg-green-100 text-green-700' : 'bg-slate-50 dark:bg-slate-800 text-slate-400'}`}
                                    >
                                        {i + 1}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    <div className="flex-1 flex flex-col gap-6 overflow-hidden">
                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800 flex justify-between items-center">
                            <div>
                                <h3 className="text-xl font-black dark:text-white line-clamp-1">{selectedExam}</h3>
                                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Application: {appNumber}</p>
                            </div>
                            <div className="flex items-center gap-4 bg-red-50 dark:bg-red-900/30 px-8 py-3 rounded-2xl border border-red-100 dark:border-red-900/20 shadow-inner">
                                <Clock className="w-6 h-6 text-red-600 animate-pulse" />
                                <span className="text-3xl font-mono font-black text-red-600 tabular-nums">
                                    {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
                                </span>
                            </div>
                        </div>

                        <div className="flex-1 bg-white dark:bg-slate-900 p-12 rounded-[3.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 overflow-y-auto flex flex-col group relative">
                            <div className="flex-1">
                                <div className="flex gap-6 mb-12">
                                    <span className="text-8xl font-black text-indigo-600/5 select-none leading-none -mt-3">{currentQIdx + 1}</span>
                                    <h2 className="text-3xl font-black dark:text-white leading-tight">{MOCK_QUESTIONS[currentQIdx].text}</h2>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-4xl">
                                    {MOCK_QUESTIONS[currentQIdx].options?.map((opt, oIdx) => (
                                        <button 
                                            key={oIdx} 
                                            onClick={() => setAnswers({...answers, [MOCK_QUESTIONS[currentQIdx].id]: opt})}
                                            className={`w-full text-left p-8 rounded-[2rem] border-4 transition-all flex items-center gap-6 group relative overflow-hidden ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/20 ring-8 ring-indigo-600/5' : 'border-slate-50 dark:border-slate-800/50 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
                                        >
                                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-lg flex-shrink-0 transition-all ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'bg-indigo-600 text-white scale-110 shadow-lg' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 group-hover:bg-indigo-100 group-hover:text-indigo-600'}`}>{String.fromCharCode(65 + oIdx)}</div>
                                            <span className={`text-lg font-bold ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'text-indigo-900 dark:text-white' : 'text-slate-600 dark:text-slate-300'}`}>{opt}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div className="mt-12 flex justify-between items-center border-t-2 border-slate-50 dark:border-slate-800 pt-10">
                                <button disabled={currentQIdx === 0} onClick={() => setCurrentQIdx(currentQIdx - 1)} className="p-5 bg-slate-100 dark:bg-slate-800 rounded-2xl font-black text-slate-400 hover:text-black dark:hover:text-white disabled:opacity-10 transition-all"><ChevronLeft className="w-8 h-8" /></button>

                                <div className="flex gap-4">
                                    {currentQIdx === MOCK_QUESTIONS.length - 1 ? (
                                        <button onClick={finalizeTest} className="px-12 bg-green-600 text-white font-black text-xl rounded-[2rem] shadow-xl hover:bg-green-700 transition-all active:scale-95">Finish Session</button>
                                    ) : (
                                        <button onClick={() => setCurrentQIdx(currentQIdx + 1)} className="px-10 bg-indigo-600 text-white rounded-[2rem] shadow-xl hover:bg-indigo-700 transition-all active:scale-95"><ChevronRight className="w-8 h-8" /></button>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* SUBMITTING PHASE */}
            {phase === 'SUBMITTING' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in text-center">
                    <Loader2 className="w-16 h-16 text-indigo-600 animate-spin mb-8" />
                    <h2 className="text-4xl font-black dark:text-white uppercase tracking-tighter">Finalizing Response</h2>
                    <p className="text-slate-500">Encrypting behavioral logs and indexing MCQ data...</p>
                </div>
            )}

            {/* BLOCKED PHASE */}
            {phase === 'BLOCKED' && (
                <div className="flex-1 flex flex-col items-center justify-center p-8 text-center animate-fade-in">
                    <div className="w-24 h-24 bg-red-100 rounded-[2rem] flex items-center justify-center mb-8 animate-bounce">
                        <AlertTriangle className="w-12 h-12 text-red-600" />
                    </div>
                    <h2 className="text-4xl font-black text-red-600 uppercase tracking-tighter mb-4">Session Terminated</h2>
                    <p className="text-slate-500 max-w-md mb-10 leading-relaxed font-bold">
                        Security breach detected. Full-screen exit or excessive AI behavioral flags have resulted in immediate termination of this assessment.
                    </p>
                    <button onClick={() => window.location.reload()} className="px-10 py-5 bg-red-600 text-white rounded-[2rem] font-black text-xl hover:bg-red-700 shadow-2xl transition-all">Exit Portal</button>
                </div>
            )}

        </div>
    );
};

export default ExaminationCenter;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeProctoringFrame } from '../services/gemini';
import { TestResult, QuestionType, Question, User } from '../types';
import { 
    Play, ShieldCheck, Hash, CheckCircle, Camera, Activity, 
    Clock, ShieldAlert, ChevronRight, ChevronLeft, 
    Shield, UserCheck, Mic, Laptop, Search, Loader2, AlertTriangle, 
    Trophy, Monitor, LogOut
} from 'lucide-react';
import confetti from 'canvas-confetti';

// --- CONSTANTS ---
const EXAM_LIST = [
    "NISM (Capital Markets)", "NCFM", "Graduate Record Examinations (GRE)", 
    "Test of English as a Foreign Language (TOEFL iBT)", "Graduate Management Admission Test (GMAT)", 
    "International English Language Testing System (IELTS)", "Microsoft Certification Exams", 
    "Amazon Web Services (AWS) Certification", "Cisco Certification Exams (CCNA)", 
    "Cisco Certification Exams (CCNP)", "Test of Professional Skills (TOPS) & Other Corporate Hiring Tests", 
    "Certifications by Google (Google Career Certificates)"
];

const MOCK_QUESTIONS: Question[] = [
    { id: 1, text: "In a stock market context, what does IPO stand for?", type: QuestionType.MCQ, options: ["Internal Profit Option", "Initial Public Offering", "International Payment Order", "Investment Portfolio Overhaul"], correctAnswer: "Initial Public Offering", difficulty: "Easy", explanation: "IPO is the first time a company sells stock to the public.", marks: 2 },
    { id: 2, text: "Which protocol is primarily used for secure communication over a computer network?", type: QuestionType.MCQ, options: ["HTTP", "FTP", "HTTPS", "SMTP"], correctAnswer: "HTTPS", difficulty: "Medium", explanation: "HTTPS encrypts communication between a browser and a server.", marks: 2 },
    { id: 3, text: "What is the primary function of a router in a network?", type: QuestionType.MCQ, options: ["To store data", "To route packets between networks", "To provide power to devices", "To display web pages"], correctAnswer: "To route packets between networks", difficulty: "Medium", explanation: "Routers forward data packets across network boundaries.", marks: 2 },
    { id: 4, text: "Cloud computing 'AWS' stands for what?", type: QuestionType.MCQ, options: ["Advanced Web Systems", "Amazon Web Services", "Apple Web Software", "Apex Wireless Solutions"], correctAnswer: "Amazon Web Services", difficulty: "Easy", explanation: "AWS is Amazon's cloud platform.", marks: 2 },
    { id: 5, text: "What is the standard port for SSH?", type: QuestionType.MCQ, options: ["21", "22", "80", "443"], correctAnswer: "22", difficulty: "Hard", explanation: "SSH typically uses port 22.", marks: 2 }
];

type PortalPhase = 'WELCOME' | 'VERIFY_APP' | 'IDENTITY_CAPTURE' | 'MATCHING' | 'INSTRUCTIONS' | 'ARENA' | 'SUBMITTING' | 'RESULT' | 'BLOCKED';

interface ExaminationCenterProps {
    user: User;
    onSaveResult: (result: TestResult) => void;
    onLogout: () => void; 
    globalTests?: any;
    onAddTest?: any;
}

const ExaminationCenter: React.FC<ExaminationCenterProps> = ({ user, onSaveResult, onLogout }) => {
    const [phase, setPhase] = useState<PortalPhase>('WELCOME');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedExam, setSelectedExam] = useState('');
    const [appNumber, setAppNumber] = useState('');
    const [isAppVerified, setIsAppVerified] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);

    // Identity State
    const [captures, setCaptures] = useState<{ front: string | null; left: string | null; right: string | null }>({ front: null, left: null, right: null });
    const [matchingStatus, setMatchingStatus] = useState<'idle' | 'processing' | 'matched' | 'failed'>('idle');

    // Exam Arena State
    const [currentQIdx, setCurrentQIdx] = useState(0);
    const [answers, setAnswers] = useState<Record<number, string>>({});
    const [timeLeft, setTimeLeft] = useState(600); // 10 mins
    const [warnings, setWarnings] = useState(0);
    const [proctorStatus, setProctorStatus] = useState('Monitoring');
    const [aiWarning, setAiWarning] = useState<string | null>(null);

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const lastViolationRef = useRef<number>(0);

    // --- HARDWARE KILLSWITCH AGENT ---
    // Automatically release camera and microphone resources when not in active monitoring phases
    useEffect(() => {
        const monitoringPhases: PortalPhase[] = ['IDENTITY_CAPTURE', 'MATCHING', 'ARENA'];
        if (!monitoringPhases.includes(phase) && streamRef.current) {
            console.log("AI Agent: Test phase concluded. Terminating camera and microphone access.");
            streamRef.current.getTracks().forEach(track => {
                track.stop();
                console.log(`Track ${track.kind} disabled.`);
            });
            streamRef.current = null;
        }
    }, [phase]);

    // Cleanup on unmount
    useEffect(() => {
        return () => {
            if (streamRef.current) {
                streamRef.current.getTracks().forEach(track => track.stop());
                streamRef.current = null;
            }
        };
    }, []);

    // Filtered Exams
    const filteredExams = EXAM_LIST.filter(e => e.toLowerCase().includes(searchTerm.toLowerCase()));

    // --- KEYBOARD LOCKDOWN ---
    useEffect(() => {
        if (phase === 'ARENA') {
            const blockKeys = (e: KeyboardEvent) => {
                e.preventDefault();
                setAiWarning("KEYBOARD INPUT DETECTED: Mouse Use Only.");
                setTimeout(() => setAiWarning(null), 3000);
            };
            window.addEventListener('keydown', blockKeys);
            return () => window.removeEventListener('keydown', blockKeys);
        }
    }, [phase]);

    // --- FULLSCREEN ENFORCEMENT ---
    useEffect(() => {
        const handleFS = () => {
            if (!document.fullscreenElement && phase === 'ARENA') {
                setPhase('BLOCKED');
            }
        };
        document.addEventListener('fullscreenchange', handleFS);
        return () => document.removeEventListener('fullscreenchange', handleFS);
    }, [phase]);

    // --- PROCTORING AGENT ---
    useEffect(() => {
        let visionInterval: any;
        if (phase === 'ARENA' && streamRef.current) {
            visionInterval = setInterval(async () => {
                if (!videoRef.current) return;
                const canvas = document.createElement('canvas');
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;
                ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                setProctorStatus('Scanning behavior...');
                try {
                    const res = await analyzeProctoringFrame(base64);
                    if (res.suspicious) {
                        triggerViolation(res.reason);
                    } else {
                        setAiWarning(null);
                    }
                } catch (e) {}
                setProctorStatus('Active AI Monitoring');
            }, 8000);
        }
        return () => clearInterval(visionInterval);
    }, [phase]);

    const triggerViolation = (reason: string) => {
        if (Date.now() - lastViolationRef.current < 4000) return;
        lastViolationRef.current = Date.now();

        setWarnings(prev => {
            const next = prev + 1;
            setAiWarning(`Please look straight at the screen. This is warning #${next}.`);
            if (next >= 5) setPhase('BLOCKED');
            return next;
        });
    };

    // --- CAMERA ACCESS ---
    const startCamera = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
            streamRef.current = stream;
            if (videoRef.current) videoRef.current.srcObject = stream;
        } catch (e) {
            alert("Camera access is mandatory to enter the hall.");
        }
    };

    // --- HANDLERS ---
    const handleVerifyApp = () => {
        if (!appNumber.trim()) {
            alert("Please enter your application number.");
            return;
        }

        setIsVerifying(true);
        setTimeout(() => {
            setIsVerifying(false);
            setIsAppVerified(true);
            setTimeout(() => {
                setPhase('IDENTITY_CAPTURE');
                startCamera();
            }, 1200);
        }, 1500);
    };

    const captureView = (view: 'front' | 'left' | 'right') => {
        if (!videoRef.current) return;
        const canvas = document.createElement('canvas');
        canvas.width = 640; canvas.height = 480;
        canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0);
        setCaptures(prev => ({ ...prev, [view]: canvas.toDataURL('image/jpeg') }));
    };

    const runIdentityMatch = () => {
        setPhase('MATCHING');
        setMatchingStatus('processing');
        setTimeout(() => {
            setMatchingStatus('matched');
            setTimeout(() => setPhase('INSTRUCTIONS'), 1500);
        }, 3000);
    };

    const startTest = () => {
        document.documentElement.requestFullscreen().then(() => {
            setPhase('ARENA');
        }).catch(() => alert("Full-screen required."));
    };

    const finalizeTest = () => {
        // Immediate Phase Transition
        setPhase('SUBMITTING');

        // Immediate Hardware Shutdown
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(t => t.stop());
            streamRef.current = null;
        }

        // Redirect to main screen after a brief "Finalizing" feedback
        setTimeout(() => {
            onLogout(); 
        }, 2000);
    };

    useEffect(() => {
        let t: any;
        if (phase === 'ARENA' && timeLeft > 0) t = setInterval(() => setTimeLeft(p => p - 1), 1000);
        else if (phase === 'ARENA' && timeLeft === 0) finalizeTest();
        return () => clearInterval(t);
    }, [phase, timeLeft]);

    return (
        <div className="min-h-[calc(100vh)] bg-slate-50 dark:bg-slate-950 flex flex-col font-sans transition-colors duration-500 relative">

            {/* PORTAL HEADER */}
            <header className="sticky top-0 z-[100] w-full bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 px-8 py-4 flex justify-between items-center shadow-sm">
                <div className="flex items-center gap-2">
                    <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-indigo-600/20 shadow-lg">
                        <ShieldCheck className="w-5 h-5 text-white" />
                    </div>
                    <span className="text-xl font-black bg-gradient-to-r from-indigo-600 to-purple-600 bg-clip-text text-transparent">
                        MyClassroom
                    </span>
                    <span className="ml-3 px-2 py-0.5 bg-slate-100 dark:bg-slate-800 rounded text-[10px] font-black text-slate-500 uppercase tracking-widest border border-slate-200 dark:border-slate-700">
                        Exam Mode
                    </span>
                </div>

                <button 
                    onClick={onLogout}
                    className="flex items-center gap-2 px-4 py-2 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 border border-red-200 dark:border-red-800 rounded-xl font-bold text-sm hover:bg-red-100 transition-all shadow-sm active:scale-95 group"
                >
                    <LogOut className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                    Log Out
                </button>
            </header>

            {/* WELCOME PHASE */}
            {phase === 'WELCOME' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in text-center">
                    <div className="w-20 h-20 bg-indigo-600 rounded-[2rem] flex items-center justify-center mb-8 shadow-2xl animate-pulse">
                        <ShieldCheck className="w-10 h-10 text-white" />
                    </div>
                    <h1 className="text-4xl font-black text-slate-900 dark:text-white mb-2 uppercase tracking-tighter">Test yourself with MyClassroom</h1>
                    <p className="text-slate-500 mb-10 text-lg">— your own trusted app —</p>

                    <div className="w-full max-w-xl space-y-4">
                        <div className="relative group">
                            <Search className="absolute left-6 top-6 text-slate-400 w-6 h-6 group-focus-within:text-indigo-600 transition-colors" />
                            <input 
                                value={searchTerm}
                                onChange={e => setSearchTerm(e.target.value)}
                                placeholder="Search for your examination..."
                                className="w-full pl-16 p-6 bg-white dark:bg-slate-900 rounded-[2rem] shadow-xl border-none text-xl dark:text-white outline-none focus:ring-4 focus:ring-indigo-500/10"
                            />
                        </div>

                        <div className="bg-white dark:bg-slate-900 rounded-[2.5rem] shadow-2xl max-h-[350px] overflow-y-auto p-4 border border-slate-100 dark:border-slate-800 scrollbar-hide">
                            {filteredExams.length > 0 ? filteredExams.map(exam => (
                                <button 
                                    key={exam}
                                    onClick={() => { setSelectedExam(exam); setPhase('VERIFY_APP'); }}
                                    className="w-full text-left p-6 rounded-2xl hover:bg-indigo-50 dark:hover:bg-indigo-900/30 transition-all flex items-center justify-between group"
                                >
                                    <span className="font-bold dark:text-slate-200 group-hover:text-indigo-600">{exam}</span>
                                    <ChevronRight className="w-5 h-5 text-slate-300 group-hover:translate-x-1 transition-transform" />
                                </button>
                            )) : <p className="p-8 text-slate-400 italic">No exams found matching your search.</p>}
                        </div>
                    </div>
                </div>
            )}

            {/* VERIFY APP PHASE */}
            {phase === 'VERIFY_APP' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-md bg-white dark:bg-slate-900 p-10 rounded-2xl shadow-2xl border border-slate-100 dark:border-slate-800 text-center flex flex-col">
                        <h2 className="text-3xl font-black mb-1 text-slate-900 dark:text-white leading-tight">{selectedExam}</h2>
                        <p className="text-slate-400 text-xs font-semibold uppercase tracking-widest mb-10 opacity-70">Candidate Verification Required</p>

                        <div className="text-left mb-8">
                            <label className="block text-[10px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.2em] mb-2 ml-1">
                                Application Number
                            </label>
                            <div className="relative group">
                                <Hash className="absolute left-4 top-4 text-slate-300 w-5 h-5 group-focus-within:text-indigo-500 transition-colors" />
                                <input 
                                    value={appNumber}
                                    onChange={e => { 
                                        const val = e.target.value.toUpperCase().replace(/\s/g, '');
                                        setAppNumber(val); 
                                        setIsAppVerified(false); 
                                    }}
                                    onPaste={e => e.preventDefault()}
                                    onCopy={e => e.preventDefault()}
                                    placeholder="Enter your application number"
                                    className="w-full pl-12 p-4 bg-slate-50 dark:bg-slate-800 rounded-xl border border-slate-200 dark:border-slate-700 text-lg font-black tracking-widest text-slate-900 dark:text-white outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 transition-all placeholder:text-slate-300 dark:placeholder:text-slate-600"
                                />
                            </div>
                        </div>

                        {isVerifying ? (
                            <div className="h-14 flex items-center justify-center gap-3 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 rounded-xl font-black">
                                <Loader2 className="w-5 h-5 animate-spin" />
                                <span>VERIFYING...</span>
                            </div>
                        ) : isAppVerified ? (
                            <div className="p-4 bg-green-50 dark:bg-green-900/10 border border-green-100 dark:border-green-800/30 rounded-xl flex flex-col items-center animate-scale-in">
                                <div className="w-10 h-10 bg-green-100 dark:bg-green-800/40 rounded-full flex items-center justify-center mb-2">
                                    <CheckCircle className="w-6 h-6 text-green-600" />
                                </div>
                                <span className="text-green-600 font-bold text-sm tracking-tight italic">✔ Application number verified successfully</span>
                            </div>
                        ) : (
                            <button 
                                onClick={handleVerifyApp} 
                                disabled={!appNumber}
                                className="w-full h-14 bg-indigo-600 hover:bg-indigo-700 text-white rounded-xl font-black text-lg shadow-lg shadow-indigo-600/20 transition-all active:scale-95 disabled:opacity-50 disabled:grayscale"
                            >
                                Verify & Continue
                            </button>
                        )}

                        <button 
                            onClick={() => setPhase('WELCOME')} 
                            className="mt-8 text-slate-400 hover:text-indigo-600 text-[10px] font-black uppercase tracking-widest transition-colors flex items-center justify-center gap-2 mx-auto"
                        >
                            <ChevronLeft className="w-3 h-3" /> Choose a different exam
                        </button>
                    </div>
                </div>
            )}

            {/* IDENTITY CAPTURE PHASE */}
            {phase === 'IDENTITY_CAPTURE' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-4xl bg-white dark:bg-slate-900 p-10 rounded-[3.5rem] shadow-2xl text-center">
                        <h2 className="text-3xl font-black mb-2 dark:text-white uppercase tracking-tighter">Identity Verification</h2>
                        <p className="text-slate-500 mb-8">Please capture three clear views of your face.</p>

                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 items-center">
                            <div className="relative aspect-video bg-black rounded-[2rem] overflow-hidden border-4 border-slate-100 dark:border-slate-800">
                                <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover scale-x-[-1]" />
                                <div className="absolute inset-0 border-[30px] border-black/30 pointer-events-none rounded-[2rem]"></div>
                            </div>

                            <div className="grid grid-cols-3 gap-3">
                                {[
                                    { key: 'front', label: 'Front View' },
                                    { key: 'left', label: 'Left View' },
                                    { key: 'right', label: 'Right View' }
                                ].map(view => (
                                    <div key={view.key} className="space-y-2">
                                        <div className="aspect-[3/4] bg-slate-100 dark:bg-slate-800 rounded-2xl overflow-hidden relative border-2 border-slate-200 dark:border-slate-700">
                                            {(captures as any)[view.key] ? (
                                                <img src={(captures as any)[view.key]} alt={view.label} className="w-full h-full object-cover" />
                                            ) : <div className="h-full flex items-center justify-center text-slate-400 text-[10px] uppercase font-bold">{view.label}</div>}
                                        </div>
                                        <button 
                                            onClick={() => captureView(view.key as any)}
                                            className={`w-full py-2 rounded-xl text-[10px] font-black uppercase transition-all ${(captures as any)[view.key] ? 'bg-green-100 text-green-700' : 'bg-indigo-600 text-white shadow-lg'}`}
                                        >
                                            {(captures as any)[view.key] ? 'Retake' : `Snap ${view.key}`}
                                        </button>
                                    </div>
                                ))}
                            </div>
                        </div>

                        <button 
                            disabled={!captures.front || !captures.left || !captures.right}
                            onClick={runIdentityMatch}
                            className="mt-10 w-full py-6 bg-indigo-600 hover:bg-indigo-700 text-white rounded-[2.5rem] font-black text-xl shadow-2xl disabled:opacity-30 disabled:grayscale transition-all"
                        >
                            Verify & Match Identity
                        </button>
                    </div>
                </div>
            )}

            {/* MATCHING PHASE */}
            {phase === 'MATCHING' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in text-center">
                    {matchingStatus === 'processing' ? (
                        <>
                            <div className="relative w-32 h-32 mb-8">
                                <div className="absolute inset-0 border-8 border-slate-100 dark:border-slate-800 rounded-full"></div>
                                <div className="absolute inset-0 border-8 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
                                <UserCheck className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-10 h-10 text-indigo-600" />
                            </div>
                            <h2 className="text-3xl font-black dark:text-white uppercase tracking-tighter">Comparing Biometrics</h2>
                            <p className="text-slate-500 animate-pulse">Running neural match with registry photo...</p>
                        </>
                    ) : (
                        <div className="animate-scale-in">
                            <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mx-auto mb-6">
                                <CheckCircle className="w-12 h-12 text-green-600" />
                            </div>
                            <h2 className="text-3xl font-black text-green-600 uppercase tracking-tighter">Face Match Successful</h2>
                            <p className="text-slate-500">Identity verified against application records.</p>
                        </div>
                    )}
                </div>
            )}

            {/* INSTRUCTIONS PHASE */}
            {phase === 'INSTRUCTIONS' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in">
                    <div className="w-full max-w-2xl bg-white dark:bg-slate-900 p-12 rounded-[4rem] shadow-2xl border-t-8 border-indigo-600">
                        <h2 className="text-4xl font-black mb-6 dark:text-white uppercase tracking-tighter">Exam Rules & Permissions</h2>
                        <div className="space-y-4 mb-10">
                            {[
                                { icon: Monitor, label: "Full-screen mode is mandatory." },
                                { icon: Camera, label: "Continuous camera monitoring by AI." },
                                { icon: Mic, label: "Microphone must remain active." },
                                { icon: Laptop, label: "Keyboard is locked. Mouse interaction only." },
                                { icon: ShieldAlert, label: "Strict AI invigilation enforced." }
                            ].map((rule, i) => (
                                <div key={i} className="flex items-center gap-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-2xl">
                                    <rule.icon className="w-6 h-6 text-indigo-600" />
                                    <span className="font-bold text-slate-700 dark:text-slate-200">{rule.label}</span>
                                </div>
                            ))}
                        </div>
                        <button onClick={startTest} className="w-full py-6 bg-indigo-600 hover:bg-indigo-700 text-white rounded-[2rem] font-black text-2xl shadow-2xl flex items-center justify-center gap-3">
                            <Play className="w-6 h-6 fill-current" /> Start Examination
                        </button>
                    </div>
                </div>
            )}

            {/* ARENA PHASE */}
            {phase === 'ARENA' && (
                <div className="flex-1 flex flex-col lg:flex-row gap-6 p-6 animate-fade-in overflow-hidden relative select-none">
                    {aiWarning && (
                        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-red-600 text-white px-10 py-5 rounded-[2rem] shadow-2xl animate-bounce font-black uppercase text-sm border-4 border-white flex items-center gap-4">
                            <AlertTriangle className="w-8 h-8" /> {aiWarning}
                        </div>
                    )}

                    <div className="w-full lg:w-72 flex flex-col gap-4">
                        <div className="bg-black rounded-[2rem] aspect-video overflow-hidden border-2 border-red-600 relative shadow-2xl">
                            <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover scale-x-[-1]" />
                            <div className="absolute top-3 left-3 flex items-center gap-2 bg-black/50 backdrop-blur-md px-2 py-1 rounded-full text-[8px] font-black text-white">
                                <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-pulse"></div> AI INVIGILATOR LIVE
                            </div>
                        </div>

                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800">
                             <div className="flex justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">
                                <span>Integrity Meter</span>
                                <span className="text-red-600">{warnings}/5 Flags</span>
                             </div>
                             <div className="flex gap-1.5">
                                {[1,2,3,4,5].map(i => <div key={i} className={`h-2 flex-1 rounded-full transition-all duration-700 ${i <= warnings ? 'bg-red-600 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.5)]' : 'bg-slate-100 dark:bg-slate-800'}`}></div>)}
                             </div>
                             <p className="mt-4 text-[10px] text-slate-400 font-bold uppercase flex items-center gap-2"><Laptop className="w-3 h-3"/> Keypad Locked</p>
                        </div>

                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800 flex-1">
                            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2"><Activity className="w-4 h-4 text-indigo-500" /> Exam Progress</h4>
                            <div className="grid grid-cols-4 gap-2">
                                {MOCK_QUESTIONS.map((_, i) => (
                                    <button 
                                        key={i} 
                                        onClick={() => setCurrentQIdx(i)}
                                        className={`aspect-square rounded-xl font-black text-xs transition-all ${currentQIdx === i ? 'bg-indigo-600 text-white shadow-lg' : answers[MOCK_QUESTIONS[i].id] ? 'bg-green-100 text-green-700' : 'bg-slate-50 dark:bg-slate-800 text-slate-400'}`}
                                    >
                                        {i + 1}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    <div className="flex-1 flex flex-col gap-6 overflow-hidden">
                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800 flex justify-between items-center">
                            <div>
                                <h3 className="text-xl font-black dark:text-white line-clamp-1">{selectedExam}</h3>
                                <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Application: {appNumber}</p>
                            </div>
                            <div className="flex items-center gap-4 bg-red-50 dark:bg-red-900/30 px-8 py-3 rounded-2xl border border-red-100 dark:border-red-900/20 shadow-inner">
                                <Clock className="w-6 h-6 text-red-600 animate-pulse" />
                                <span className="text-3xl font-mono font-black text-red-600 tabular-nums">
                                    {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
                                </span>
                            </div>
                        </div>

                        <div className="flex-1 bg-white dark:bg-slate-900 p-12 rounded-[3.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 overflow-y-auto flex flex-col group relative">
                            <div className="flex-1">
                                <div className="flex gap-6 mb-12">
                                    <span className="text-8xl font-black text-indigo-600/5 select-none leading-none -mt-3">{currentQIdx + 1}</span>
                                    <h2 className="text-3xl font-black dark:text-white leading-tight">{MOCK_QUESTIONS[currentQIdx].text}</h2>
                                </div>

                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-4xl">
                                    {MOCK_QUESTIONS[currentQIdx].options?.map((opt, oIdx) => (
                                        <button 
                                            key={oIdx} 
                                            onClick={() => setAnswers({...answers, [MOCK_QUESTIONS[currentQIdx].id]: opt})}
                                            className={`w-full text-left p-8 rounded-[2rem] border-4 transition-all flex items-center gap-6 group relative overflow-hidden ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/20 ring-8 ring-indigo-600/5' : 'border-slate-50 dark:border-slate-800/50 hover:bg-slate-50 dark:hover:bg-slate-800'}`}
                                        >
                                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-lg flex-shrink-0 transition-all ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'bg-indigo-600 text-white scale-110 shadow-lg' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 group-hover:bg-indigo-100 group-hover:text-indigo-600'}`}>{String.fromCharCode(65 + oIdx)}</div>
                                            <span className={`text-lg font-bold ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'text-indigo-900 dark:text-white' : 'text-slate-600 dark:text-slate-300'}`}>{opt}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div className="mt-12 flex justify-between items-center border-t-2 border-slate-50 dark:border-slate-800 pt-10">
                                <button disabled={currentQIdx === 0} onClick={() => setCurrentQIdx(currentQIdx - 1)} className="p-5 bg-slate-100 dark:bg-slate-800 rounded-2xl font-black text-slate-400 hover:text-black dark:hover:text-white disabled:opacity-10 transition-all"><ChevronLeft className="w-8 h-8" /></button>

                                <div className="flex gap-4">
                                    {currentQIdx === MOCK_QUESTIONS.length - 1 ? (
                                        <button onClick={finalizeTest} className="px-12 bg-green-600 text-white font-black text-xl rounded-[2rem] shadow-xl hover:bg-green-700 transition-all active:scale-95">Finish Session</button>
                                    ) : (
                                        <button onClick={() => setCurrentQIdx(currentQIdx + 1)} className="px-10 bg-indigo-600 text-white rounded-[2rem] shadow-xl hover:bg-indigo-700 transition-all active:scale-95"><ChevronRight className="w-8 h-8" /></button>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* SUBMITTING PHASE */}
            {phase === 'SUBMITTING' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in text-center">
                    <Loader2 className="w-16 h-16 text-indigo-600 animate-spin mb-8" />
                    <h2 className="text-4xl font-black dark:text-white uppercase tracking-tighter">Finalizing Response</h2>
                    <p className="text-slate-500">Encrypting behavioral logs and indexing MCQ data...</p>
                </div>
            )}

            {/* BLOCKED PHASE */}
            {phase === 'BLOCKED' && (
                <div className="flex-1 flex flex-col items-center justify-center p-8 text-center animate-fade-in">
                    <div className="w-24 h-24 bg-red-100 rounded-[2rem] flex items-center justify-center mb-8 animate-bounce">
                        <AlertTriangle className="w-12 h-12 text-red-600" />
                    </div>
                    <h2 className="text-4xl font-black text-red-600 uppercase tracking-tighter mb-4">Session Terminated</h2>
                    <p className="text-slate-500 max-w-md mb-10 leading-relaxed font-bold">
                        Security breach detected. Full-screen exit or excessive AI behavioral flags have resulted in immediate termination of this assessment.
                    </p>
                    <button onClick={() => window.location.reload()} className="px-10 py-5 bg-red-600 text-white rounded-[2rem] font-black text-xl hover:bg-red-700 shadow-2xl transition-all">Exit Portal</button>
                </div>
            )}

        </div>
    );
};

export default ExaminationCenter;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeProctoringFrame } from '../services/gemini';
import { TestResult, QuestionType, Question, User } from '../types';
import { 
    Play, ShieldCheck, Hash, CheckCircle, Camera, Activity, 
    Clock, ShieldAlert, ChevronRight, ChevronLeft, 
    Shield, UserCheck, Mic, Laptop, Search, Loader2, AlertTriangle, 
    Trophy, Monitor, LogOut, Globe, ArrowRight, PlayCircle
} from 'lucide-react';
import confetti from 'canvas-confetti';

// --- CONSTANTS ---
const EXAM_LIST = [
    "NISM (Capital Markets)", "NCFM", "Graduate Record Examinations (GRE)", 
    "Test of English as a Foreign Language (TOEFL iBT)", "Graduate Management Admission Test (GMAT)", 
    "International English Language Testing System (IELTS)", "Microsoft Certification Exams", 
    "Amazon Web Services (AWS) Certification", "Cisco Certification Exams (CCNA)", 
    "Cisco Certification Exams (CCNP)", "Test of Professional Skills (TOPS) & Other Corporate Hiring Tests", 
    "Certifications by Google (Google Career Certificates)"
];

const MOCK_QUESTIONS: Question[] = [
    { id: 1, text: "In a stock market context, what does IPO stand for?", type: QuestionType.MCQ, options: ["Internal Profit Option", "Initial Public Offering", "International Payment Order", "Investment Portfolio Overhaul"], correctAnswer: "Initial Public Offering", difficulty: "Easy", explanation: "IPO is the first time a company sells stock to the public.", marks: 2 },
    { id: 2, text: "Which protocol is primarily used for secure communication over a computer network?", type: QuestionType.MCQ, options: ["HTTP", "FTP", "HTTPS", "SMTP"], correctAnswer: "HTTPS", difficulty: "Medium", explanation: "HTTPS encrypts communication between a browser and a server.", marks: 2 },
    { id: 3, text: "What is the primary function of a router in a network?", type: QuestionType.MCQ, options: ["To store data", "To route packets between networks", "To provide power to devices", "To display web pages"], correctAnswer: "To route packets between networks", difficulty: "Medium", explanation: "Routers forward data packets across network boundaries.", marks: 2 },
    { id: 4, text: "Cloud computing 'AWS' stands for what?", type: QuestionType.MCQ, options: ["Advanced Web Systems", "Amazon Web Services", "Apple Web Software", "Apex Wireless Solutions"], correctAnswer: "Amazon Web Services", difficulty: "Easy", explanation: "AWS is Amazon's cloud platform.", marks: 2 },
    { id: 5, text: "What is the standard port for SSH?", type: QuestionType.MCQ, options: ["21", "22", "80", "443"], correctAnswer: "22", difficulty: "Hard", explanation: "SSH typically uses port 22.", marks: 2 }
];

type PortalPhase = 'WELCOME' | 'VERIFY_APP' | 'IDENTITY_CAPTURE' | 'MATCHING' | 'INSTRUCTIONS' | 'ARENA' | 'SUBMITTING' | 'RESULT' | 'BLOCKED';

interface ExaminationCenterProps {
    user: User;
    onSaveResult: (result: TestResult) => void;
    onLogout: () => void; 
    globalTests?: any;
    onAddTest?: any;
}

const ExaminationCenter: React.FC<ExaminationCenterProps> = ({ user, onSaveResult, onLogout }) => {
    const [phase, setPhase] = useState<PortalPhase>('WELCOME');
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedExam, setSelectedExam] = useState('');
    const [appNumber, setAppNumber] = useState('');
    const [isAppVerified, setIsAppVerified] = useState(false);
    const [isVerifying, setIsVerifying] = useState(false);

    // Identity State
    const [captures, setCaptures] = useState<{ front: string | null; left: string | null; right: string | null }>({ front: null, left: null, right: null });
    const [matchingStatus, setMatchingStatus] = useState<'idle' | 'processing' | 'matched' | 'failed'>('idle');

    // Exam Arena State
    const [currentQIdx, setCurrentQIdx] = useState(0);
    const [answers, setAnswers] = useState<Record<number, string>>({});
    const [timeLeft, setTimeLeft] = useState(600); // 10 mins
    const [warnings, setWarnings] = useState(0);
    const [proctorStatus, setProctorStatus] = useState('Monitoring');
    const [aiWarning, setAiWarning] = useState<string | null>(null);

    const videoRef = useRef<HTMLVideoElement>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const lastViolationRef = useRef<number>(0);

    // --- HARDWARE KILLSWITCH AGENT ---
    useEffect(() => {
        const monitoringPhases: PortalPhase[] = ['IDENTITY_CAPTURE', 'MATCHING', 'ARENA'];
        if (!monitoringPhases.includes(phase) && streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }
    }, [phase]);

    useEffect(() => {
        return () => {
            if (streamRef.current) {
                streamRef.current.getTracks().forEach(track => track.stop());
                streamRef.current = null;
            }
        };
    }, []);

    const filteredExams = EXAM_LIST.filter(e => e.toLowerCase().includes(searchTerm.toLowerCase()));

    // --- KEYBOARD LOCKDOWN ---
    useEffect(() => {
        if (phase === 'ARENA') {
            const blockKeys = (e: KeyboardEvent) => {
                e.preventDefault();
                setAiWarning("KEYBOARD INPUT DETECTED: Mouse Use Only.");
                setTimeout(() => setAiWarning(null), 3000);
            };
            window.addEventListener('keydown', blockKeys);
            return () => window.removeEventListener('keydown', blockKeys);
        }
    }, [phase]);

    // --- FULLSCREEN ENFORCEMENT ---
    useEffect(() => {
        const handleFS = () => {
            if (!document.fullscreenElement && phase === 'ARENA') {
                setPhase('BLOCKED');
            }
        };
        document.addEventListener('fullscreenchange', handleFS);
        return () => document.removeEventListener('fullscreenchange', handleFS);
    }, [phase]);

    // --- PROCTORING AGENT ---
    useEffect(() => {
        let visionInterval: any;
        if (phase === 'ARENA' && streamRef.current) {
            visionInterval = setInterval(async () => {
                if (!videoRef.current) return;
                const canvas = document.createElement('canvas');
                canvas.width = 320; canvas.height = 240;
                const ctx = canvas.getContext('2d');
                if (!ctx) return;
                ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
                const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1];
                setProctorStatus('Scanning behavior...');
                try {
                    const res = await analyzeProctoringFrame(base64);
                    if (res.suspicious) {
                        triggerViolation(res.reason);
                    } else {
                        setAiWarning(null);
                    }
                } catch (e) {}
                setProctorStatus('Active AI Monitoring');
            }, 8000);
        }
        return () => clearInterval(visionInterval);
    }, [phase]);

    const triggerViolation = (reason: string) => {
        if (Date.now() - lastViolationRef.current < 4000) return;
        lastViolationRef.current = Date.now();

        setWarnings(prev => {
            const next = prev + 1;
            setAiWarning(`Please look straight at the screen. This is warning #${next}.`);
            if (next >= 5) setPhase('BLOCKED');
            return next;
        });
    };

    const startCamera = async () => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ video: true, audio: true });
            streamRef.current = stream;
            if (videoRef.current) videoRef.current.srcObject = stream;
        } catch (e) {
            alert("Camera access is mandatory to enter the hall.");
        }
    };

    const handleVerifyApp = () => {
        if (!appNumber.trim()) {
            alert("Please enter your application number.");
            return;
        }
        setIsVerifying(true);
        setTimeout(() => {
            setIsVerifying(false);
            setIsAppVerified(true);
            setTimeout(() => {
                setPhase('IDENTITY_CAPTURE');
                startCamera();
            }, 1200);
        }, 1500);
    };

    const captureView = (view: 'front' | 'left' | 'right') => {
        if (!videoRef.current) return;
        const canvas = document.createElement('canvas');
        canvas.width = 640; canvas.height = 480;
        canvas.getContext('2d')?.drawImage(videoRef.current, 0, 0);
        setCaptures(prev => ({ ...prev, [view]: canvas.toDataURL('image/jpeg') }));
    };

    const runIdentityMatch = () => {
        setPhase('MATCHING');
        setMatchingStatus('processing');
        setTimeout(() => {
            setMatchingStatus('matched');
            setTimeout(() => setPhase('INSTRUCTIONS'), 1500);
        }, 3000);
    };

    const startTest = () => {
        document.documentElement.requestFullscreen().then(() => {
            setPhase('ARENA');
        }).catch(() => alert("Full-screen required."));
    };

    const finalizeTest = () => {
        setPhase('SUBMITTING');
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        setTimeout(() => {
            onLogout(); 
        }, 2000);
    };

    useEffect(() => {
        let t: any;
        if (phase === 'ARENA' && timeLeft > 0) t = setInterval(() => setTimeLeft(p => p - 1), 1000);
        else if (phase === 'ARENA' && timeLeft === 0) finalizeTest();
        return () => clearInterval(t);
    }, [phase, timeLeft]);

    return (
        <div className="min-h-screen bg-slate-50 dark:bg-slate-950 flex flex-col font-sans transition-colors duration-500 relative">

            {/* PORTAL HEADER */}
            <header className="sticky top-0 z-[100] w-full bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200 dark:border-slate-800 px-8 py-4 flex justify-between items-center shadow-sm">
                <div className="flex items-center gap-2">
                    <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center shadow-indigo-600/20 shadow-lg">
                        <ShieldCheck className="w-5 h-5 text-white" />
                    </div>
                    <span className="text-xl font-black bg-gradient-to-r from-indigo-600 to-purple-600 bg-clip-text text-transparent">
                        MyClassroom
                    </span>
                    <span className="ml-3 px-2 py-0.5 bg-slate-100 dark:bg-slate-800 rounded text-[10px] font-black text-slate-500 uppercase tracking-widest border border-slate-200 dark:border-slate-700">
                        Exam Mode
                    </span>
                </div>

                <button 
                    onClick={onLogout}
                    className="flex items-center gap-2 px-4 py-2 bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 border border-red-200 dark:border-red-800 rounded-xl font-bold text-sm hover:bg-red-100 transition-all shadow-sm active:scale-95 group"
                >
                    <LogOut className="w-4 h-4 group-hover:-translate-x-1 transition-transform" />
                    Log Out
                </button>
            </header>

            {/* WELCOME PHASE - REDESIGNED EXAM LISTING */}
            {phase === 'WELCOME' && (
                <div className="flex-1 flex flex-col items-center py-12 px-6 animate-fade-in max-w-5xl mx-auto w-full">
                    <div className="text-center mb-10">
                        <div className="w-16 h-16 bg-emerald-100 dark:bg-emerald-900/30 rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-sm border border-emerald-200 dark:border-emerald-800/50">
                            <Activity className="w-8 h-8 text-emerald-600 dark:text-emerald-400" />
                        </div>
                        <h1 className="text-4xl font-black text-slate-900 dark:text-white tracking-tight mb-3">Live Assessments</h1>
                        <p className="text-slate-500 dark:text-slate-400 text-lg">Browse and attempt ongoing examinations currently active in your region.</p>
                    </div>

                    <div className="w-full max-w-3xl mb-12">
                        <div className="relative group">
