// --- PROCTORING AGENT ---
export const analyzeProctoringFrame = async (imageBase64: string): Promise<{ suspicious: boolean, reason: string }> => {
  const ai = await getClient();
  const prompt = `
    Analyze this webcam frame of a candidate taking a high-stakes online exam. 
    STRICT INVIGILATION MODE - ACT AS A HUMAN PROCTOR.

    Detect and flag the following violations as 'suspicious': true:
    1. **Face Out of Range**: No face detected, face disappears briefly, or camera is obstructed.
    2. **Multiple Faces**: More than one person present in the frame (Zero Tolerance).
    3. **Unusual Head/Gaze Movement**: Looking away repeatedly or for an extended duration.

    If suspicious: true, return exactly one of these reason strings:
    - Return "FACE_NOT_FOUND" if face is missing or obstructed.
    - Return "MULTIPLE_FACES" if 2+ faces are detected.
    - Return "UNUSUAL_MOVEMENT" for looking away or significant turning.

    Otherwise return 'suspicious': false with reason: "OK".
    Return JSON.
  `;

  const schema = {
    type: Type.OBJECT,
    properties: {
      suspicious: { type: Type.BOOLEAN },
      reason: { type: Type.STRING }
    },
    required: ["suspicious", "reason"]
  };

  try {
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: {
            parts: [
                { inlineData: { mimeType: 'image/jpeg', data: imageBase64 } },
                { text: prompt }
            ]
        },
        config: { responseMimeType: "application/json", responseSchema: schema }
      });

      const text = response.text;
      if (!text) return { suspicious: false, reason: "No response" };
      return JSON.parse(text) as { suspicious: boolean, reason: string };
  } catch (e) {
      console.error("Proctoring Error", e);
      return { suspicious: false, reason: "AI Service Error" };
  }
};

