    const ai = await getClient();

    const context = questions.map(q => ({
        id: q.id,
        question: q.text,
        correctAnswer: q.correctAnswer,
        modelAnswer: q.modelAnswer,
        studentAnswer: answers[q.id] || "No Answer",
        maxMarks: q.marks || 1
    }));

    const prompt = `
