            {/* ARENA PHASE */}
            {phase === 'ARENA' && (
                <div className="flex-1 flex flex-col lg:flex-row gap-6 p-6 animate-fade-in overflow-hidden relative select-none">
                    {/* PROFESSIONAL AI WARNING OVERLAY */}
                    {aiWarning && (
                        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[100] bg-slate-900/95 backdrop-blur-md text-white px-10 py-5 rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.3)] animate-slide-up font-bold text-center border-2 border-indigo-500/30 flex items-center gap-4 max-w-[90vw]">
                            <AlertTriangle className="w-6 h-6 text-yellow-400 flex-shrink-0" /> {aiWarning}
                        </div>
                    )}

                    <div className="w-full lg:w-72 flex flex-col gap-4">
                        <div className="bg-black rounded-[2rem] aspect-video overflow-hidden border-2 border-red-600 relative shadow-2xl">
                            <video ref={videoRef} autoPlay muted playsInline className="w-full h-full object-cover scale-x-[-1]" />
                            <div className="absolute top-3 left-3 flex items-center gap-2 bg-black/50 backdrop-blur-md px-2 py-1 rounded-full text-[8px] font-black text-white">
                                <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-pulse"></div> AI INVIGILATOR LIVE
                            </div>
                        </div>

                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800">
                             <div className="flex justify-between items-center text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">
                                <span>Integrity Meter</span>
                                <span className="text-red-600">{warnings}/5 Flags</span>
                             </div>
                             <div className="flex gap-1.5">
                                {[1,2,3,4,5].map(i => <div key={i} className={`h-2 flex-1 rounded-full transition-all duration-700 ${i <= warnings ? 'bg-red-600 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.5)]' : 'bg-slate-100 dark:bg-slate-800'}`}></div>)}
                             </div>
                             <p className="mt-4 text-[10px] text-slate-400 font-bold uppercase flex items-center gap-2"><Laptop className="w-3 h-3"/> Keypad Locked</p>
                        </div>

                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800 flex-1">
                            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6 flex items-center gap-2"><Activity className="w-4 h-4 text-indigo-500" /> Exam Progress</h4>
                            <div className="grid grid-cols-4 gap-2">
                                {MOCK_QUESTIONS.map((_, i) => (
                                    <button key={i} onClick={() => setCurrentQIdx(i)} className={`aspect-square rounded-xl font-black text-xs transition-all ${currentQIdx === i ? 'bg-indigo-600 text-white shadow-lg' : answers[MOCK_QUESTIONS[i].id] ? 'bg-green-100 text-green-700' : 'bg-slate-50 dark:bg-slate-800 text-slate-400'}`}>
                                        {i + 1}
                                    </button>
                                ))}
                            </div>
                        </div>
                    </div>

                    <div className="flex-1 flex flex-col gap-6 overflow-hidden">
                        <div className="bg-white dark:bg-slate-900 p-6 rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-slate-800 flex justify-between items-center">
                            <div>
                                <h3 className="text-xl font-black dark:text-white line-clamp-1">{selectedExam}</h3>
                                <p className="text-[10px] text-slate-400 font-bold uppercase mt-1 tracking-widest">Application: {appNumber}</p>
                            </div>
                            <div className="flex items-center gap-4 bg-red-50 dark:bg-red-900/30 px-8 py-3 rounded-2xl border border-red-100/50 shadow-inner">
                                <Clock className="w-6 h-6 text-red-600 animate-pulse" />
                                <span className="text-3xl font-mono font-black text-red-600 tabular-nums">
                                    {Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}
                                </span>
                            </div>
                        </div>

                        <div className="flex-1 bg-white dark:bg-slate-900 p-12 rounded-[3.5rem] shadow-2xl border border-slate-100 dark:border-slate-800 overflow-y-auto flex flex-col relative group">
                            <div className="flex-1">
                                <div className="flex gap-6 mb-12">
                                    <span className="text-8xl font-black text-indigo-600/5 select-none leading-none -mt-3">{currentQIdx + 1}</span>
                                    <h2 className="text-3xl font-black dark:text-white leading-tight">{MOCK_QUESTIONS[currentQIdx].text}</h2>
                                </div>
                                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-4xl">
                                    {MOCK_QUESTIONS[currentQIdx].options?.map((opt, oIdx) => (
                                        <button key={oIdx} onClick={() => setAnswers({...answers, [MOCK_QUESTIONS[currentQIdx].id]: opt})} className={`w-full text-left p-8 rounded-[2rem] border-4 transition-all flex items-center gap-6 group overflow-hidden ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/20 shadow-inner' : 'border-slate-50 dark:border-slate-800/50 hover:bg-slate-50'}`}>
                                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-lg transition-all ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'bg-indigo-600 text-white shadow-lg' : 'bg-slate-100 dark:bg-slate-700 text-slate-400 group-hover:bg-indigo-100'}`}>{String.fromCharCode(65 + oIdx)}</div>
                                            <span className={`text-lg font-bold ${answers[MOCK_QUESTIONS[currentQIdx].id] === opt ? 'text-indigo-900 dark:text-white' : 'text-slate-600 dark:text-slate-300'}`}>{opt}</span>
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div className="mt-12 flex justify-between items-center border-t-2 border-slate-50 dark:border-slate-800 pt-10">
                                <button disabled={currentQIdx === 0} onClick={() => setCurrentQIdx(currentQIdx - 1)} className="p-5 bg-slate-100 dark:bg-slate-800 rounded-2xl disabled:opacity-10 transition-all hover:bg-slate-200"><ChevronLeft className="w-8 h-8 text-slate-400" /></button>
                                <div className="flex gap-4">
                                    {currentQIdx === MOCK_QUESTIONS.length - 1 ? (
                                        <button onClick={finalizeTest} className="px-12 bg-green-600 text-white font-black text-xl rounded-[2rem] shadow-xl hover:bg-green-700 transition-all active:scale-95">Finish Session</button>
                                    ) : (
                                        <button onClick={() => setCurrentQIdx(currentQIdx + 1)} className="px-10 bg-indigo-600 text-white rounded-[2rem] shadow-xl hover:bg-indigo-700 transition-all active:scale-95"><ChevronRight className="w-8 h-8" /></button>
                                    )}
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* SUBMITTING PHASE */}
            {phase === 'SUBMITTING' && (
                <div className="flex-1 flex flex-col items-center justify-center p-6 animate-fade-in text-center">
                    <Loader2 className="w-16 h-16 text-indigo-600 animate-spin mb-8" />
                    <h2 className="text-4xl font-black dark:text-white uppercase tracking-tighter">Finalizing Response</h2>
                    <p className="text-slate-500">Encrypting behavioral logs and indexing results...</p>
                </div>
            )}

            {/* BLOCKED PHASE */}
            {phase === 'BLOCKED' && (
                <div className="flex-1 flex flex-col items-center justify-center p-8 text-center animate-fade-in">
                    <div className="w-24 h-24 bg-red-100 rounded-[2rem] flex items-center justify-center mb-8 animate-bounce">
                        <AlertTriangle className="w-12 h-12 text-red-600" />
                    </div>
                    <h2 className="text-4xl font-black text-red-600 uppercase tracking-tighter mb-4">Session Terminated</h2>
                    <p className="text-slate-500 max-w-md mb-10 leading-relaxed font-bold">
                        {terminationMessage || "A security protocol violation was detected. Unauthorized actions have resulted in immediate termination of this assessment."}
                    </p>
                    <button onClick={() => window.location.reload()} className="px-10 py-5 bg-red-600 text-white rounded-[2rem] font-black text-xl hover:bg-red-700 shadow-2xl transition-all">Exit Hall</button>
                </div>
            )}
        </div>
    );
};

export default ExaminationCenter;

import React, { useState, useEffect, useRef } from 'react';
import { generateTest, analyzeProctoringFrame } from '../services/gemini';
import { TestData, QuestionType, User, UserRole, TestResult, Classroom } from '../types';
import { 
    CheckCircle, XCircle, AlertCircle, Award, Loader2, Clock, 
    ShieldAlert, Plus, Play, Eye, FileText, Globe, Camera, Mic, 
    Users, AlertTriangle, ScreenShare, Activity, Lock, Gavel, Monitor, X, CheckSquare, Square, Megaphone
} from 'lucide-react';
import confetti from 'canvas-confetti';

interface TestManagerProps {
  user: User;
  globalTests: TestData[];
  testHistory: TestResult[];
  classrooms: Classroom[];
  onAddTest: (test: TestData) => void;
  onSaveResult: (result: TestResult) => void;
  onDeployTest: (testId: string, classIds: string[]) => void;
  onPublishResults: (testId: string) => void; // New prop
  onExit?: () => void;
}

const TestManager: React.FC<TestManagerProps> = ({ user, globalTests, testHistory, classrooms, onAddTest, onSaveResult, onDeployTest, onPublishResults, onExit }) => {
  // Navigation & View State
  const [view, setView] = useState<'LIST' | 'CREATE_SELECT' | 'CREATE_AI' | 'CREATE_MANUAL' | 'TAKE' | 'SUBMITTING' | 'RESULT' | 'DEPLOY' | 'PROCTOR_DASHBOARD' | 'PERMISSIONS'>('LIST');

  // Teacher State
  const [topic, setTopic] = useState('');
  const [qCount, setQCount] = useState(5);
  const [loading, setLoading] = useState(false);
  const [manualTitle, setManualTitle] = useState('');
  const [manualQuestions, setManualQuestions] = useState<{text: string, answer: string}[]>([]);
  const [currentManualQ, setCurrentManualQ] = useState('');
  const [selectedTestId, setSelectedTestId] = useState<string | null>(null);

  // Multi-select Deployment
  const [selectedClassIds, setSelectedClassIds] = useState<string[]>([]);

  // Student State
  const [joinCode, setJoinCode] = useState('');
  const [activeTest, setActiveTest] = useState<TestData | null>(null);
  const [answers, setAnswers] = useState<Record<number, string>>({});
  const [timeLeft, setTimeLeft] = useState(0);
  const [permissionsGranted, setPermissionsGranted] = useState(false);

  // PROCTORING STATE
  const [violationLog, setViolationLog] = useState<string[]>([]);
  const [warnings, setWarnings] = useState(0);
  const [proctorStatus, setProctorStatus] = useState('Monitoring');
  const [audioLevel, setAudioLevel] = useState(0);

  const videoRef = useRef<HTMLVideoElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const analyserRef = useRef<AnalyserNode | null>(null);
  const lastViolationRef = useRef<number>(0);

  // --- TEACHER ACTIONS ---

  const handleAiGenerate = async () => {
    setLoading(true);
    try {
      const data = await generateTest(topic, 'Medium', qCount);
      const newTest: TestData = { 
          ...data, 
          id: Date.now().toString(),
          creatorId: user.id, 
          status: 'DRAFT',
          accessCode: Math.floor(100000 + Math.random() * 900000).toString(),
          settings: { ...data.settings, proctoring: true },
          resultsPublished: false
      };
      onAddTest(newTest);
      setView('LIST');
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const addManualQuestion = () => {
      if(!currentManualQ) return;
      setManualQuestions([...manualQuestions, { text: currentManualQ, answer: '' }]);
      setCurrentManualQ('');
  }

  const saveManualTest = () => {
      const newTest: TestData = {
          id: Date.now().toString(),
          title: manualTitle,
          subject: 'General',
          creatorId: user.id,
          // Fix: Added missing properties to TestSettings within saveManualTest to satisfy the interface definition.
          settings: { 
            timeLimitMinutes: 30, 
            proctoring: true, 
            requireWebcam: true, 
            preventTabSwitch: true, 
            allowCalculator: false, 
            allowInternet: false, 
            adaptive: false, 
            shuffleQuestions: false 
          },
          status: 'DRAFT',
          accessCode: Math.floor(100000 + Math.random() * 900000).toString(),
          questions: manualQuestions.map((q, i) => ({
              id: i,
              text: q.text,
              type: QuestionType.SHORT,
              explanation: 'Manual question',
              difficulty: 'Medium'
          })),
          resultsPublished: false
      };
      onAddTest(newTest);
      setView('LIST');
      setManualTitle('');
      setManualQuestions([]);
  };

  const openDeployModal = (testId: string) => {
      setSelectedTestId(testId);
      setSelectedClassIds([]); // Reset
      setView('DEPLOY');
  }

  const toggleClassSelection = (classId: string) => {
      setSelectedClassIds(prev => 
          prev.includes(classId) 
              ? prev.filter(id => id !== classId) 
              : [...prev, classId]
      );
  };

  const handleDeploy = () => {
      if (selectedTestId && selectedClassIds.length > 0) {
          onDeployTest(selectedTestId, selectedClassIds);
          setView('LIST');
          setSelectedClassIds([]);
      }
  };

  const handleAnnounce = (testId: string) => {
      if(confirm("Are you sure? All students will be notified and can see their results immediately.")) {
          onPublishResults(testId);
      }
  };

  // --- STUDENT ACTIONS ---

  const requestPermissions = async () => {
      try {
          // Request permissions with specific constraints for mobile & sensitivity
          const stream = await navigator.mediaDevices.getUserMedia({ 
              video: { 
                  facingMode: 'user', // Prefer front camera for self-view on mobile
                  width: { ideal: 640 },
                  height: { ideal: 480 }
              }, 
              audio: { 
                  echoCancellation: true, 
                  noiseSuppression: true,
                  autoGainControl: true 
              } 
          });
          streamRef.current = stream;
          setPermissionsGranted(true);
          setView('TAKE');
      } catch (e) {
          console.error("Permission Error:", e);
          alert("Permission Denied: Camera and Microphone are required. Please check your browser settings or ensure no other app is using the camera.");
      }
  }

  const joinLiveTest = () => {
      const test = globalTests.find(t => t.accessCode === joinCode || t.id === 'demo-photosynthesis'); // Demo hack
      if (test) {
          // Check if already taken
          const taken = testHistory.find(r => r.testId === test.id);
          if (taken) {
              alert("You have already submitted this test. Please wait for results.");
              return;
          }
          initiateTest(test);
      } else {
          alert("Invalid Code or Test Not Live");
      }
  }

  const initiateTest = (test: TestData) => {
      setActiveTest(test);
      setViolationLog([]);
      setWarnings(0);
      setPermissionsGranted(false);
      setAnswers({});
      setView('PERMISSIONS');
  }

  const viewMyResult = (test: TestData) => {
      // Find the specific result
      const result = testHistory.find(r => r.testId === test.id);
      if (result) {
          // Set state to simulate the "RESULT" view logic
          setActiveTest(test);
          setAnswers(result.answers);
          setWarnings(result.warningsCount || 0);
          setViolationLog(result.violationLog || []);
          setView('RESULT');
      }
  };

  // --- PROCTORING LOGIC ---

  useEffect(() => {
    // Tab Switching Detection (Requirement: Immediate Auto-Submit)
    const handleVisibilityChange = () => {
        if (document.hidden && view === 'TAKE') {
            triggerViolation("Tab/Window Change Detected (Auto-Submit Triggered)", true);
        }
    };

    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => {
        document.removeEventListener("visibilitychange", handleVisibilityChange);
        // Clean up stream on unmount or view change
        if (streamRef.current && view !== 'TAKE') {
            streamRef.current.getTracks().forEach(track => track.stop());
            if (audioContextRef.current) {
                audioContextRef.current.close();
                audioContextRef.current = null;
            }
        }
    };
  }, [view]);

  // Initialize Sensors when in TAKE mode
  useEffect(() => {
      let visionInterval: any;
      let audioInterval: any;

      if (view === 'TAKE' && permissionsGranted && streamRef.current) {
          // 1. Setup Video
          if (videoRef.current) {
              videoRef.current.srcObject = streamRef.current;
          }

          // 2. Setup Audio
          if (!audioContextRef.current) {
              try {
                  const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
                  audioContextRef.current = new AudioContext();
                  analyserRef.current = audioContextRef.current.createAnalyser();
                  const source = audioContextRef.current.createMediaStreamSource(streamRef.current);
                  source.connect(analyserRef.current);
                  analyserRef.current.fftSize = 256;
                  analyserRef.current.smoothingTimeConstant = 0.5; // Smooth out jitter

                  // Resume context if suspended (common on mobile browsers)
                  if (audioContextRef.current.state === 'suspended') {
                      audioContextRef.current.resume();
                  }
              } catch (e) {
                  console.error("Audio Context Error", e);
              }
          }

          // 3. Start AI Vision Loop (Every 5 seconds)
          visionInterval = setInterval(checkVision, 5000);

          // 4. Start Audio Loop (Every 200ms for high responsiveness)
          audioInterval = setInterval(checkAudio, 200);
      }

      return () => {
          clearInterval(visionInterval);
          clearInterval(audioInterval);
      };
  }, [view, permissionsGranted]);

  const checkAudio = () => {
      if (!analyserRef.current) return;
      const dataArray = new Uint8Array(analyserRef.current.frequencyBinCount);
      analyserRef.current.getByteFrequencyData(dataArray);

      // Calculate average volume
      const average = dataArray.reduce((a, b) => a + b) / dataArray.length;
      setAudioLevel(average);

      // SENSITIVITY SETTING:
      // A threshold of 15 is usually just above the noise floor of a quiet room.
      // This will detect whispering or low talking.
      const THRESHOLD = 15; 

      if (average > THRESHOLD) {
          triggerViolation("Audio Alert: Voice/Whispering Detected");
      }
  };

  const checkVision = async () => {
      if (!videoRef.current) return;

      // Draw video to low-res canvas for analysis
      const canvas = document.createElement('canvas');
      canvas.width = 320;
      canvas.height = 240;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
      const base64 = canvas.toDataURL('image/jpeg', 0.6).split(',')[1]; // Compress jpg

      setProctorStatus('AI Analyzing...');
      try {
          // Send to Gemini
          const result = await analyzeProctoringFrame(base64);

          // Fix: Update to check result.action as analyzeProctoringFrame returns {action, message?}
          if (result.action !== 'NONE') {
              triggerViolation(`AI Vision Alert: ${result.message || result.action}`, result.action === 'CRITICAL_VIOLATION' || result.action === 'TERMINATE_EXAM');
          }
      } catch (e) {
          console.error("Vision Check Failed", e);
      } finally {
          setProctorStatus('Monitoring');
      }
  };

  const triggerViolation = (reason: string, isSevere: boolean = false) => {
      if (view !== 'TAKE') return;

      const now = Date.now();
      // Debounce: Avoid spammed warnings within 5 seconds for the same reason
      if (!isSevere && (now - lastViolationRef.current < 5000)) {
          return;
      }

      lastViolationRef.current = now;
      const log = `${new Date().toLocaleTimeString()}: ${reason}`;
      setViolationLog(prev => [...prev, log]);

      if (isSevere) {
           alert(`SEVERE VIOLATION: ${reason}. Test will be auto-submitted.`);
           submitTest(true);
           return;
      }

      setWarnings(prev => {
          const newCount = prev + 1;

          // Warning Toast
          const toast = document.createElement('div');
          toast.className = "fixed top-4 left-1/2 transform -translate-x-1/2 bg-red-600 text-white px-6 py-3 rounded-lg shadow-2xl z-[100] animate-bounce font-bold border-2 border-white text-center";
          toast.innerText = `⚠️ WARNING (${newCount}/5): ${reason}`;
          document.body.appendChild(toast);
          setTimeout(() => toast.remove(), 4000);

          if (newCount >= 5) {
              // Use timeout to allow state update to reflect before alert
              setTimeout(() => {
                  alert("Maximum warnings (5/5) reached. System is auto-submitting your test.");
                  submitTest(true);
              }, 500);
          }
          return newCount;
      });
  };

  const handleTimerTick = () => {
      if (timeLeft > 0) {
          setTimeLeft(prev => prev - 1);
      } else if (timeLeft === 0 && view === 'TAKE') {
          submitTest(true);
      }
  };

  useEffect(() => {
    let timer: any;
    if (view === 'TAKE' && activeTest) {
        if (timeLeft === 0 && activeTest.settings.timeLimitMinutes) {
             setTimeLeft(activeTest.settings.timeLimitMinutes * 60);
        }
        timer = setInterval(handleTimerTick, 1000);
    }
    return () => clearInterval(timer);
  }, [timeLeft, view, activeTest]);

  const submitTest = (auto = false) => {
    if (!activeTest) return;

    // Switch to SUBMITTING state
    setView('SUBMITTING');

    // Stop camera & audio
    if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
    }
    if (audioContextRef.current) {
        audioContextRef.current.close();
    }

    // Simulate "Uploading" delay for realism
    setTimeout(() => {
        let score = 0;
        activeTest.questions.forEach(q => {
          if (q.type === QuestionType.MCQ && answers[q.id] === q.correctAnswer) {
            score++;
          }
        });

        const result: TestResult = {
          testId: activeTest.id,
          studentId: user.id,
          score,
          maxScore: activeTest.questions.length,
          answers,
          dateTaken: new Date().toISOString(),
          status: 'COMPLETED',
          violationLog,
          warningsCount: warnings,
          autoSubmitted: auto
        };

        onSaveResult(result);

        confetti({
            particleCount: 150,
            spread: 70,
            origin: { y: 0.6 }
        });

        if (onExit) {
            onExit();
        } else {
            setView('LIST'); // Return to list instead of result directly (Wait for publish)
        }
    }, 2000);
  };

  // --- RENDERERS ---

  if (user.role === UserRole.TEACHER) {
      return (
          <div className="p-6 max-w-6xl mx-auto">
              {view === 'LIST' && (
                  <div className="space-y-6">
                      <div className="flex justify-between items-center">
                          <h2 className="text-3xl font-bold dark:text-white">Test Management</h2>
                          <div className="flex gap-2">
