  if (!user || view === AppView.LOGIN) {
      return (
        <div className="min-h-screen bg-gray-50 dark:bg-gray-900 flex items-center justify-center p-4">
            <div className="max-w-5xl w-full bg-white dark:bg-gray-800 rounded-3xl shadow-2xl overflow-hidden grid grid-cols-1 md:grid-cols-2 min-h-[650px] animate-fade-in border border-gray-100 dark:border-gray-700">
                <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-12 text-white flex flex-col justify-between relative overflow-hidden">
                    <div className="absolute top-0 left-0 w-full h-full opacity-10 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>

                    <div className="relative z-10">
                        <div className="w-12 h-12 bg-white/20 rounded-xl flex items-center justify-center backdrop-blur-sm mb-6">
                           <Sparkles className="w-6 h-6 text-yellow-300" />
                        </div>
                        <h1 className="text-4xl font-bold mb-4">MyClassroom AI</h1>
                        <p className="text-indigo-100 text-lg leading-relaxed">
                            The next generation of personalized learning. Powered by Gemini 3.0.
                        </p>
                    </div>

                    <div className="space-y-4 relative z-10">
                        <div className="flex items-center gap-4 bg-white/10 p-4 rounded-xl backdrop-blur-sm border border-white/10">
                            <div className="bg-white/20 p-2 rounded-lg"><Play className="w-6 h-6 text-white" /></div>
                            <div>
                                <h3 className="font-bold">AI Video Lessons</h3>
                                <p className="text-xs text-indigo-200">Instant educational content generation</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-4 bg-white/10 p-4 rounded-xl backdrop-blur-sm border border-white/10">
                            <div className="bg-white/20 p-2 rounded-lg"><ShieldCheck className="w-6 h-6 text-white" /></div>
                            <div>
                                <h3 className="font-bold">Enterprise Proctoring</h3>
                                <p className="text-xs text-indigo-200">Secure AI-monitored testing environment</p>
                            </div>
                        </div>
                        <div className="flex items-center gap-4 bg-white/10 p-4 rounded-xl backdrop-blur-sm border border-white/10">
                            <div className="bg-white/20 p-2 rounded-lg"><FileText className="w-6 h-6 text-white" /></div>
                            <div>
                                <h3 className="font-bold">Smart Revision</h3>
                                <p className="text-xs text-indigo-200">Auto-generated smart notes & study paths</p>
                            </div>
                        </div>
                    </div>
                </div>

                <div className="p-12 flex flex-col justify-center bg-white dark:bg-gray-800">
                    {loginStep === 'DETAILS' ? (
                        <>
                            <h2 className="text-3xl font-bold text-gray-900 dark:text-white mb-2 tracking-tight">Access Hub</h2>
                            <p className="text-gray-500 mb-8">Identify your role and sign in to your dashboard.</p>

                            <div className="grid grid-cols-3 gap-4 mb-8">
                                <button 
                                    onClick={() => setLoginRole(UserRole.STUDENT)}
                                    className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${loginRole === UserRole.STUDENT ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300 ring-4 ring-indigo-500/10' : 'border-gray-200 dark:border-gray-700 hover:border-indigo-300'}`}
                                >
                                    <UserCircle className="w-8 h-8" />
                                    <span className="font-bold text-sm">Student</span>
                                </button>

                                <button 
                                    onClick={handleGuestExamLogin}
                                    className="p-4 rounded-2xl border-2 border-gray-200 dark:border-gray-700 flex flex-col items-center gap-2 transition-all hover:border-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 group"
                                >
                                    <ShieldCheck className="w-8 h-8 text-gray-400 group-hover:text-red-500" />
                                    <span className="font-bold text-sm">Exam Hub</span>
                                </button>

                                <button 
                                    onClick={() => setLoginRole(UserRole.TEACHER)}
                                    className={`p-4 rounded-2xl border-2 flex flex-col items-center gap-2 transition-all ${loginRole === UserRole.TEACHER ? 'border-indigo-600 bg-indigo-50 dark:bg-indigo-900/20 text-indigo-700 dark:text-indigo-300 ring-4 ring-indigo-500/10' : 'border-gray-200 dark:border-gray-700 hover:border-indigo-300'}`}
                                >
                                    <GraduationCap className="w-8 h-8" />
                                    <span className="font-bold text-sm">Teacher</span>
                                </button>
                            </div>

                            <button 
                                onClick={handleGoogleLogin}
                                disabled={isGoogleLoading}
                                className="w-full py-4 bg-white dark:bg-gray-700 border-2 border-gray-200 dark:border-gray-600 rounded-xl font-bold flex items-center justify-center gap-3 hover:bg-gray-50 dark:hover:bg-gray-600 transition-all mb-6 shadow-sm disabled:opacity-50"
                            >
                                {isGoogleLoading ? <Loader2 className="w-5 h-5 animate-spin" /> : <Globe className="w-5 h-5 text-blue-600" />}
                                Continue with Google
                            </button>

                            <div className="relative mb-6">
                                <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-gray-200 dark:border-gray-700"></div></div>
                                <div className="relative flex justify-center text-xs uppercase tracking-widest font-bold"><span className="px-2 bg-white dark:bg-gray-800 text-gray-400">or use email</span></div>
                            </div>

                            <form onSubmit={handleEmailLogin} className="space-y-4 mb-8">
                                <div className="relative group">
                                    <Mail className="absolute left-4 top-4 text-gray-400 group-focus-within:text-indigo-600 transition-colors w-5 h-5" />
                                    <input 
                                        type="email" 
                                        required
                                        value={loginEmail}
                                        onChange={e => setLoginEmail(e.target.value)}
                                        placeholder="Email Address"
                                        className="w-full pl-12 pr-4 py-4 rounded-xl border border-gray-200 dark:border-gray-600 dark:bg-gray-700 dark:text-white focus:ring-2 focus:ring-indigo-500 transition-all outline-none font-medium"
                                    />
                                </div>
                                <button 
                                    type="submit"
                                    disabled={isLoggingIn}
                                    className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-xl shadow-lg flex items-center justify-center gap-2 disabled:opacity-70 transition-all active:scale-95 text-lg uppercase tracking-wider"
                                >
                                    {isLoggingIn ? <Loader2 className="w-5 h-5 animate-spin" /> : "Verify & Access"}
                                </button>
                            </form>
                        </>
                    ) : (
                        <div className="animate-fade-in">
                            <button onClick={() => setLoginStep('DETAILS')} className="text-gray-400 hover:text-indigo-600 font-bold text-sm mb-6 flex items-center gap-1 transition-colors">
                                <X className="w-4 h-4" /> Change Account
