                                <div className="relative group">
                                    <Lock className="absolute left-4 top-4 text-gray-400 group-focus-within:text-indigo-600 transition-colors w-5 h-5" />
                                    <input 
                                        value={loginOtp}
                                        onChange={e => setLoginOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
                                        placeholder="Enter Code (e.g. 123456)"
                                        className="w-full pl-12 pr-4 py-5 rounded-2xl border-2 border-gray-100 dark:border-gray-700 dark:bg-gray-900 dark:text-white focus:border-indigo-600 transition-all outline-none font-black text-2xl tracking-[0.5em] text-center"
                                        maxLength={6}
                                        required
                                    />
