                                <button 
                                    type="submit"
                                    disabled={isLoggingIn || loginOtp.length < 4}
                                    className="w-full py-5 bg-indigo-600 hover:bg-indigo-700 text-white font-black rounded-2xl shadow-2xl flex items-center justify-center gap-3 disabled:opacity-30 transition-all active:scale-95 text-xl"
