                                    {isLoggingIn ? <Loader2 className="w-6 h-6 animate-spin" /> : <><CheckCircle className="w-6 h-6"/> Start Session</>}
                                </button>
                                <p className="text-center text-sm text-gray-400">
                                    Didn't receive the code? <button type="button" className="text-indigo-600 font-bold hover:underline" onClick={() => addNotification('OTP Resent', 'A new code has been sent.', 'INFO')}>Resend Code</button>
                                </p>
                            </form>
                        </div>
                    )}

