                        <button onClick={() => handleLogin(UserRole.STUDENT)} className="py-3 px-4 rounded-xl bg-gray-50 dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600 text-gray-600 dark:text-white font-bold text-xs transition-all uppercase tracking-widest border border-gray-200 dark:border-gray-600">
                            Student Path
